insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الِاثْنَيْنِ إِلَى قُبَاءَ، حَتَّى إِذَا كُنَّا فِي بَنِي سَالِمٍ وَقَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى بَابِ عِتْبَانَ فَصَرَخَ بِهِ، فَخَرَجَ يَجُرُّ إِزَارَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْجَلْنَا الرَّجُلَ". فَقَالَ عِتْبَانُ: يَا رَسُولَ اللهِ، أَرَأَيْتَ الرَّجُلَ يُعْجَلُ عَنِ امْرَأَتِهِ وَلَمْ يُمْنِ، مَاذَا عَلَيْهِ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا الْمَاءُ مِنَ الْمَاءِ". (م)', 'അബ്ദുർറഹ്മാനുബ്നു അബീ സഈദിനിൽ ഖുദ്‌രി, തന്റെ പിതാവിൽ നിന്ന്: അദ്ദേഹം (പിതാവ്) പറയുന്നു: നബി(സ)യുടെ കൂടെ ഒരു തിങ്കളാഴ്ച ഞാൻ ഖുബാഇലേക്ക് പുറപ്പെട്ടു. സാലിം ഗോത്രക്കാരുടെ അടുത്തെത്തിയപ്പോൾ നബി(സ) ഇത്ബാൻ എന്നയാളുടെ വീടിനടുത്ത് നിന്ന് അദ്ദേഹത്തെ ഉച്ചത്തിൽ വിളിച്ചു. ഉടുതുണി വലിച്ചിഴച്ച് അദ്ദേഹം നബി(സ)യുടെ അടുത്തേക്ക് വന്നു. നബി(സ) പറഞ്ഞു: "ഇയാളോട് നാം ധൃതികാണിച്ചിരിക്കുന്നു (സംയോഗത്തിലേർപ്പെട്ടുകൊണ്ടിരിക്കെ അത് പൂർത്തിയാക്കാൻ നാം അയാളെ അനുവദിച്ചില്ല)." അപ്പോൾ ഇത്ബാൻ ചോദിച്ചു: "അല്ലാഹുവിന്റെ റസൂലേ ഒരാൾ തന്റെ ഭാര്യയുമായി സംയോഗത്തിലേർപ്പെടുകയും സ്ഖലിക്കാത്ത അവസ്ഥയിൽ ധൃതികാണിച്ച് സംയോഗം നിർത്തുകയും ചെയ്താൽ അയാൾ എന്താണ് ചെയ്യേണ്ടത്? നബി(സ) പറഞ്ഞു: വെള്ളം (കുളിക്കൽ) നിർബ്ബന്ധമാകുന്നത് വെള്ളം (ഇന്ദ്രിയം പുറപ്പെട്ടാൽ) കാരണത്താൽ മാത്രമാണ്. (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ عَنْ أَبِيهِ', null, null, null, array['م']::text[], array['മു']::text[], null, null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا الْمَاءُ مِنَ الْمَاءِ فِي الِاحْتِلَامِ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): സ്വപ്ന ദർശനമുണ്ടായിട്ടുണ്ടെങ്കിലും അതിൽ സ്ഖലനം സംഭവിച്ചിട്ടുണ്ടെങ്കിൽ മാത്രമേ കുളി നിർബ്ബന്ധമാവുകയുള്ളൂ. (തി)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തി']::text[], null, null, 199, 199, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: اخْتُلِفَ فِي ذَلِكَ رَهْطٌ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، فَقَالَ الْأَنْصَارِيُّونَ: لَا يَجِبُ الْغُسْلُ إِلَّا مِنَ الدَّفْقِ أَوْ مِنَ الْمَاءِ. وَقَالَ الْمُهَاجِرُونَ: بَلْ إِذَا خَالَطَ فَقَدْ وَجَبَ الْغُسْلُ. قَالَ: قَالَ أَبُو مُوسَى: فَأَنَا أَشْفِيكُمْ مِنْ ذَلِكَ، فَقُمْتُ فَاسْتَأْذَنْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَأُذِنَ لِي، فَقُلْتُ [لَهَا]: يَا أُمَّاهْ – أَوْ يَا أُمَّ الْمُؤْمِنِينَ – إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنْ شَيْءٍ وَإِنِّي أَسْتَحْيِيكِ. فَقَالَتْ: لَا تَسْتَحْيِي أَنْ تَسْأَلَنِي عَمَّا كُنْتَ سَائِلًا عَنْهُ أُمَّكَ الَّتِي وَلَدَتْكَ، فَإِنَّمَا أَنَا أُمُّكَ. قُلْتُ: فَمَا يُوجِبُ الْغُسْلَ؟ قَالَتْ: عَلَى الْخَبِيرِ سَقَطْتَ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، "إِذَا جَلَسَ بَيْنَ شُعَبِهَا الْأَرْبَعِ، وَمَسَّ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ". (م)', 'അബൂമൂസാ(റ): ഈ വിഷയത്തിൽ (ഭാര്യയുമായുള്ള ക്രീഡ കാരണത്താൽ കുളി നിർബന്ധമാവൽ) മുഹാജിറുകളിലെയും അൻസാറുകളിലെയും ഒരു സംഘമാളുകൾ പരസ്പരം ഭിന്നാഭിപ്രായത്തിലായി. അൻസാറുകൾ പറഞ്ഞു: ഇന്ദ്രിയ സ്ഖലനം കൊണ്ടേ കുളി നിർബന്ധമാവൂ. മുഹാജിറുകൾ പറഞ്ഞു: അങ്ങനെയല്ല. പുരുഷ ലിംഗം സ്ത്രീയുടെ യോനിയിൽ പ്രവേശിച്ചാൽതന്നെ കുളി നിർബന്ധമാകും. ഈ സമയത്ത് അബൂമൂസാ(റ) പറഞ്ഞു: ഞാൻ ഈ വിഷയത്തിൽ നിങ്ങൾക്ക് തൃപ്തികരമായ ഒരു തീരുമാനം അറിയിച്ചു തരാം. ഉടനെ ഞാൻ എഴുന്നേറ്റ് ആഇശ(റ)യുടെ അടുക്കൽ പോവുകയും മഹതിയോട് സമ്മതം ചോദിക്കുകയും ചെയ്തു. എനിക്ക് അനുവാദം ലഭിച്ചപ്പോൾ ഞാൻ ചോദിച്ചു: എന്റെ ഉമ്മാ! - മുഴുവൻ സത്യവിശ്വാസികളുടെയും മാതാവേ -  ഞാൻ അവിടുത്തോട് ഒരു കാര്യം ചോദിക്കാനാഗ്രഹിക്കുന്നു. ചോദിക്കാൻ എനിക്ക് ലജ്ജ തോന്നുന്നുമുണ്ട്. അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: നിന്നെ പ്രസവിച്ച ഉമ്മയോട് ചോദിക്കാറുണ്ടായിരുന്ന ഏതിനെക്കുറിച്ച് ചോദിക്കാനും നീ മടി കാണിക്കരുത്. കാരണം ഞാൻ നിന്റെ ഉമ്മയാണ്. ഞാൻ ചോദിച്ചു കുളി നിർബന്ധമാക്കുന്ന കാര്യമെന്താണ്?. മഹതി പറഞ്ഞു: ഈ വിഷയത്തിൽ നന്നായറിയുന്ന ആളുടെ അടുത്ത് തന്നെയാണ് നീ എത്തിപ്പെട്ടത്. റസൂൽ(സ) പറഞ്ഞു: ഒരു പുരുഷൻ തന്റെ ഭാര്യയുടെ കൈ കാലുകൾക്കിടയിൽ ഇരിക്കുകയും പുരുഷലിംഗം സ്ത്രീയുടെ യോനിയിൽ പ്രവേശിപ്പിക്കുകയും ചെയ്താൽ കുളി നിർബന്ധമായി. (മു)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لَهَا', null, 199, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ عَنْ أُمِّ كُلْثُومٍ، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: إِنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُجَامِعُ أَهْلَهُ ثُمَّ يُكْسِلُ، هَلْ عَلَيْهِمَا الْغُسْلُ؟ وَعَائِشَةُ جَالِسَةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَفْعَلُ ذَلِكَ أَنَا وَهَذِهِ ثُمَّ نَغْتَسِلُ". (م)', 'ഉമ്മുകുൽസൂമിൽ നിന്ന് ജാബിറുബ്നു അബ്ദില്ലാ(റ): അവർ പ്രവാചക പത്നി ആഇശ (റ)യിൽ നിന്ന്: അവർ പറഞ്ഞു: ഒരാൾ തന്റെ ഭാര്യയുമായി ബന്ധപ്പെടുകയും ഇന്ദ്രിയ സ്ഖലനം സംഭവിക്കും മുമ്പ് നിർത്തുകയും ചെയ്താൽ അവർക്ക് കുളി നിർബന്ധമാമോ എന്ന് ഒരാൾ പ്രവാചകരോട് ചോദിച്ചു. ഈ സമയം ആഇശ(റ) അവിടെ ചാരിയിരിക്കുന്നുണ്ടായിരുന്നു. പ്രവാചകൻ(സ) പറഞ്ഞു: ഞാനും ആഇശ(റ)യും അങ്ങിനെ ചെയ്യാറുണ്ട്. എന്നിട്ട് കുളിക്കുകയും ചെയ്യാറുണ്ട്. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ عَنْ أُمِّ كُلْثُومٍ، عَنْ عَائِشَةَ', 'ഉമ്മുകുൽസൂമിൽ നിന്ന് ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ فَقَدْ وَجَبَ الْغُسْلُ، فَعَلْتُهُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاغْتَسَلْنَا. وَفِي رِوَايَةٍ: "إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ وَجَبَ الْغُسْلُ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'ആഇശ(റ): പുരുഷലിംഗം സ്ത്രീയുടെ യോനിയിൽ പ്രവേശിക്കുന്നതോടെ കുളി നിർബ്ബന്ധമായി. ഞാനും പ്രവാചകനും അപ്രകാരം ചെയ്യുകയും ശേഷം കുളിക്കുകയും ചെയ്യാറുണ്ട്. മറ്റൊരു റിപ്പോർട്ടിൽ ലിംഗം യോനിയിൽ പ്രവേശിച്ചാൽ കുളി നിർബന്ധമായി. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=5), 1, 'وَفِي رِوَايَةٍ: "إِذَا جَاوَزَ الْخِتَانُ الْخِتَانَ وَجَبَ الْغُسْلُ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'മറ്റൊരു നിവേദനിൽ ലിംഗം യോനിയിൽ പ്രവേശിച്ചാൽ കുളി നിർബന്ധമായി. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി. (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّمَا كَانَ الْمَاءُ مِنَ الْمَاءِ رُخْصَةً فِي أَوَّلِ الْإِسْلَامِ، ثُمَّ نُهِيَ عَنْهَا. حَسَنٌ صَحِيحٌ. (ت)', 'ഉബയ്യ്ബ്നു കഅ്ബ്(റ): ഇന്ദ്രിയ സ്ഖലനം സംഭവിച്ചിട്ടുണ്ടെങ്കിൽ മാത്രമേ കുളി നിർബന്ധമാവൂ എന്ന ഇളവ് ഇസ്ലാമിന്റെ ആദ്യകാലത്ത് ഉണ്ടായിരുന്നു. പിന്നീട് അത് നിരോധിക്കപ്പെട്ടു (ദുർബ്ബലപ്പെടുത്തി). ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യ്ബ്നു കഅ്ബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, 'ദുർബ്ബലപ്പെടുത്തി', 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا جَلَسَ بَيْنَ شُعَبِهَا الْأَرْبَعِ ثُمَّ جَهَدَهَا فَقَدْ وَجَبَ الْغُسْلُ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: ഒരാൾ തന്റെ ഭാര്യയുടെ കൈ കാലുകൾക്കിടയിൽ ഇരിക്കുകയും അവളുമായി സഹവസിക്കുകയും ചെയ്താൽ കുളി നിർബന്ധമായി. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 200, 200, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ أُبَيَّ رَضِيَ اللهُ عَنْهُ أَخْبَرَهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ إِنَّمَا جُعِلَ ذَلِكَ رُخْصَةً لِلنَّاسِ فِي أَوَّلِ الْإِسْلَامِ لِقِلَّةِ الثِّيَابِ، ثُمَّ أَمَرَ بِالْغُسْلِ وَنَهَى عَنْ ذَلِكَ. قَالَ أَبُو دَاوُدَ: "يَعْنِي الْمَاءَ مِنَ الْمَاءِ" (د)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): ഉബയ്യുബ്നു കഅ്ബ് അദ്ദേഹത്തെ അറിയിച്ചു: തിരുമേനി(സ) പറഞ്ഞു: ഈ ഇളവ് ജനങ്ങൾക്ക് നിയമമാക്കപ്പെട്ടത് ഇസ്ലാമിന്റെ ആദ്യഘട്ടത്തിൽ വസ്ത്രത്തിന്റെ ദൗർലഭ്യത ഉണ്ടായിരുന്നതിനാലാണ്. പിന്നെ അത് വിലക്കുകയും കുളിക്കാൻ കൽപ്പിക്കുകയും ചെയ്തു. അബൂദാവൂദ് പറയുന്നു: ഇവിടെ ഇളവ് എന്നതുകൊണ്ട് ഉദ്ദേശിച്ചത് ''സ്ഖലിച്ചാൽ മാത്രമേ കുളിക്കേണ്ടതുള്ളൂ'' എന്ന കാര്യമാണ്. (ദ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 200, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ إِسْحَاقَ [بْنِ أَبِي طَلْحَةَ] عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ جَاءَتْ أُمُّ سُلَيْمٍ – وَهِيَ جَدَّةُ إِسْحَقَ – إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ لَهُ وَعَائِشَةُ عِنْدَهُ: يَا رَسُولَ اللهِ الْمَرْأَةُ تَرَى مَا يَرَى الرَّجُلُ فِي الْمَنَامِ، فَتَرَى مِنْ نَفْسِهَا مَا يَرَى الرَّجُلُ مِنْ نَفْسِهِ؟ فَقَالَتْ عَائِشَةُ: يَا أُمَّ سُلَيْمٍ، فَضَحْتِ النِّسَاءَ تَرِبَتْ يَمِينُكِ. فَقَالَ لِعَائِشَةَ: "بَلْ أَنْتِ فَتَرِبَتْ يَمِينُكِ، نَعَمْ فَلْتَغْتَسِلْ يَا أُمَّ سُلَيْمٍ إِذَا رَأَتْ ذَاكِ". (م)', 'അനസി(റ)ൽ നിന്ന് ഇസ്ഹാഖ്ബ്നി അബീ ത്വൽഹ(റ): അദ്ദേഹം പറഞ്ഞു: ആഇശ(റ) പ്രവാചകന്റെ അടുത്തുള്ളപ്പോൾ ഇസ്ഹാഖി(റ)ന്റെ വലിയുമ്മ ഉമ്മുസുലൈം പ്രവാചകന്റെ അടുത്തേക്ക് വന്ന് ചോദിച്ചു: പ്രവാചകരേ, പുരുഷന് സ്വപ്ന സ്ഖലനം ഉണ്ടാകുന്നതുപോലെ സ്ത്രീക്ക് സ്വപ്ന സ്ഖലം ഉണ്ടായാൽ അവൾ എന്ത് ചെയ്യണം?. അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: ഉമ്മുസുലൈമേ! നീ സ്ത്രീകളെ വഷളാക്കി, നിന്റെ വലംകൈ മണ്ണ് പുരണ്ടിരിക്കുന്നു! (ച്ഛെ! വളരെ മോശമായിപ്പോയി). അപ്പോൾ ആയിശ(റ)യോട് തിമേനി(സ) പറഞ്ഞു: ആയിശാ! നിന്റെ വലംകൈ മണ്ണ് പുരണ്ടിരിക്കുന്നു! (നീയാണ് മോശമായിപ്പോയത്); ഉമ്മുസുലൈമേ! അങ്ങനെ സ്വപ്നം കണ്ടവൾ കുളിക്കട്ടെ. (മു)', 'إِسْحَاقَ [بْنِ أَبِي طَلْحَةَ] عَنْ أَنَسٍ', 'അനസി(റ)', null, null, array['م']::text[], array['മു']::text[], 'بْنِ أَبِي طَلْحَةَ', null, 201, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَتْ أُمُّ سُلَيْمٍ بِنْتُ مِلْحَانَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ اللهَ لَا يَسْتَحْيِي مِنَ الْحَقِّ، فَهَلْ عَلَى الْمَرْأَةِ – تَعْنِي غُسْلًا – إِذَا هِيَ رَأَتْ فِي الْمَنَامِ مِثْلَ مَا يَرَى الرَّجُلُ؟ قَالَ: "نَعَمْ، إِذَا هِيَ رَأَتِ الْمَاءَ فَلْتَغْتَسِلْ". قَالَتْ أُمُّ سَلَمَةَ: قُلْتُ لَهَا: فَضَحْتِ النِّسَاءَ يَا أُمَّ سُلَيْمٍ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഉമ്മുസലമ(റ): മിൽഹാന്റെ പുത്രി ഉമ്മുസുലൈം പ്രവാചക സന്നിധിയിലേക്ക് വന്ന് ചോദിച്ചു: പ്രവാചകരേ! അല്ലാഹു സത്യത്തിൽ ലജ്ജ കാണിക്കുകയില്ല. പുരുഷൻ കാണുന്നത് പോലെ സ്ത്രീ സ്വപ്നം കണ്ടാൽ അവൾ കുളിക്കേണ്ടതുണ്ടോ?. പ്രവാചകൻ(സ) പറഞ്ഞു: "അതെ! വെള്ളം (ഇന്ദ്രിയം പുറപ്പെട്ടതായി) കണ്ടെത്തിയിട്ടുണ്ടെങ്കിൽ കുളിക്കണം." ഉമ്മുസലമ(റ) പറയുന്നു: ഞാൻ ഉമ്മുസുലൈമിനോട് പറഞ്ഞു: നീ സ്ത്രീകളെ വഷളാക്കിയിരിക്കുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമിദി പറയുന്നു) (ബു,മു,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 201, 201, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَدْنَيْتُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غُسْلَهُ مِنَ الْجَنَابَةِ، فَغَسَلَ كَفَّيْهِ مَرَّتَيْنِ أَوْ ثَلَاثًا، ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ، ثُمَّ أَفْرَغَ بِهِ عَلَى فَرْجِهِ وَغَسَلَهُ بِشِمَالِهِ، ثُمَّ ضَرَبَ بِشِمَالِهِ الْأَرْضَ فَدَلَكَهَا دَلْكًا شَدِيدًا، ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ أَفْرَغَ عَلَى رَأْسِهِ ثَلَاثَ حَفَنَاتٍ مِلْءَ كَفِّهِ، ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ، ثُمَّ تَنَحَّى عَنْ مَقَامِهِ ذَلِكَ فَغَسَلَ رِجْلَيْهِ، ثُمَّ أَتَيْتُهُ بِالْمِنْدِيلِ، فَرَدَّهُ. (م)', 'പ്രവാചക പത്നി മൈമൂന(റ): വലിയ അശുദ്ധിയിൽ നിന്നും കുളിക്കാനുള്ള വെള്ളം പ്രവാചകന്റെ അടുത്തേക്ക് ഞാൻ വെച്ച് കൊടുത്തു. പ്രവാചകൻ (സ) ആദ്യം തന്റെ മുൻ കൈകൾ രണ്ടോ മൂന്നോ പ്രാവശ്യം കഴുകി വൃത്തിയാക്കി. പിന്നീട് പാത്രത്തിൽ നിന്ന് കൈ കൊണ്ട് വെള്ളം കോരിയെടുത്ത് ഗുഹ്യസ്ഥാനത്തൊഴിക്കുകയും ഇടത് കൈ കൊണ്ട് കഴുകുകയും ചെയ്തു. പിന്നെ ഇടത് കൈ നിലത്ത് നന്നായി തേച്ചുരച്ച് വൃത്തിയാക്കുകയും ചെയ്തു. അതിനു ശേഷം നിസ്കാരത്തിന് വുദൂ ചെയ്യുകയും പോലെ വുദൂ ചെയ്തു. പിന്നെ മൂന്ന് പ്രാവശ്യം തലക്ക് മുകളിലൂടെ കൈ നിറയെ വെള്ളമൊഴിച്ചു. പിന്നീട് മറ്റു ശരീര ഭാഗങ്ങൾ കഴുകി. അതിന് ശേഷം ആ സ്ഥലത്ത് നിന്ന് അൽപം മാറി രണ്ട് കാലുകളും കഴുകി വൃത്തിയാക്കുകയും ചെയ്തു. ഈ സമയം ഞാൻ പ്രവാചകന്റെയടുത്തേക്ക് തോർത്തുമായി പോയി. പക്ഷേ അത് തിരിച്ച് നൽകുകയാണ് ചെയ്തത്. (മു,തു,ദ)', 'مَيْمُونَةَ', 'പ്രവാചക പത്നി മൈമൂന(റ)', null, null, array['م']::text[], array['മു','തു','ദ']::text[], null, null, 201, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ خَالَتِهِ مَيْمُونَةَ – رَضِيَ اللهُ عَنْهُمْ– قَالَتْ: وَضَعْتُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غُسْلًا، فَاغْتَسَلَ مِنَ الْجَنَابَةِ: فَأَكْفَأَ الْإِنَاءَ بِشِمَالِهِ عَلَى يَمِينِهِ، فَغَسَلَ كَفَّيْهِ، ثُمَّ أَدْخَلَ يَدَهُ فِي الْإِنَاءِ فَأَفَاضَ عَلَى فَرْجِهِ، ثُمَّ دَلَكَ بِيَدِهِ الْحَائِطَ، أَوِ الْأَرْضَ، ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ، وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ، ثُمَّ أَفَاضَ عَلَى رَأْسِهِ ثَلَاثًا، ثُمَّ أَفَاضَ عَلَى سَائِرِ جَسَدِهِ، ثُمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹത്തിന്റെ പിതൃവ്യയായ മൈമൂന(റ) പറഞ്ഞു: നബി(സ)ക്ക് ഞാൻ കുളിക്കാനുള്ള വെള്ളം വെച്ച് കൊടുത്തു. റസൂൽ(സ) ജനാബത്ത് കുളി നിർവ്വഹിച്ചു. ഇടത് കൈകൊണ്ട് വലത് കയ്യിലേക്ക് പാത്രം ചെരിച്ച് മുൻ കൈ രണ്ടും കഴുകി. പിന്നെ പാത്രത്തിൽ കയ്യിട്ട് ഗുഹ്യസ്ഥാനം വെള്ള മൊഴിച്ച് കഴുകി. പിന്നെ കൈ ചുമരിലോ തറയിലോ തേച്ചുരച്ച് കഴുകി. വായിൽ വെള്ളം കൊപ്ലിക്കുകയും മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുകയും ചെയ്തു. മുഖവും കയ്യും കഴുകി. പിന്നെ തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിച്ചു. പിന്നീട് ശരീരത്തിന്റെ മറ്റ് ഭാഗങ്ങളിലേക്ക് വെള്ള മൊഴിക്കുകയും അൽപം മാറി രണ്ട് കാലുകളും കഴുകി. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ، عَنْ خَالَتِهِ مَيْمُونَةَ –', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 202, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَغْتَسِلَ مِنَ الْجَنَابَةِ بَدَأَ فَغَسَلَ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا الْإِنَاءَ، ثُمَّ غَسَلَ فَرْجَهُ، وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ يُشَرِّبُ شَعْرَهُ الْمَاءَ، ثُمَّ يَحْثِي عَلَى رَأْسِهِ ثَلَاثَ حَثَيَاتٍ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) ജനാബത്ത് കുളി നിർവ്വഹിക്കാൻ ഉദ്ദേശിച്ചാൽ പാത്രത്തിൽ ഇടുന്നതിന് മുമ്പ് രണ്ട് കയ്യും കഴുകും. പിന്നെ ഗുഹ്യസ്ഥാനം കഴുകി നിസ്കാരത്തിന് വുദൂ ചെയ്യുന്ന പോലെ വുദൂ എടുക്കുകയും രോമങ്ങളൊക്കെ നന്നായി നനക്കുകയും ചെയ്യും. പിന്നീട് തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ള മൊഴിക്കും. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 202, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَا وَأَخُوهَا مِنَ الرَّضَاعَةِ، فَسَأَلَهَا عَنْ غُسْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْجَنَابَةِ؟ فَدَعَتْ بِإِنَاءٍ قَدْرِ الصَّاعِ، فَاغْتَسَلَتْ، وَبَيْنَنَا وَبَيْنَهَا سِتْرٌ، وَأَفْرَغَتْ عَلَى رَأْسِهَا ثَلَاثًا، قَالَ: وَكَانَ أَزْوَاجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْخُذْنَ مِنْ رُءُوسِهِنَّ حَتَّى تَكُونَ كَالْوَفْرَةِ. (م)', 'അബൂസലമത്ത് ബ്നു അബ്ദിർറഹ്മാൻ(റ): ആഇശ(റ)യുടെ അടുത്തേക്ക് ഞാനും മഹതിയുടെ മുലകുടിബന്ധത്തിലുള്ള ഒരു സഹോദരനും പോയി. ശരീരാശുദ്ധി വന്നാലുള്ള പ്രവാചകന്റെ കുളിയെ കുറിച്ച് ആഇശ(റ)യോട് ചോദിച്ചു. ഒരു സ്വാഇന്റെ വലുപ്പത്തിലുള്ള ഒരു പാത്രം കൊണ്ടു വരാനാവശ്യപ്പെട്ടു. പിന്നീട് മഹതി കുളിക്കുകയും ചെയ്തു. ഞങ്ങൾക്കിടയിൽ മറയുണ്ടായിരുന്നു. മഹതി തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിച്ചു. പ്രവാചക പത്നിമാർ തലമുടി വെട്ടി ചെറുതാക്കാറുണ്ടായിരുന്നു. (മു)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ قَالَ', 'അബൂസലമത്ത് ബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 202, 202, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سُئِلَتْ عَنْ غُسْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَدَعَتْ بِإِنَاءٍ نَحْوٍ مِنْ صَاعٍ فَاغْتَسَلَتْ وَأَفَاضَتْ عَلَى رَأْسِهَا وَبَيْنَنَا وَبَيْنَهَا وَبَيْنَ السَّائِلِ حِجَابٌ. (خ)', 'ആഇശ(റ): അവർ ഒരു ദിവസം പ്രവാചക(സ)ന്റെ ജനാബത്ത് കുളിയെ പ്പറ്റി ചോദിക്കപ്പെട്ടു. ഒരു സ്വാഇന്റെ വലിപ്പത്തിലുള്ള ഒരു പാത്രം അവർ കൊണ്ടു അവരുടെ തലയുടെ മുകളിലൂടെ വെള്ളമൊഴിച്ച് കുളിക്കുകയും ചെയ്തു. ആഇശ(റ)ക്കും ചോദ്യകർത്താവിനു മിടയിൽ ഒരു മറയുണ്ടായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَهُ رَجُلٌ عَنِ الْغُسْلِ فَقَالَ: يَكْفِيكَ صَاعٌ، فَقَالَ: رَجُلٌ مَا يَكْفِينِي فَقَالَ: جَابِرٌ كَانَ يَكْفِي مَنْ هُوَ أَوْفَى مِنْكَ شَعَرًا وَخَيْرٌ مِنْكَ، ثُمَّ أَمَّنَا فِي ثَوْبٍ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹത്തോട് ഒരു ദിവസം ഒരാൾ (ജനാബത്തു) കുളിയെ കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിനക്ക് ഒരു സ്വാഅ് (വെള്ളം) മതി. അപ്പോൾ അയാൾ പറഞ്ഞു: "എനിക്കത് പോരാ." അപ്പോൾ ജാബിർ(റ) പറഞ്ഞു: ''നിന്നേക്കാൾ രോമം നിറഞ്ഞവനും ഉത്തമനുമായ ആൾക്ക് (പ്രവാചക(സ)ന്) ഒരു സ്വാഅ് മതിയാകാറുണ്ടായിരുന്നു.'' പിന്നെ അവർക്കദ്ദേഹം ഒരു വസ്ത്ര മണിഞ്ഞ് നേതൃത്വം നൽകി. (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهَا:أَنَّهَا لَمَّا كَانَ عَامُ الْفَتْحِ أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِأَعْلَى مَكَّةَ، قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى غُسْلِهِ، فَسَتَرَتْ عَلَيْهِ فَاطِمَةُ، ثُمَّ أَخَذَ ثَوْبَهُ فَالْتَحَفَ بِهِ، ثُمَّ صَلَّى ثَمَانَ رَكَعَاتٍ سُبْحَةَ الضُّحَى. (م)', 'അബൂത്വാലിബിന്റെ പുത്രി ഉമ്മുഹാനിഅ്(റ): മക്കാ വിജയ ദിവസം അവർ പ്രവാചക(സ)ന്റെ അടുത്തേക്ക് ചെന്നു. പ്രവാചകൻ മക്കയിലെ മുകൾഭാഗത്തായിരുന്നു. പ്രവാചകനപ്പോൾ കുളിക്കാനെഴുന്നേറ്റു നിന്നു. ഫാത്വിമ(റ) നബി(സ)ക്ക് മറച്ച് കൊടുത്തു. നബി(സ) പിന്നീട് തന്റെ വസ്ത്രമെടുത്ത് ശരീരം പൊതിഞ്ഞു. പിന്നീട് എട്ട് റക്അത്ത് ളുഹാ നിസ്കരിക്കുകയും ചെയ്തു. (മു)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'അബൂത്വാലിബിന്റെ പുത്രി ഉമ്മുഹാനിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 203, 203, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنْ مُحَمَّدٍ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ أَحَادِيثَ، مِنْهَا: وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَانَتْ بَنُو إِسْرَائِيلَ يَغْتَسِلُونَ عُرَاةً يَنْظُرُ بَعْضُهُمْ إِلَى سَوْأَةِ بَعْضٍ، وَكَانَ مُوسَى عَلَيْهِ السَّلَامُ يَغْتَسِلُ وَحْدَهُ، فَقَالُوا: وَاللهِ مَا يَمْنَعُ مُوسَى أَنْ يَغْتَسِلَ مَعَنَا إِلَّا أَنَّهُ آدَرُ، قَالَ: فَذَهَبَ مَرَّةً يَغْتَسِلُ، فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ فَفَرَّ الْحَجَرُ بِثَوْبِهِ، قَالَ: فَجَمَحَ مُوسَى بِإِثْرِهِ يَقُولُ: ثَوْبِي حَجَرُ ثَوْبِي حَجَرُ، حَتَّى نَظَرَتْ بَنُو إِسْرَائِيلَ إِلَى سَوْأَةِ مُوسَى، قَالُوا وَاللهِ مَا بِمُوسَى مِنْ بَأْسٍ، فَقَامَ الْحَجَرُ حَتَّى نُظِرَ إِلَيْهِ، [قَالَ: فَأَخَذَ ثَوْبَهُ] فَطَفِقَ بِالْحَجَرِ ضَرْبًا". قَالَ أَبُو هُرَيْرَةَ: وَاللهِ إِنَّهُ بِالْحَجَرِ نَدَبٌ، سِتَّةٌ أَوْ سَبْعَةٌ، ضَرْبُ مُوسَى بِالْحَجَرِ. (م)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ മുഹമ്മദ്(സ) ധാരാളം ഹദീസുകൾ പറഞ്ഞു തന്നിട്ടുണ്ട്. അതിൽ പെട്ട ഒന്നാണിത്. റസൂൽ (സ) പറഞ്ഞു: ഇസ്റാഈല്യർ നഗ്നരായി പരസ്പരം ഗുഹ്യ സ്ഥാനത്തേക്ക് നോക്കി യായിരുന്നു കുളിച്ചിരുന്നത്. എന്നാൽ മൂസാ(അ) ഒറ്റക്കായിരുന്നു കുളിച്ചിരുന്നത്. അതിനാൽ ജനങ്ങൾ പറഞ്ഞു: മൂസാ നമ്മോട് കൂടെ കുളിക്കാത്തത് അദ്ദേഹം വലിയ വൃഷ്ണമുള്ള ആളായതിനാലാണ്. പ്രവാചകൻ(സ) തുടരുന്നു: മൂസാ(അ) ഒരു പ്രാവശ്യം കുളിക്കാൻ പോയി. വസ്ത്രങ്ങൾ ഒരു കല്ലിൻ മേലായിരുന്നു വെച്ചത്. പക്ഷേ കല്ല് വസ്ത്രവുമായി ഓടി. മൂസാ(അ) അപ്പോൾ മുട്ട് കുത്തിനിന്ന് പറഞ്ഞു: കല്ലേ! എന്റെ വസ്ത്രം, കല്ലേ! എന്റെ വസ്ത്രം, ഈ സമയം ബനൂ ഇസ്റാഈലുകാർ അദ്ദേഹത്തിന്റെ ഗുഹ്യ ഭാഗം കാണുകയും ചെയ്തു. അവർ പറഞ്ഞു: മൂസാക്ക് ഒരു കുഴപ്പവുമില്ല. ഈ സമയം കല്ല് നിൽക്കുകയും ചെയ്തു. അദ്ദേഹം വസ്ത്രം എടുത്തു. പിന്നീട് കല്ലിനെ അടിക്കാൻ തുടങ്ങി. അബൂഹുറൈറ(റ) പറഞ്ഞു: ആ കല്ലിൽ ആറോ ഏഴോ പാടുകളുണ്ടായിരുന്നു. മൂസാ(അ) അടിച്ചത് കാരണത്താലായിരുന്നുവത്. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ: فَأَخَذَ ثَوْبَهُ', null, 203, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَنْظُرُ الرَّجُلُ إِلَى عَوْرَةِ الرَّجُلِ، وَلَا الْمَرْأَةُ إِلَى عَوْرَةِ الْمَرْأَةِ، وَلَا يُفْضِي الرَّجُلُ إِلَى الرَّجُلِ فِي ثَوْبٍ وَاحِدٍ، وَلَا تُفْضِي الْمَرْأَةُ إِلَى الْمَرْأَةِ فِي الثَّوْبِ الْوَاحِدِ". (م)', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: പുരുഷൻ പുരുഷന്റെ ഔറത്തിലേക്കും, സ്ത്രീ സ്ത്രീയുടെ ഔറത്തിലേക്കും നോക്കാൻ പാടില്ല. രണ്ട് പുരുഷന്മാർ ഒറ്റ വസ്ത്രത്തിൽ ഒരുമിക്കാൻ പാടില്ല. രണ്ട് സ്ത്രീകൾ ഒറ്റ വസ്ത്രത്തിൽ ഒരുമിച്ചാവുകയും അരുത്. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിനിൽ ഖുദ്‌രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: يُحَدِّثُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْقُلُ مَعَهُمُ الْحِجَارَةَ لِلْكَعْبَةِ وَعَلَيْهِ إِزَارُهُ، فَقَالَ لَهُ الْعَبَّاسُ عَمُّهُ: يَا ابْنَ أَخِي، لَوْ حَلَلْتَ إِزَارَكَ فَجَعَلْتَهُ عَلَى مَنْكِبِكَ دُونَ الْحِجَارَةِ. قَالَ: فَحَلَّهُ فَجَعَلَهُ عَلَى مَنْكِبِهِ، فَسَقَطَ مَغْشِيًّا عَلَيْهِ، قَالَ: فَمَا رُئِيَ بَعْدَ ذَلِكَ الْيَوْمِ عُرْيَانًا. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) അവരോട് കൂടെ കഅ്ബക്ക് വേണ്ടി കല്ല് ചുമന്ന് കൊണ്ട് പോവുമായിരുന്നു. ഈ സമയത്ത് പ്രവാചകൻ അരവസ്ത്രം അണിഞ്ഞിരുന്നു. പ്രവാചകന്റെ പിതൃ സഹോദരൻ അബ്ബാസ്(റ) പറഞ്ഞു: സഹോദര പുത്രാ നീ തുണി അഴിച്ച് കല്ലിന് താഴെ തോളിൽ വെക്കുകയാണെങ്കിൽ (മെച്ചമായിരുന്നു). അപ്പോൾ പ്രവാചകൻ വസ്ത്രമഴിക്കുകയും തോളിൽ വെക്കുകയും ചെയ്തു. പക്ഷേ അവിടുന്ന് ബോധം കെട്ട് വീഴുകയാണ് ചെയ്തത്. ജാബിർ(റ) പറയുന്നു. പിന്നീടൊരിക്കലും തിരുമേനി(സ) നഗ്നനായി കാണപ്പെട്ടിട്ടില്ല. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ جُنُبًا، فَأَرَادَ أَنْ يَأْكُلَ أَوْ يَنَامَ تَوَضَّأَ وُضُوءَهُ [لِلصَّلَاةِ] (م)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ജനാബത്തുകാരനായിരിക്കെ ഉറങ്ങാനോ തിന്നാനോ ഉദ്ദേശിച്ചാൽ (നിസ്കാരത്തിനുള്ള) വുദൂ ചെയ്യുമായിരുന്നു. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'لِلصَّلَاةِ', null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ أَنَّهُ سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيَرْقُدُ أَحَدُنَا وَهُوَ جُنُبٌ؟ قَالَ: "نَعَمْ إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَرْقُدْ وَهُوَ جُنُبٌ". (خ)', 'ഉമറുബ്നു ഖത്വാബ്(റ): അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: ഒരാൾ ജനാബത്തുകാരനായിരിക്കെ ഉറങ്ങുമോ?. അദ്ദേഹം പറഞ്ഞു: അതെ, നിങ്ങൾ വുദൂ ചെയ്തിട്ടുണ്ടെങ്കിൽ ജനാബത്തുകാരനായി തന്നെ ഉറങ്ങട്ടെ. (ബു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നു ഖത്വാബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 204, 204, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ، رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيَنَامُ أَحَدُنَا وَهُوَ جُنُبٌ؟ قَالَ: "نَعَمْ، إِذَا تَوَضَّأَ". (ق,د,ت,ن,جه)', 'ഉമറി(റ)ൽ നിന്ന് ഇബ്നുഉമർ(റ): അദ്ദേഹം പ്രവാചക(സ)നോട് ചോദിച്ചു: ജനാബത്തുകാരനായി ഒരാൾക്ക് ഉറങ്ങാമോ?. പ്രവാചകൻ പറഞ്ഞു: "അതെ! വുദൂ ചെയ്താൽ." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ، عَنْ عُمَرَ،', 'ഉമറി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 204, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنْ وِتْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَذَكَرَ الْحَدِيثَ – قُلْتُ: كَيْفَ كَانَ يَصْنَعُ فِي الْجَنَابَةِ، أَكَانَ يَغْتَسِلُ قَبْلَ أَنْ يَنَامَ أَمْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، رُبَّمَا اغْتَسَلَ فَنَامَ، وَرُبَّمَا تَوَضَّأَ فَنَامَ. قُلْتُ: الْحَمْدُ للهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. (م)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഖൈസ്: ആഇശ(റ)യോട് ഞാൻ നബി(സ)യുടെ വിത്റിനെ കുറിച്ച് ചോദിച്ചു: അശുദ്ധിയുള്ള സമയത്ത് പ്രവാചകൻ(സ) എങ്ങനെയാണ് ചെയ്തിരുന്നത്?. ഉറങ്ങുന്നതിനു മുമ്പ് കുളിച്ചിരുന്നോ അതോ കുളിക്കുന്നതിനു മുമ്പ് ഉറങ്ങിയിരുന്നോ?. ആഇശ(റ) പറഞ്ഞു: എല്ലാം അവിടുന്ന് ചെയ്തിരുന്നു. ചിലപ്പോൾ കുളിച്ചുറങ്ങും, ചിലപ്പോൾ വുദൂ ചെയ്ത് ഉറങ്ങും. ഞാൻ പറഞ്ഞു: "ഇക്കാര്യത്തിൽ വിശാലത ചെയ്ത അല്ലാഹുവിന്ന് സർവ്വ സ്തുതിയും." (മു)', 'عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബീ ഖൈസ്', null, null, array['م']::text[], array['മു']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنَامُ وَهُوَ جُنُبٌ، وَلَا يَمَسُّ مَاءً. وَفِي رِوَايَةٍ: أَنَّهُ كَانَ يَتَوَضَّأُ قَبْلَ أَنْ يَنَامَ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ജനാബത്തുകാരനായിരിക്കെ വെള്ളം സ്പർശിക്ക പോലും ചെയ്യാതെ ഉറങ്ങാറുണ്ടായിരുന്നു. ഒരു റിപ്പോർട്ടിൽ പ്രവാചകൻ ഉറങ്ങുന്നതിനു മുമ്പ് വുദൂ ചെയ്തിരുന്നു എന്നുമുണ്ട്. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=25), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ كَانَ يَتَوَضَّأُ قَبْلَ أَنْ يَنَامَ. (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَهُوَ جُنُبٌ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "വലിയ അശുദ്ധിയുള്ള വേളയിൽ കെട്ടിനിൽക്കുന്ന വെള്ളത്തിൽ കുളിക്കരുത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَبُولَنَّ الرَّجُلُ فِي الْمَاءِ الدَّائِمِ ثُمَّ يَغْتَسِلُ مِنْهُ. أَوْ: يَتَوَضَّأُ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "കെട്ടി നിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിക്കുകയോ, ശേഷം അതിൽ നിന്ന് വുദൂ ചെയ്യുകയോ കുളിക്കുകയോ അരുത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُبَالَ فِي الْمَاءِ الدَّائِمِ ثُمَّ يُغْتَسَلَ فِيهِ مِنَ الْجَنَابَةِ. (ن)', 'അബൂഹുറൈറ(റ): "കെട്ടി നിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിക്കുന്നതും, ശേഷം അതിൽ നിന്നും ജനാബത്തിന് കുളിക്കുന്നതും പ്രവാചകൻ(സ) വിലക്കിയിരിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُبَالَ فِي الْمَاءِ الرَّاكِدِ ثُمَّ يُغْتَسَلَ مِنْهُ. (ن)', 'അബൂഹുറൈറ(റ): "കെട്ടി നിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിച്ച്, അതിൽ കുളിക്കുന്നതിനെ പ്രവാചകൻ(സ) വിലക്കിയിരിക്കുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 205, 205, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هريرة رَضِيَ اللهُ عَنْهُ قَالَ: "لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ الَّذِي لَا يَجْرِي ثُمَّ يَغْتَسِلُ مِنْهُ". (ن)', 'അബൂഹുറൈറ(റ): "നിങ്ങളിലാരും തന്നെ ഒഴുകാതെ കെട്ടി നിൽക്കുന്ന വെള്ളത്തിൽ മൂത്രമൊഴിച്ച് അതിൽ നിന്ന് കുളിക്കരുത്." (ന)', 'أَبِي هريرة', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَدْخُلِ الْحَمَّامَ إِلَّا بِمِئْزَرٍ". (ن)', 'ജാബിർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നവൻ അരയുടുപ്പില്ലാതെ കുളി മുറിയിലേക്ക് പ്രവേശിക്കാതിരിക്കട്ടെ." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَبْدِ اللهِ ابْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا، يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَدْعُو "اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا، اللَّهُمَّ نَقِّنِي مِنْهَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഔഫ്(റ): പ്രവാചകൻ(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, എന്നെ ദോഷങ്ങളിൽ നിന്നും പാപങ്ങളിൽ നിന്നും ശുദ്ധമാക്കേണമേ, എന്നെ വെള്ള വസ്ത്രം അഴുക്കിൽ നിന്ന് ശുദ്ധിയാക്കും പോലെ പാപങ്ങളിൽ നിന്ന് മോചിപ്പിക്കേണമേ. എന്നെ തണുത്ത വെള്ളം കൊണ്ടും മഞ്ഞ് കൊണ്ടും ഐസു കൊണ്ടും ശുദ്ധിയാക്കേണമേ. (ന)', 'عَبْدِ اللهِ ابْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു ഔഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ، اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ كَمَا يُطَهَّرُ الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ". (ن)', 'ഇബ്നുഅബീ ഔഫാ(റ): പ്രവാചകൻ(സ) പറയാറുണ്ടായിരുന്നു "തണുത്ത വെള്ളവും ഐസും മഞ്ഞും കൊണ്ട് എന്നെ ശുദ്ധിയാക്കണേ, എന്നെ വെള്ള വസ്ത്രം അഴുക്കിൽ നിന്ന് ശുദ്ധമാക്കപ്പെടും പോലെ ശുദ്ധമാക്കിത്തരണേ." (ന)', 'ابْنِ أَبِي أَوْفَى', 'ഇബ്നുഅബീ ഔഫാ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 206, 206, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: كَيْفَ كَانَ نَوْمُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْجَنَابَةِ، أَيَغْتَسِلُ قَبْلَ أَنْ يَنَامَ، أَوْ يَنَامُ قَبْلَ أَنْ يَغْتَسِلَ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ، رُبَّمَا اغْتَسَلَ فَنَامَ، وَرُبَّمَا تَوَضَّأَ فَنَامَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഖൈസ്(റ): ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചു: ജനാബത്ത് വേളയിൽ പ്രവാചകന്റെ ഉറക്ക് എങ്ങനെയായിരുന്നു. ഉറക്കിന് മുമ്പ് കുളിച്ചിരുന്നോ, അതോ കുളിക്ക് മുമ്പേ ഉറങ്ങിയിരുന്നോ?. അവർ പറഞ്ഞു: ''എല്ലാം (രണ്ടു വിധത്തിലും) ചെയ്തിരുന്നു. ചിലപ്പോൾ കുളിച്ച് ഉറങ്ങും, ചിലപ്പോൾ വുദൂ ചെയ്ത് ഉറങ്ങും.'' (ന)', 'عَبْدِ اللهِ بْنِ أَبِي قَيْسٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു അബീ ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 206, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ غُضَيْفِ بْنِ الْحَارِثِ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَسَأَلْتُهَا فَقُلْتُ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ مِنْ أَوَّلِ اللَّيْلِ أَوْ مِنْ آخِرِهِ؟ قَالَتْ: كُلُّ ذَلِكَ كَانَ، رُبَّمَا اغْتَسَلَ مِنْ أَوَّلِهِ وَرُبَّمَا اغْتَسَلَ مِنْ آخِرِهِ. قُلْتُ: الْحَمْدُ للهِ الَّذِي جَعَلَ فِي الْأَمْرِ سَعَةً. (ن)', 'ഉളൈഫ്ബ്നു ഹാരിസ്(റ): ഞാൻ ആഇശ(റ)യുടെ അടുത്ത് പോയി ചോദിച്ചു: പ്രവാചകൻ(സ) രാത്രിയുടെ ആദ്യഭാഗത്താണോ അവസാന ഭാഗത്താണോ കുളിച്ചിരുന്നത്?. അവർ പറഞ്ഞു: "രണ്ടുമുണ്ടായിരുന്നു. ചിലപ്പോൾ ആദ്യവും ചിലപ്പോൾ അവസാനവും കുളിക്കും." ഞാൻ പറഞ്ഞു: ''കാര്യങ്ങളിലൊക്കെ വിശാലത നൽകിയ അല്ലാഹുവിന്ന് സർവ്വ സ്തുതിയും.'' (ന)', 'غُضَيْفِ بْنِ الْحَارِثِ قَالَ', 'ഉളൈഫ്ബ്നു ഹാരിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ فِي الْإِنَاءِ وَهُوَ الْفَرَقُ، وَكُنْتُ أَغْتَسِلُ أَنَا وَهُوَ مِنْ إِنَاءٍ وَاحِدٍ. (ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) മൂന്ന് സ്വാഅ് വലിപ്പമുള്ള (ഫറഖ്) പാത്രത്തിൽ കുളിച്ചിരുന്നു. ഞാനും നബി(സ)യും ഒരേ പാത്രത്തിൽ കുളിക്കാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ وَأَنَا مِنْ إِنَاءٍ وَاحِدٍ، نَغْتَرِفُ مِنْهُ جَمِيعًا. (ن)', 'ആഇശ(റ): പ്രവാചക(സ)നും ഞാനും ഒരേ പാത്രത്തിൽ നിന്ന് കുളിച്ചിരുന്നു. ഒരുമിച്ച് ഞങ്ങൾ വെള്ളം കോരിയെടുക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ مِنَ الْجَنَابَةِ. (ن)', 'ആഇശ(റ): ഞാനും പ്രവാചക(സ)നും ഒരേ പാത്രത്തിൽ നിന്ന് ഒരുമിച്ച് ജനാബത്തുകുളി കുളിക്കാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ رَأَيْتُنِي أُنَازِعُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْإِنَاءَ، أَغْتَسِلُ أَنَا وَهُوَ مِنْهُ. (ن)', 'ആഇശ(റ): ഞാനും പ്രവാചക(സ)നും ഒരേ പാത്രത്തിൽ കുളിക്കുമ്പോൾ പരസ്പരം പാത്രത്തിനു വേണ്ടി തർക്കിക്കുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 207, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ، أُبَادِرُهُ وَيُبَادِرُنِي، حَتَّى يَقُولَ: "دَعِي لِي" وَأَقُولُ أَنَا: دَعْ لِي. (ن)', 'ആയിശ(റ): ഞാനും നബി(സ)യും ഒരേ പാത്രത്തിൽ നിന്നും കുളിക്കുമ്പോൾ പരസ്പരം പാത്രത്തിനു വേണ്ടി മത്സരിക്കുമായിരുന്നു. അപ്പോൾ അദ്ദേഹം പറയും "എനിക്ക് തരൂ". ഞാൻ പറയും "എനിക്ക് നൽകൂ". (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 207, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُمَا: قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ بَيْنِي وَبَيْنَهُ، فَيُبَادِرُنِي، حَتَّى أَقُولَ: دَعْ لِي، دَعْ لِي، قَالَتْ: وَهُمَا جُنُبَانِ. (م)', 'ആഇശ(റ)യിൽ നിന്ന് മുആദ്(റ): മഹതി പറയുന്നു: ഞാനും നബി(സ)യും ഞങ്ങൾക്ക് മദ്ധ്യേയുള്ള ഒരു പാത്രത്തിൽ നിന്ന് കുളിക്കാറുണ്ടായിരുന്നു. പ്രവാചകൻ(സ) ധൃതി കാണിക്കും ആ സമയം ഞാൻ പറയും ''എനിക്ക് (പാത്രം) തരൂ, എനിക്ക് (പാത്രം) തരൂ.'' അവർ രണ്ടു പേരും ജനാബത്തുകാരായിരിക്കും. (മു)', 'مُعَاذَةَ، عَنْ عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ مِنْ قَدَحٍ يُقَالُ لَهُ الْفَرَقُ. (خ)', 'ആഇശ(റ): ഞാനും നബി(സ)യും ''ഫറഖ്'' എന്ന് പേരുള്ള ഒരു പാത്രത്തിൽ നിന്നായിരുന്നു കുളിച്ചിരുന്നത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا دَخَلَتْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ وَهُوَ يَغْتَسِلُ، قَدْ سَتَرْتُهُ بِثَوْبٍ دُونَهُ، فِي قَصْعَةٍ فِيهَا أَثَرُ الْعَجِينِ. قَالَتْ: فَصَلَّى الضُّحَى، فَمَا أَدْرِي كَمْ صَلَّى حِينَ قَضَى غُسْلَهُ. (ن)', 'ഉമ്മുഹാനിഅ്(റ): മക്കാ വിജയ വർഷം പ്രവാചക(സ)ന്റെ അടുത്ത് പോയി. തിരുമേനി അപ്പോൾ മാവിന്റെ അംശമുള്ള ഒരു പാത്രത്തിൽ നിന്ന് ഒരു വസ്ത്രത്തിന്റെ മറവിൽ നിന്ന് കുളിച്ച് കൊണ്ടിരിക്കുകയായിരുന്നു. പിന്നീട് ളുഹാ നിസ്കരിച്ചു. കുളി കഴിഞ്ഞിട്ട് എത്രയാണ് നിസ്കരിച്ചതെന്ന് എനിക്കറിയില്ല. (ന)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَقَدْ رَأَيْتُنِي أَغْتَسِلُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ هَذَا – فَإِذَا تَوْرٌ مَوْضُوعٌ مِثْلُ الصَّاعِ أَوْ دُونَهُ – فَنَشْرَعُ فِيهِ جَمِيعًا، فَأُفِيضُ عَلَى رَأْسِي بِيَدَيَّ ثَلَاثَ مَرَّاتٍ، وَمَا أَنْقُضُ لِي شَعْرًا. (ن)', 'ആഇശ(റ): ഞാനും പ്രവാചക(സ)നും ഇതിൽ നിന്ന് കുളിക്കുന്നതായി ഞാൻ കണ്ടിട്ടുണ്ട്. അവിടെ ഒരു സ്വാഇന്റെ അത്രയോ ചെറുതോ ആയ ഒരു പാത്രമുണ്ടായിരുന്നു. ഞങ്ങൾ ഒരുമിച്ച് തുടങ്ങും. ഞാനെന്റെ തലയിൽ മൂന്ന് പ്രാവശ്യം വെള്ളം ഒഴിക്കും. എന്റെ മുടി അഴിച്ചിട്ടില്ലായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي امْرَأَةٌ أَشُدُّ ضَفْرَ رَأْسِي، أَفَأَنْقُضُهُ لِغُسْلِ الْجَنَابَةِ؟ قَالَ: "لَا، إِنَّمَا يَكْفِيكِ أَنْ تَحْثِينَ عَلَى رَأْسِكِ ثَلَاثَ حَثَيَاتٍ مِنْ مَاءٍ، ثُمَّ تُفِيضِينَ عَلَى سَائِرِ جَسَدِكِ الْمَاءَ، فَتَطْهُرِينَ. أَوْ قَالَ: فَإِذَا أَنْتِ قَدْ تَطَهَّرْتِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'ഉമ്മുസലമ(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: പ്രവാചകരേ, ഞാൻ മുടി നല്ലവണ്ണം മിടയുന്നയാളാണ്. ജനാബത്ത് കുളിക്കുമ്പോൾ ഞാനത് അഴിച്ചിടണോ?. പ്രവാചകൻ(സ) പറഞ്ഞു: വേണ്ട, നീ നിന്റെ തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിച്ചാൽ മതി. പിന്നീട് മറ്റു ശരീര ഭാഗങ്ങളിലേക്ക് ഒഴിക്കുക. എന്നാൽ തന്നെ നീ ശുദ്ധമാവും, ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,ദ,തു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 208, 208, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ مُحَمَّدِ بْنِ الْمُنْتَشِرِ قَالَ: سَمِعْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: لَأَنْ أُصْبِحَ مُطَّلِيًا بِقَطِرَانٍ أَحَبُّ إِلَيَّ مِنْ أَنْ أُصْبِحَ مُحْرِمًا أَنْضَخُ طِيبًا. فَدَخَلْتُ عَلَى عَائِشَةَ فَأَخْبَرْتُهَا بِقَوْلِهِ، فَقَالَتْ: طَيَّبْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَطَافَ عَلَى نِسَائِهِ، ثُمَّ أَصْبَحَ مُحْرِمًا. (ن)', 'മുഹമ്മദ്ബ്നു മുൻതശിർ(റ): ഇബ്നുഉമർ(റ) പറയുന്നതായി ഞാൻ കേട്ടു. സുഗന്ധം പുരണ്ട് പ്രഭാതമാവുന്നതാണ് സുഗന്ധം പൂശി മുഹ്‌രിമാകുന്നതിനേക്കാൾ എനിക്കിഷ്ടം. ആഇശ(റ)യോട് ഈ വിഷയം ഞാൻ പറഞ്ഞപ്പോൾ മഹതി പറഞ്ഞു: പ്രവാചക(സ)ന് ഞാൻ സുഗന്ധം പൂശി ക്കൊടുത്തു. എന്നിട്ട് തിരുമേനി(സ) ഭാര്യമാരുടെ അടുത്തൊക്കെ പോയി. രാവിലെ മുഹ്‌രിമാവുകയും ചെയ്തു. (ന)', 'مُحَمَّدِ بْنِ الْمُنْتَشِرِ قَالَ', 'മുഹമ്മദ്ബ്നു മുൻതശിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وُضُوءَهُ لِلصَّلَاةِ غَيْرَ رِجْلَيْهِ، وَغَسَلَ فَرْجَهُ وَمَا أَصَابَهُ، ثُمَّ أَفَاضَ عَلَيْهِ الْمَاءَ، ثُمَّ نَحَّى رِجْلَيْهِ فَغَسَلَهُمَا، قَالَتْ: هَذِهِ غُسْلَةٌ لِلْجَنَابَةِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മൈമൂന(റ) പറഞ്ഞു: പ്രവാചകൻ(സ) നിസ്കാരത്തിനുള്ള വുദൂ എടുത്തു. പക്ഷെ കാൽ കഴുകിയില്ല. ഗുഹ്യസ്ഥാനവും അവിടെയുള്ള അഴുക്കുമൊക്കെ കഴുകി. പിന്നീട് ശരീരത്തിൽ വെള്ള മൊഴിച്ചു. പിന്നെ കാൽ രണ്ടും അകറ്റി വെച്ച് കഴുകി. ഇതായിരുന്നു പ്രവാചകന്റെ ജനാബത്ത് കുളി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ مَيْمُونَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ يَبْدَأُ فَيَغْسِلُ يَدَيْهِ، ثُمَّ يُفْرِغُ بِيَمِينِهِ عَلَى شِمَالِهِ فَيَغْسِلُ فَرْجَهُ، ثُمَّ يَضْرِبُ بِيَدِهِ عَلَى الْأَرْضِ ثُمَّ يَمْسَحُهَا، ثُمَّ يَغْسِلُهَا، ثُمَّ يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ يُفْرِغُ عَلَى رَأْسِهِ وَعَلَى سَائِرِ جَسَدِهِ، ثُمَّ يَتَنَحَّى فَيَغْسِلُ رِجْلَيْهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചക പത്നി മൈമൂന(റ) പറഞ്ഞു: നബി(സ) ജനാബത്ത് കുളിച്ചാൽ ആദ്യം കൈ രണ്ടും കഴുകും. പിന്നെ വലത് കൈ കൊണ്ട് ഇടത് കയ്യിലേക്ക് വെള്ളമൊഴിച്ച് ഗുഹ്യസ്ഥാനം കഴുകും. പിന്നെ കൈ തറയിൽ ഉരച്ച് കഴുകും. പിന്നെ നിസ്കാരത്തിനുള്ള വുദൂ എടുക്കും. പിന്നെ തലയിലും മറ്റു ശരീരഭാഗത്തും വെള്ളമൊഴിക്കുകയും അൽപം മാറി നിന്ന് കാൽ രണ്ടും കഴുകുകയും ചെയ്യും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ التَّيَمُّنَ مَا اسْتَطَاعَ: فِي طُهُورِهِ وَتَنَعُّلِهِ وَتَرَجُّلِهِ، وَفِي شَأْنِهِ كُلِّهِ. (ن)', 'ആഇശ(റ): നബി(സ) ശുദ്ധിയിലും ചെരിപ്പ് ധരിക്കുന്നതിലും മുടിചീകുന്നതിലും തന്റെ മറ്റ് എല്ലാ കാര്യങ്ങളിലും കഴിയുന്നത്ര വലത് ഭാഗം മുന്തിക്കാൻ ഇഷ്ടപ്പെട്ടിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 209, 209, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَائِشَةَ وَابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمْ: أَنَّ عُمَرَ سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْغُسْلِ مِنَ الْجَنَابَةِ، وَاتَّسَقَتِ الْأَحَادِيثُ عَلَى هَذَا. يَبْدَأُ فَيُفْرِغُ عَلَى يَدِهِ الْيُمْنَى مَرَّتَيْنِ أَوْ ثَلَاثًا، ثُمَّ يُدْخِلُ يَدَهُ الْيُمْنَى فِي الْإِنَاءِ فَيَصُبُّ بِهَا عَلَى فَرْجِهِ، وَيَدُهُ الْيُسْرَى عَلَى فَرْجِهِ، فَيَغْسِلُ مَا هُنَالِكَ حَتَّى يُنْقِيَهُ، ثُمَّ يَضَعُ يَدَهُ الْيُسْرَى عَلَى التُّرَابِ إِنْ شَاءَ، ثُمَّ يُصَبُّ عَلَى يَدِهِ الْيُسْرَى حَتَّى يُنْقِيَهَا، ثُمَّ يَغْسِلُ يَدَيْهِ ثَلَاثًا، وَيَسْتَنْشِقُ وَيُمَضْمِضُ، وَيَغْسِلُ وَجْهَهُ وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا، حَتَّى إِذَا بَلَغَ رَأْسَهُ لَمْ يَمْسَحْ وَأَفْرَغَ عَلَيْهِ الْمَاءَ، فَهَكَذَا كَانَ غُسْلُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا ذُكِرَ. (ن)', 'ആഇശ(റ)യും ഇബ്നുഉമറും(റ): ഉമർ(റ) നബിയോട് ജനാബത്ത് കുളിയെപ്പറ്റി ചോദിച്ചു. [ഈ വിഷയകമായി പല ഹദീസുകൾ വന്നിട്ടുണ്ട്]. ആദ്യം വലത് കയ്യിൽ രണ്ടോ മൂന്നോ പ്രാവശ്യം വെള്ളമൊഴിക്കും. പിന്നെ വലത് കൈ പാത്രത്തിലിട്ട് ഗുഹ്യസ്ഥാനത്തേക്ക് വെള്ളം കോരിയൊഴിക്കും. ഇടത് കൈ കൊണ്ട് അവിടുത്തെ അഴുക്കൊക്കെ കഴുകി വൃത്തിയാക്കും. പിന്നെ വേണമെങ്കിൽ ഇടത് കൈ മണ്ണിൽ വെച്ച് വെള്ളം ഒഴിച്ച് വൃത്തിയാക്കും. പിന്നെ രണ്ട് കയ്യും മൂന്ന് പ്രാവശ്യം കഴുകും. മൂക്കിൽ വെള്ളം ചീറ്റുകയും കൊപ്ലിക്കുകയും ചെയ്യും. മുഖവും മുഴംകയ്യും മൂന്ന് വീതം പ്രാവശ്യം കഴുകും. തലതടവാനായാൽ തടവാതെ തലക്ക് മുകളിലൂടെ വെള്ളമൊഴിക്കും. ഇതായിരുന്നു പ്രവാചകന്റെ കുളി. (ന)', 'عَائِشَةَ وَابْنِ عُمَرَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ غَسَلَ يَدَيْهِ، ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ يُخَلِّلُ رَأْسَهُ بِأَصَابِعِهِ، حَتَّى إِذَا خُيِّلَ إِلَيْهِ أَنَّهُ قَدِ اسْتَبْرَأَ الْبَشَرَةَ غَرَفَ عَلَى رَأْسِهِ ثَلَاثًا، ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) കുളിക്കുമ്പോൾ കൈ കഴുകും. പിന്നെ വുദൂ ചെയ്യും. പിന്നെ വിരലുപയോഗിച്ച് തല മുടി തിക്കി അകറ്റും. തൊലിയൊക്കെ പൂർണ്ണമായി നനഞ്ഞിരിക്കുന്നുവെന്നറിഞ്ഞാൽ തലയിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കും. പിന്നെ ശരീരത്തിന്റെ മറ്റു ഭാഗവും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ دَعَا بِشَيْءٍ نَحْوَ الْحِلَابِ، فَأَخَذَ بِكَفِّهِ، بَدَأَ بِشِقِّ رَأْسِهِ الْأَيْمَنِ ثُمَّ الْأَيْسَرِ، ثُمَّ أَخَذَ بِكَفَّيْهِ فَقَالَ بِهِمَا عَلَى رَأْسِهِ. (ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ജനാബത്ത് കുളിക്കുമ്പോൾ പാൽ കറക്കുന്ന പാത്രം പോലെയുള്ള ഒന്ന് വരുത്തി കയ്യിൽ പിടിക്കും. ആദ്യം തലയുടെ വലതു ഭാഗവും പിന്നീട് ഇടത് ഭാഗവും കഴുകും. പിന്നെ രണ്ട് കയ്യും ഒരുമിച്ച് പിടിച്ച് തലക്ക് മുകളിലൂടെ വെള്ളമൊഴിക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 210, 210, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذُكِرَ عِنْدَهُ الْغُسْلُ، فَقَالَ: "أَمَّا أَنَا فَأُفْرِغُ عَلَى رَأْسِي ثَلَاثًا". (ن)', 'ജുബൈർബ്നു മുത്‌ഇം(റ): പ്രവാചകന്റെ അടുത്ത് കുളിയെ കുറിച്ച് പറയപ്പെട്ടു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കാറുണ്ട്." (ന)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈർബ്നു മുത്‌ഇം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 210, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ أَفْرَغَ عَلَى رَأْسِهِ ثَلَاثًا. (ن)', 'ജാബിർ(റ): "നബി(സ) കുളിക്കുമ്പോൾ തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കും." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا أَنَا فَأُفِيضُ عَلَى رَأْسِي ثَلَاثًا". وَأَشَارَ بِيَدَيْهِ كِلْتَيْهِمَا. (خ)', 'ജുബൈറുബ്നുമുത്ഇം(റ): നബി(സ) പറഞ്ഞു: ഞാൻ (ജനാബത്തുകുളി നിർവ്വഹിക്കുമ്പോൾ) എന്റെ തലക്ക് മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കാറുണ്ട്. പ്രവാചകൻ(സ) രണ്ട് കൈകൊണ്ടും ആംഗ്യം കാണിച്ചിരുന്നു. (ബു)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നുമുത്ഇം(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً سَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: يَا رَسُولَ اللهِ، كَيْفَ أَغْتَسِلُ عِنْدَ الطُّهُورِ؟ قَالَ: "خُذِي فِرْصَةً مُمَسَّكَةً فَتَوَضَّئِي بِهَا". قَالَتْ: كَيْفَ أَتَوَضَّأُ بِهَا؟ قَالَ: "تَوَضَّئِي بِهَا". قَالَتْ: كَيْفَ أَتَوَضَّأُ بِهَا؟ قَالَتْ: ثُمَّ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَبَّحَ وَأَعْرَضَ عَنْهَا، فَفَطَنَتْ عَائِشَةُ لِمَا يُرِيدُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: فَأَخَذْتُهَا وَجَبَذْتُهَا إِلَيَّ، فَأَخْبَرْتُهَا بِمَا يُرِيدُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): ഒരു സ്ത്രീ പ്രവാചകനോട് ചോദിച്ചു. നബിയേ, ശുദ്ധിയാവുന്ന ഘട്ടത്തിൽ ഞാനെങ്ങനെ കുളിക്കണം?. നബി(സ) പറഞ്ഞു: ''നീ ഒരു പിടി പരുത്തി എടുത്ത് വുളു ചെയ്യുക.'' അവർ ചോദിച്ചു: ''പരുത്തികൊണ്ട് ഞാനെങ്ങനെ വുളു ചെയ്യും?.'' പ്രവാചകൻ പറഞ്ഞു: "അത് കൊണ്ട് നീ വുദൂ ചെയ്യുക.'' അവർ ചോദിച്ചു: ''എങ്ങനെ?''. അപ്പോൾ റസൂൽ(സ) തസ്ബീഹ് ചൊല്ലി തിരിഞ്ഞ് പോയി. ആഇശ(റ)ക്ക് പ്രവാചകൻ(സ) ഉദ്ദേശിച്ചത് മനസ്സിലായി. ആഇശ(റ) പറയുന്നു: ഞാൻ ആസ്ത്രീയെ എന്റെയടുത്തേക്ക് വലിച്ച് പ്രവാചകനുദ്ദേശിച്ച കാര്യം പറഞ്ഞ് കൊടുത്തു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: اغْتَسَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْجَنَابَةِ: فَغَسَلَ فَرْجَهُ، وَدَلَكَ يَدَهُ بِالْأَرْضِ أَوِ الْحَائِطِ، ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ أَفَاضَ عَلَى رَأْسِهِ وَسَائِرِ جَسَدِهِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): പ്രവാചക പത്നി മൈമൂന(റ) പറഞ്ഞു: പ്രവാചകൻ ജനാബത്തിന്റെ കുളി നിർവ്വഹിച്ചു. ഗുഹ്യസ്ഥാനം കഴുകി. കൈ തറയിലോ ചുമരിലോ തേച്ച് കഴുകി. പിന്നെ നിസ്കാരത്തിന്റെ വുദൂ എടുത്തു. പിന്നീട് തലയിലും മറ്റു ശരീരഭാഗങ്ങളിലും വെള്ളമൊഴിച്ചു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 211, 211, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، فَسَأَلْنَاهُ عَنْ حَجَّةِ الْوَدَاعِ: فَحَدَّثَنَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ لِخَمْسٍ بَقِينَ مِنْ ذِي الْقَعْدَةِ وَخَرَجْنَا مَعَهُ، حَتَّى إِذَا أَتَى ذَا الْحُلَيْفَةِ وَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَرْسَلَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ أَصْنَعُ؟ فَقَالَ: "اغْتَسِلِي، ثُمَّ اسْتَثْفِرِي، ثُمَّ أَهِلِّي". (ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)യിൽ നിന്ന്, ഞങ്ങൾ പ്രവാചക(സ)നോട് ഹജ്ജത്തുൽവാദാഇനെക്കുറിച്ച് ചോദിച്ചു. ദുൽഹിജ്ജ മാസത്തിലെ അഞ്ച് ദിവസം ബാക്കിയിരിക്കെ റസൂൽ(സ) ഹജ്ജിന് പുറപ്പെട്ടു. ഞങ്ങളും കൂടെ പ്പുറപ്പെട്ടു. അങ്ങിനെ ഞങ്ങൾ ദുൽഹുലൈഫയിൽ എത്തിയപ്പോൾ അസ്മാഉ ബിൻതു ഉമൈസ് മുഹമ്മദ് പ്രസവിച്ചു. അപ്പോൾ റസൂലി(സ)നോട് എന്ത് ചെയ്യണമെന്ന് ചോദിക്കാൻ ആളെ അയച്ചു. റസൂൽ(സ) പറഞ്ഞു: നീ കുളിക്കുകയും തുണിക്കഷ്ണം വെച്ച് കെട്ടുകയും ചെയ്യുക, ശേഷം ഇഹ്റാം ചെയ്യുക. (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَتَوَضَّأُ بَعْدَ الْغُسْلِ. (ن)', 'ആയിശ(റ): റസൂൽ(സ) കുളിച്ച ശേഷം വുദൂ എടുക്കാറില്ല. (ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أُطَيِّبُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَطُوفُ عَلَى نِسَائِهِ، ثُمَّ يُصْبِحُ مُحْرِمًا يَنْضَخُ طِيبًا. (خ,ن)', 'ആയിശ(റ): ഞാൻ റസൂലി(സ)ന് സുഗന്ധം പുരട്ടിക്കൊടുക്കാറുണ്ടായിരുന്നു. അങ്ങനെ അദ്ദേഹം തന്റെ ഭാര്യമാരെ സന്തർശിക്കുകയും പിന്നെ സുഗന്ധം പൂശിയിരിക്കെതന്നെ മുഹ്‌രിമാവുകയും ചെയ്യുമായിരുന്നു. (ബു,ന)', 'عَائِشَةَ', 'ആയിശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَطُوفُ عَلَى نِسَائِهِ فِي غُسْلٍ وَاحِدٍ. حَسَنٌ صَحِيحٌ. (ق,ن,د,جه,ت)', 'അനസ്(റ): പ്രവാചകൻ(സ) ഒരു കുളി മാത്രം കുളിച്ച് തന്റെ ഭാര്യമാരെ സമീപിക്കാറുണ്ടായിരുന്നു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (തു,ന,ദ,ജ,ബു,മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ن','د','جه','ت']::text[], array['തു','ന','ദ','ജ','ബു','മു']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ غَسَلَ يَدَيْهِ، ثُمَّ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ، ثُمَّ اغْتَسَلَ، ثُمَّ يُخَلِّلُ بِيَدِهِ شَعْرَهُ، حَتَّى إِذَا ظَنَّ أَنَّهُ قَدْ أَرْوَى بَشَرَتَهُ أَفَاضَ عَلَيْهِ الْمَاءَ ثَلَاثَ مَرَّاتٍ، ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ. (ن)', 'ആഇശ(റ): പ്രവാചകൻ(സ) കുളിക്കുമ്പോൾ കൈ രണ്ടും കഴുകും. പിന്നെ നിസ്കാരത്തിന്റെ വുളു ചെയ്യും. പിന്നീട് കുളിക്കും. കൈ കൊണ്ട് രോമം നന്നായി തിക്കി അകറ്റും. തൊലിയാകെ നനഞ്ഞുവെന്നറിഞ്ഞാൽ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കും. പിന്നീട് ശരീരമാകെ കഴുകുകയും ചെയ്യും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 212, 212, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَانَ إذا اغْتَسَلَ مِنَ الْجَنَابَةِ بَدَأَ فَغَسَلَ يَدَيْهِ ثُمَّ يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلاَةِ، ثُمَّ يُدْخِلُ أَصَابِعَهُ فِي الْمَاءِ فَيُخَلِّلُ بِهَا أُصُولَ شَعَرِهِ، ثُمَّ يَصُبُّ عَلَى رَأْسِهِ ثَلاَثَ غُرَفٍ بِيَدَيْهِ ثُمَّ يُفِيضُ الْمَاءَ عَلَى جِلْدِهِ كُلِّهِ. (خ)', 'പ്രവാചക പത്നി ആഇശ(റ): നബി(സ) ജനാബത്ത് കുളിക്കുകയാണെങ്കിൽ ആദ്യമായി കൈ കഴുകും. പിന്നെ നിസ്കാരത്തിന് വുദൂ ചെയ്യുന്നത് പോലെ വുദൂ ചെയ്യും. പിന്നെ വിരലുകൾ വെള്ളത്തിലിട്ട് രോമകൂപങ്ങളൊക്കെ തിക്കകറ്റി കഴുകും. പിന്നീട് രണ്ട് കയ്യും ഉപയോഗിച്ച് തലക്കു മുകളിലൂടെ മൂന്ന് പ്രാവശ്യം വെള്ളം കോരിയൊഴിക്കും. പിന്നെ ശരീരമാസകലം വെള്ളം ഒഴിക്കും. (ബു)', 'عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'പ്രവാചക പത്നി ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَوَضَّأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وُضُوءَهُ لِلصَّلاَةِ غَيْرَ رِجْلَيْهِ وَغَسَلَ فَرْجَهُ وَمَا أَصَابَهُ مِنَ الْأَذَى ثُمَّ أَفَاضَ عَلَيْهِ الْمَاءَ ثُمَّ نَحَّى رِجْلَيْهِ فَغَسَلَهُمَا، هَذِهِ غُسْلُهُ مِنَ الْجَنَابَةِ. (خ)', 'പ്രവാചക പത്നി മൈമൂന(റ): പ്രവാചകൻ നിസ്കാരത്തിന് വുദൂ ചെയ്യുന്ന പോലെ വുദൂ ചെയ്തു. പക്ഷെ കാൽ കഴുകിയില്ല. ഗുഹ്യസ്ഥാനവും അവിടെയുള്ള അഴുക്കുകളും കഴുകി വൃത്തിയാക്കി. പിന്നെ ശരീരത്തിൻ മേൽ വെള്ളമൊഴിച്ചു. പിന്നീട് കാലുകൾ രണ്ടും അകറ്റിവെച്ച് കഴുകി. ഇതായിരുന്നു പ്രവാചകന്റെ ജനാബത്ത് കുളി. (ബു)', 'مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'പ്രവാചക പത്നി മൈമൂന(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذا اغْتَسَلَ مِنَ الْجَنَابَةِ دَعَا بِشَيْءٍ نَحْوَ الْحِلاَبِ فَأَخَذَ بِكَفِّهِ فَبَدَأَ بِشِقِّ رَأْسِهِ الْأَيْمَنِ ثُمَّ الْأَيْسَرِ فَقَالَ بِهِمَا عَلَى وَسَطِ رَأْسِهِ. (خ)', 'ആഇശ(റ): നബി(സ) ജനാബത്തിന് കുളിക്കുമ്പോൾ പാൽ കറന്ന് വെക്കുന്ന പാത്രം പോലുള്ള ഒന്ന് കൊണ്ട് വരാൻ പറയും. പിന്നെ തന്റെ രണ്ട് മുൻകയ്യും കൊണ്ടത് പിടിച്ച് വലത് ഭാഗം കൊണ്ട് (കുളി) തുടങ്ങും. പിന്നെ ഇടത് ഭാഗവും. പിന്നീട് രണ്ട് കൈകൊണ്ടും തലക്ക് മുകളിലൂടെ ഒഴിക്കും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَأَنِّي أَنْظُرُ إِلَى وَبِيصِ الطِّيبِ فِي مَفْرِقِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُحْرِمٌ. (خ)', 'ആഇശ(റ): പ്രവാചകൻ മുഹ്‌രിമായിരിക്കെ അവിടുത്തെ നെറ്റിത്തടത്തിലെ സുഗന്ധത്തിന്റെ തിളക്കത്തിലേക്ക് ഞാൻ നോക്കുന്ന പോലെ (എനിക്കിപ്പോഴും അനുഭവപ്പെടുന്നു). (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أُطَيِّبُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَطُوفُ عَلَى نِسَائِهِ ثُمَّ يُصْبِحُ مُحْرِمًا يَنْضَخُ طِيبًا. (خ)', 'ആഇശ(റ): ഞാൻ പ്രവാചക(സ)ന് സുഗന്ധം പുരട്ടി കൊടുക്കാറുണ്ടായിരുന്നു. അങ്ങനെ പ്രവാചകൻ(സ) ഭാര്യമാരുടെ അടുത്തേക്ക് പോവുകയും ചെയ്യും. മുഹ്‌രിമായി സുഗന്ധം പരത്തിയായിരിക്കും പ്രവാചകൻ(സ) രാവിലെ ഉണ്ടാവുക. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 213, 213, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدُورُ عَلَى نِسَائِهِ فِي السَّاعَةِ الْوَاحِدَةِ مِنَ اللَّيْلِ وَالنَّهَارِ وَهُنَّ إِحْدَى عَشْرَةَ، وَفِي رِوَايَةٍ: تِسْعُ نِسْوَةٍ، قِيلَ: أَوَكَانَ يُطِيقُ ذَلِكَ! قَالَ: كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلاَثِينَ. (خ)', 'അനസുബ്നു മാലിക്(റ): രാത്രിയിലോ പകലിലോ ഒറ്റമണിക്കൂറിനുള്ളിലായി പ്രവാചകൻ(സ) തന്റെ ഭാര്യമാരുടെ അടുത്ത് പോകാറുണ്ടായിരുന്നു. അവർ പതിനൊന്ന് പേരുണ്ടായിരുന്നു. ഒരു റിപ്പോർട്ടിൽ ഒമ്പത് എന്നുമുണ്ട്. റസൂലിന് അത്രക്കൊക്കെ ശക്തിയുണ്ടായിരുന്നുവോ എന്ന് (അനസ്(റ)) ചോദിക്കപ്പെടുകയുണ്ടായി. അനസ്(റ) പറഞ്ഞു: "നബി(സ)ക്ക് മുപ്പത് ആളുകളുടെ ശക്തി നൽകപ്പെട്ടിട്ടുണ്ടെന്നാണ് ഞങ്ങൾ പറഞ്ഞിരുന്നത്." (ബു)', 'أَنَسٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=68), 1, 'وَفِي رِوَايَةٍ: تِسْعُ نِسْوَةٍ، قِيلَ: أَوَكَانَ يُطِيقُ ذَلِكَ! قَالَ: كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلاَثِينَ. (خ)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذا اغْتَسَلَ مِنَ الْجَنَابَةِ غَسَلَ يَدَيْهِ وَتَوَضَّأَ وُضُوءَهُ لِلصَّلاَةِ، ثُمَّ اغْتَسَلَ، ثُمَّ يُخَلِّلُ بِيَدِهِ شَعَرَهُ حَتَّى إذا ظَنَّ أَنَّهُ قَدْ أَرْوَى بَشَرَتَهُ أَفَاضَ عَلَيْهِ الْمَاءَ ثَلاَثَ مَرَّاتٍ، ثُمَّ غَسَلَ سَائِرَ جَسَدِهِ. (خ)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ജനാബത്തിന് കുളിക്കുമ്പോൾ രണ്ട് കയ്യും കഴുകുകയും നിസ്കാരത്തിന് വുദൂ ചെയ്യുന്നത് പോലെ വുദൂ ചെയ്യുകയും ചെയ്യും. പിന്നെ കുളിക്കും. പിന്നെ കൈകൊണ്ട് മുടി തിക്കിയ കറ്റുകയും ചെയ്യും. തൊലി മുഴുവനായും നനഞ്ഞുവെന്ന് കണ്ടാൽ മൂന്ന് പ്രാവശ്യം വെള്ളമൊഴിക്കുകയും ശരീരത്തിന്റെ മറ്റു ഭാഗങ്ങൾ കഴുകുകയും ചെയ്യും. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُقِيمَتِ الصَّلاَةُ وَعُدِّلَتِ الصُّفُوفُ قِيَامًا فَخَرَجَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا قَامَ فِي مُصَلاَّهُ ذَكَرَ أَنَّهُ جُنُبٌ فَقَالَ لَنَا: مَكَانَكُمْ ثُمَّ رَجَعَ فَاغْتَسَلَ ثُمَّ خَرَجَ إِلَيْنَا وَرَأْسُهُ يَقْطُرُ فَكَبَّرَ فَصَلَّيْنَا مَعَهُ. (خ)', 'അബൂഹുറൈറ(റ): നിസ്കാരത്തിന് ഇഖാമത്ത് കൊടുക്കപ്പെടുകയും സ്വഫ്ഫുകളൊക്കെ നേരെയാക്കപ്പെടുകയും ചെയ്തു. റസൂൽ(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. നിസ്കരിക്കാൻ എണീറ്റ് നിന്നപ്പോൾ ജനാബത്തുകാരനാണെന്നുള്ള കാര്യം പ്രവാചകൻ(സ) ഓർത്തു. അവിടുന്ന് ഞങ്ങളോട് പറഞ്ഞു: നിങ്ങൾ അവിടെത്തന്നെ നിൽക്കുക. പ്രവാചകൻ(സ) പിന്നീട് മടങ്ങിപ്പോവുകയും കുളിച്ച് വരികയും ചെയ്തു. ഈ സമയം പ്രവാചകന്റെ തലയിൽ നിന്ന് വെള്ളം ഇറ്റി വീഴുന്നുണ്ടായിരുന്നു. പിന്നെ തിരുമേനി(സ) തക്ബീർ ചൊല്ലി നിസ്കാരത്തിൽ പ്രവേശിച്ചു. ഞങ്ങളും അവിടുത്തോടൊപ്പം നിസ്കരിച്ചു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 214, 214, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَتْ بَنُو إِسْرَائِيلَ يَغْتَسِلُونَ عُرَاةً، يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، وَكَانَ مُوسَى يَغْتَسِلُ وَحْدَهُ، فَقَالُوا: وَاللهِ مَا يَمْنَعُ مُوسَى أَنْ يَغْتَسِلَ مَعَنَا إِلَّا أَنَّهُ آدَرُ فَذَهَبَ مَرَّةً يَغْتَسِلُ فَوَضَعَ ثَوْبَهُ عَلَى حَجَرٍ فَفَرَّ الْحَجَرُ بِثَوْبِهِ، فَخَرَجَ مُوسَى فِي إِثْرِهِ يَقُولُ: ثَوْبِي يَا حَجَرُ، ثَوْبِي يَا حَجَرُ، حَتَّى نَظَرَتْ بَنُو إِسْرَائِيلَ إِلَى مُوسَى، فَقَالُوا: وَاللهِ مَا بِمُوسَى مِنْ بَأْسٍ، وَأَخَذَ ثَوْبَهُ فَطَفِقَ بِالْحَجَرِ ضَرْبًا فَقَالَ أَبُو هُرَيْرَةَ: وَاللهِ إِنَّهُ لَنَدَبٌ بِالْحَجَرِ سِتَّةٌ أَوْ سَبْعَةٌ ضَرْبًا بِالْحَجَرِ. (خ)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറയുന്നു: ഇസ്റാഈല്യർ നഗ്നരായി പരസ്പരം നോക്കിയായിരുന്നു കുളിച്ചിരുന്നത്. പക്ഷെ, മൂസാ(അ) ഒറ്റക്കായിരുന്നു കുളിച്ചിരുന്നത്. അത് കണ്ട് ജനങ്ങൾ പറഞ്ഞു: മൂസാ(അ) ഞങ്ങളോട് കൂടെ കുളിക്കാത്തത് അദ്ദേഹം വലിയ വൃഷ്ണമുള്ള ആളായതിനാലാണ്. ഒരു പ്രാവശ്യം വസ്ത്രം അഴിച്ച് ഒരു കല്ലിൽ വെച്ച് കുളിക്കാനിറങ്ങിയപ്പോൾ കല്ല് വസ്ത്രവുമായി ഓടി. മൂസാ(അ) കല്ലേ! എന്റെ വസ്ത്രം, കല്ലേ! എന്റെ വസ്ത്രം എന്ന് പറഞ്ഞ് അതിന് പിന്നാലെ പോയി. ഈ സമയം ബനൂ ഇസ്റാഈല്യർ അദ്ദേഹത്തെ പൂർണ്ണമായി കാണുകയും മൂസാ(അ)ക്ക് ഒരു കുഴപ്പവുമില്ലെന്ന് പറയുകയും ചെയ്തു. അദ്ദേഹം വസ്ത്രമെടുത്ത് കല്ലിനെ അടിക്കാൻ തുടങ്ങി. അബൂഹുറൈറ(റ) പറയുന്നു: "കല്ലിൽ അടിച്ച ആറോ ഏഴോ പാടുണ്ട്." (ബു)', 'أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 214, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا فَخَرَّ عَلَيْهِ جَرَادٌ مِنْ ذَهَبٍ فَجَعَلَ أَيُّوبُ يَحْتَثِي فِي ثَوْبِهِ، فَنَادَاهُ رَبُّهُ يَا أَيُّوبُ أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟ قَالَ: بَلَى وَعِزَّتِكَ وَلَكِنْ لاَ غِنَى بِي عَنْ بَرَكَتِكَ. (خ)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ പറയുന്നു: അയ്യൂബ്(അ) ഒരിക്കൽ നഗ്നനായി കുളിച്ചു കൊണ്ടിരിക്കെ ഒരു സ്വർണ്ണ വെട്ടുകിളി അദ്ദേഹത്തിന്റെ അടുത്ത് വീണു. അദ്ദേഹം തന്റെ വസ്ത്രത്തിൽ വെക്കാൻ തുടങ്ങി. ഈ സമയത്ത് അല്ലാഹു വിളിച്ച് പറഞ്ഞു: അയ്യൂബേ, നീ കാണുന്നതിനെ (ഈ സ്വർണ്ണ വെട്ടുകിളിയെ) തൊട്ട് ഞാൻ നിന്നെ ഐശ്വര്യമാക്കിയിട്ടില്ലയോ?. അദ്ദേഹം പ്രതിവചിച്ചു: അതേ തമ്പുരാനേ, നിന്റെ പ്രതാപത്തെ തന്നെയാണ് സത്യം, പക്ഷെ നിന്റെ ബറകതിനെ തൊട്ട് എനിക്കൊരൈശ്വര്യവുമില്ലല്ലോ. (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു','ന']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ يَعْلَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يَغْتَسِلُ بِالْبَرَازِ، فَصَعِدَ الْمِنْبَرَ فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، وَقَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ حَلِيمٌ حَيِيٌّ سِتِّيرٌ، يُحِبُّ الْحَيَاءَ وَالسَّتْرَ، فَإِذَا اغْتَسَلَ أَحَدُكُمْ فَلْيَسْتَتِرْ". (ن)', 'യഅ്ല(റ): ഒരാൾ വെളിയിൽ കുളിക്കുന്നത് പ്രവാചകൻ(സ) കണ്ടു. അങ്ങനെ മിമ്പറിൽ കയറി അല്ലാഹുവിനെ സ്തുതിച്ച ശേഷം അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു മറഞ്ഞവനും ലജ്ജയുള്ളവനുമാണ്. അവൻ ലജ്ജയും മറയും ഇഷ്ടപ്പെടുന്നു. ആരെങ്കിലും കുളിക്കുകയാണെങ്കിൽ മറസ്വീകരിക്കട്ടെ." (ന)', 'يَعْلَى', 'യഅ്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ يَعْلَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ عَزَّ وَجَلَّ سِتِّيرٌ، فَإِذَا أَرَادَ أَحَدُكُمْ أَنْ يَغْتَسِلَ فَلْيَتَوَارَ بِشَيْءٍ". (ن)', 'യഅ്ല(റ): പ്രവാചകൻ പറഞ്ഞു: "അല്ലാഹു മറഞ്ഞവനാണ്. ആരെങ്കിലും കുളിക്കാൻ ആഗ്രഹിച്ചാൽ എന്ത് കൊണ്ടെങ്കിലും മറ സ്വീകരിക്കട്ടെ." (ന)', 'يَعْلَى', 'യഅ്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: وَضَعْتُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَاءً، قَالَتْ: فَسَتَرْتُهُ، فَذَكَرَتِ الْغُسْلَ، قَالَتْ: ثُمَّ أَتَيْتُهُ بِخِرْقَةٍ فَلَمْ يُرِدْهَا. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മൈമൂന(റ) പറഞ്ഞു: പ്രവാചക(സ)നു വേണ്ടി ഞാൻ വെള്ളം വെച്ച് കൊടുത്തു. ഞാൻ മറച്ച് കൊടുക്കുകയും ചെയ്തു. (പിന്നെ കുളിയുടെ രൂപം പൂർണ്ണമായും വിശദീകരിച്ചു.) പിന്നീട് ഒരു ശീലയുമായി പ്രവാചകനെ ഞാൻ സമീപിച്ചു. പക്ഷെ അത് റസൂൽ(സ) ആഗ്രഹിച്ചിട്ടില്ലായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 215, 215, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: ذَهَبْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، فَوَجَدْتُهُ يَغْتَسِلُ وَفَاطِمَةُ تَسْتُرُهُ، فَقَالَ: "مَنْ هَذِهِ". فَقُلْتُ: أَنَا أُمُّ هَانِئٍ. (خ)', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ): പ്രവാചക(സ)ന്റെ അടുത്തേക്ക് മക്കാവിജയ വർഷം ഞാൻ പോയി. പ്രവാചകനപ്പോൾ കുളിക്കുകയായിരുന്നു. ഫാത്വിമ(റ) അദ്ദേഹത്തിന് മറച്ച് കൊടുക്കുന്നുമുണ്ടായിരുന്നു. അപ്പോൾ പ്രവാചകൻ(സ) ചോദിച്ചു: "ആരാണിത്?". ഞാൻ പറഞ്ഞു: "ഞാൻ ഉമ്മുഹാനിഅ് ആണ്". (ബു)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَقِيَهُ فِي بَعْضِ طَرِيقِ الْمَدِينَةِ وَهُوَ جُنُبٌ، قَالَ: فَانْخَنَسْتُ مِنْهُ، فَذَهَبَ فَاغْتَسَلَ ثُمَّ جِئْتُ فَقَالَ: "أَيْنَ كُنْتَ يَا أَبَا هُرَيْرَةَ؟" قَالَ: كُنْتُ جُنُبًا، فَكَرِهْتُ أَنْ أُجَالِسَكَ وَأَنَا عَلَى غَيْرِ طَهَارَةٍ، فَقَالَ: "سُبْحَانَ اللهِ، إِنَّ الْمُسْلِمَ لاَ يَنْجُسُ". (خ)', 'അബൂഹുറൈറ(റ): ഒരിക്കൽ തിരുമേനി(സ) മദീനയിലെ ഏതോ ഒരു വഴിയിൽ വെച്ച് അദ്ദേഹത്തെ (അബൂഹുറൈറയെ) കണ്ടുമുട്ടി. അപ്പോൾ അദ്ദേഹം പ്രവാചകനിൽ നിന്ന് മെല്ലെ മാറുകയും പോയി കുളിച്ച് വരികയും ചെയ്തു. അപ്പോൾ പ്രവാചകൻ(സ) ചോദിച്ചു: അബൂഹുറൈറേ, നീ എവിടെയായിരുന്നു?. അദ്ദേഹം പറഞ്ഞു: "ഞാൻ അശുദ്ധിയോടെയായിരുന്നു. ശുദ്ധിയില്ലാതെ താങ്കളോടൊപ്പം ഇരിക്കുന്നതിൽ എനിക്ക് ബുദ്ധിമുട്ട് തോന്നി." പ്രവാചകൻ(സ) പറഞ്ഞു: "അല്ലാഹു എത്ര പരിശുദ്ധൻ, ഒരു മുസ്ലിം മ്ലേച്ചമാവുകയില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَحْتَ كُلِّ شَعْرَةٍ جَنَابَةٌ، فَاغْسِلُوا الشَّعْرَ وَأَنْقُوا الْبَشَرَةَ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: ഒരോ രോമത്തിനും താഴെ ജനാബത്തുണ്ട്. അതുകൊണ്ട് രോമം കഴുകുക. തൊലി വൃത്തിയാക്കുകയും ചെയ്യുക. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يَتَوَضَّأُ بَعْدَ الْغُسْلِ. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) കുളിക്ക് ശേഷം വുദൂ ചെയ്യാറില്ലായിരുന്നു. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 216, 216, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يَجِدُ الْبَلَلَ وَلَا يَذْكُرُ احْتِلَامًا؟ قَالَ: "يَغْتَسِلُ" وَعَنِ الرَّجُلِ يَرَى أَنَّهُ قَدِ احْتَلَمَ وَلَمْ يَجِدْ بَلَلًا؟ قَالَ: "لَا غُسْلَ عَلَيْهِ". قَالَتْ أُمُّ سَلَمَةَ: يَا رَسُولَ اللهِ، هَلْ عَلَى الْمَرْأَةِ تَرَى ذَلِكَ غُسْلٌ؟ قَالَ: "نَعَمْ، إِنَّ النِّسَاءَ شَقَائِقُ الرِّجَالِ". (ت,ن,جه)', 'ആഇശ(റ): ഒരാൾ സ്വപ്നസ്ഖലനം സംഭവിച്ചത് ഓർക്കുന്നില്ല. വസ്ത്രത്തിൽ നനവ് കണുന്നുമുണ്ട് ഇങ്ങനെയുള്ള ഒരാൾ എന്ത് ചെയ്യണമെന്നതിനെപ്പറ്റി നബി(സ) ചോദിക്കപ്പെട്ടു. പ്രവാചകൻ(സ) പറഞ്ഞു: "അയാൾ കുളിക്കണം". സ്ഖലിച്ചതായി ഓർക്കുകയും നനവ് കാണാതിരിക്കുകയും ചെയ്താലോ? എന്ന് ചോദിക്കപ്പെട്ടപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: ''അയാൾ കുളിക്കേണ്ടതില്ല''. ഉമ്മുസലമ(റ) ചോദിച്ചു: പ്രവാചകരേ! ഇപ്രകാരം കാണുന്ന സ്ത്രീ കുളിക്കണോ?. നബി(സ) പറഞ്ഞു: ''അതെ, സ്ത്രീ പുരുഷന്റെ കൂടെപിറപ്പാണ്.'' (തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 217, 217, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَذْيِ؟ فَقَالَ: "مِنَ الْمَذْيِ الْوُضُوءُ، وَمِنَ الْمَنِيِّ الْغُسْلُ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അലി(റ): നബി(സ)യോട് ഞാൻ മദ്യിനെ കുറിച്ച് ചോദിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: മദ്യ് പുറപ്പെട്ടാൽ വുദൂ ചെയ്യണം. മനിയ്യാണെങ്കിൽ കുളിക്കുകയും വേണം. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 217, 217, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَلْقَى مِنَ الْمَذْيِ شِدَّةً وَعَنَاءً، فَكُنْتُ أُكْثِرُ مِنْهُ الْغُسْلَ، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَأَلْتُهُ عَنْهُ؟ فَقَالَ: "إِنَّمَا يُجْزِئُكَ مِنْ ذَلِكَ الْوُضُوءُ". فَقُلْتُ: يَا رَسُولَ اللهِ، كَيْفَ بِمَا يُصِيبُ ثَوْبِي مِنْهُ؟ قَالَ: "يَكْفِيكَ أَنْ تَأْخُذَ كَفًّا مِنْ مَاءٍ، فَتَنْضَحَ بِهِ ثَوْبَكَ حَيْثُ تَرَى أَنَّهُ أَصَابَ مِنْهُ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): എനിക്ക് ശക്തമായി മദ്യ് പുറപ്പെടാറുണ്ടായിരുന്നു. അത് കൊണ്ട് പലപ്രാവശ്യം ഞാൻ കുളിക്കാറുമുണ്ടായിരുന്നു. ഈ വിഷയം തിരിമേനി(സ)യെ അറിയിച്ച് അതിനെകുറിച്ച് ഞാൻ ആരാഞ്ഞു. പ്രവാചകൻ പറഞ്ഞു: ''അതിന് നീ വുദൂ ചെയ്താൽ മതി.'' ഞാൻ ചോദിച്ചു: പ്രവാചകരേ, എന്റെ വസ്ത്രത്തിലായാലോ?. നബി(സ) പറഞ്ഞു: ''ഒരു കയ്യിൽ വെള്ളമെടുത്ത് പുരണ്ട സ്ഥലത്ത് കുടഞ്ഞാൽ മതിയാകും.'' ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 217, 217, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ هَمَّامِ بْنِ الْحَارِثِ قَالَ: ضَافَ عَائِشَةَ – رَضِيَ اللهُ عَنْهَا – ضَيْفٌ، فَأَمَرَتْ لَهُ بِمِلْحَفَةٍ صَفْرَاءَ، فَنَامَ فِيهَا، فَاحْتَلَمَ، فَاسْتَحْيَا أَنْ يُرْسِلَ بِهَا وَبِهَا أَثَرُ الاحْتِلاَمِ، فَغَمَسَهَا فِي الْمَاءِ ثُمَّ أَرْسَلَ بِهَا، فَقَالَتْ عَائِشَةُ: لِمَ أَفْسَدَ عَلَيْنَا ثَوْبَنَا؟ إِنَّمَا كَانَ يَكْفِيهِ أَنْ يَفْرُكَهُ بِأَصَابِعِهِ، وَرُبَّمَا فَرَكْتُهُ مِنْ ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَصَابِعِي. حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'ഹമ്മാദ് ബ്നു ഹാരിസ്(റ): ആഇശ(റ) ഒരു അഥിതിയെ സൽക്കരിച്ചു. അയാൾക്ക് ഒരു മഞ്ഞ പുതപ്പ് നൽകാനാജ്ഞാപിച്ചു. അതിലയാൾ ഉറങ്ങി. സ്ഖലിക്കുകയും ചെയ്തു. പുതപ്പ് അപ്രകാരം ആഇശ(റ)ക്ക് തിരിച്ച് നൽകാൻ അദ്ദേഹത്തിന് ലജ്ജ തോന്നി. അതിനാൽ അയാളത് വെള്ളത്തിൽ മുക്കി കൊടുത്തയച്ചു. അപ്പോൾ മഹതി ചോദിച്ചു: അയാൾ ഞങ്ങളുടെ വസ്ത്രം എന്തിന് കേടുവരുത്തി?. അയാൾക്കത് വിരലുകൾകൊണ്ട് ചുരണ്ടിക്കളഞ്ഞ് കൂടായിരുന്നോ?. ചിലപ്പോൾ ഞാൻ പ്രവാചകന്റെ വസ്ത്രത്തിൽ നിന്ന് ചുരണ്ടിക്കളയാറുണ്ട്. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു,ന,ജ)', 'هَمَّامِ بْنِ الْحَارِثِ قَالَ', 'ഹമ്മാദ് ബ്നു ഹാരിസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 217, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا غَسَلَتْ مَنِيًّا مِنْ ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): അവർ പ്രവാചകരുടെ വസ്ത്രത്തിലെ മനിയ്യ് കഴുകിയിട്ടുണ്ടായിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 218, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رُبَّمَا اغْتَسَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْجَنَابَةِ، ثُمَّ جَاءَ فَاسْتَدْفَأَ بِي، فَضَمَمْتُهُ إِلَيَّ، وَلَمْ أَغْتَسِلْ. (ت,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) ചിലപ്പോൾ ജനാബത്ത് കുളിച്ച് എന്റെയടുത്ത് വന്ന് ചൂട് പങ്കിടാറുണ്ടായിരുന്നു. ഞാനപ്പോൾ പ്രവാചകനെ എന്നിലേക്ക് അണച്ച് പിടിക്കും. പക്ഷെ ഞാൻ പിന്നെ കുളിക്കാറില്ല. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 218, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الصَّعِيدَ الطَّيِّبَ طَهُورُ – وَفِي رِوَايَةٍ: وُضُوءُ – الْمُسْلِمِ وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ، فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ، فَإِنَّ ذَلِكَ خَيْرٌ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബൂദർറ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: നല്ല മണ്ണ് മുസ്ലിമിന് ശുദ്ധിയാക്കാനുള്ളതാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ ''വുദൂ ചെയ്യുന്ന വെള്ളമാണ്'' എന്നാണുള്ളത്. പത്ത് വർഷത്തോളം വെള്ളം കിട്ടിയിട്ടില്ലെങ്കിലും ശരി. വെള്ളം ലഭിച്ചാൽ തൊലിയിലത് പ്രയോഗിക്കട്ടെ. കാരണം അതാണുത്തമം. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു,ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 218, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=86), 1, 'وَفِي رِوَايَةٍ: وُضُوءُ – الْمُسْلِمِ وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ، فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ، فَإِنَّ ذَلِكَ خَيْرٌ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'മറ്റൊരു നിവേദനിൽ ''വുദൂ ചെയ്യുന്ന വെള്ളമാണ്'' എന്നാണുള്ളത്. പത്ത് വർഷത്തോളം വെള്ളം കിട്ടിയിട്ടില്ലെങ്കിലും ശരി. വെള്ളം ലഭിച്ചാൽ തൊലിയിലത് പ്രയോഗിക്കട്ടെ. കാരണം അതാണുത്തമം. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقْرِئُنَا الْقُرْآنَ عَلَى كُلِّ حَالٍ، مَا لَمْ يَكُنْ جُنُبًا. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'അലി(റ): ഞങ്ങൾക്ക് ജനാബത്തുള്ള അവസ്ഥയിലൊഴികെ മറ്റെല്ലാ അവസ്ഥയിലും ഞങ്ങളെ കൊണ്ട് പ്രവാചകൻ(സ) ഖുർആൻ ഓതിക്കാറുണ്ടായിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 218, 218, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَبْدِ اللهِ بْنِ سَلَمَةَ قَالَ: دَخَلْتُ عَلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ أَنَا وَرَجُلاَنِ: رَجُلٌ مِنَّا وَرَجُلٌ مِنْ بَنِي أَسَدٍ، أَحْسِبُ: فَبَعَثَهُمَا عَلِيٌّ رَضِيَ اللهُ عَنْهُ وَجْهًا وَقَالَ: إِنَّكُمَا عِلْجَانِ فَعَالِجَا عَنْ دِينِكُمَا. ثُمَّ قَامَ فَدَخَلَ الْمَخْرَجَ، ثُمَّ خَرَجَ فَدَعَا بِمَاءٍ فَأَخَذَ مِنْهُ حَفْنَةً فَتَمَسَّحَ بِهَا، ثُمَّ جَعَلَ يَقْرَأُ الْقُرْآنَ، فَأَنْكَرُوا ذَلِكَ، فَقَالَ إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْرُجُ مِنَ الْخَلاَءِ فَيُقْرِئُنَا الْقُرْآنَ، وَيَأْكُلُ مَعَنَا اللَّحْمَ، وَلَمْ يَكُنْ يَحْجُبُهُ – أَوْ قَالَ: يَحْجُزُهُ – عَنِ الْقُرْآنِ شَيْءٌ، لَيْسَ الْجَنَابَةَ. (د,ت,ن,جه)', 'അബ്ദുള്ളാഹിബ്നു സലമ(റ): അദ്ദേഹം പറയുന്നു: ഞാൻ രണ്ടാളുകളോടൊപ്പം അലി(റ)യുടെ അടുക്കലേക്കു കടന്നു ചെന്നു. രണ്ടു പേരിലൊരാൾ ഞങ്ങളുടെ ഗോത്രത്തിൽ പ്പെട്ടവനും മറ്റെയാൾ അസദ് ഗോത്രക്കാരനുമായിരുന്നു. അവരെ രണ്ടു പേരെയും അലി(റ) ഒരു പ്രദേശത്തേക്ക് നിയോഗിച്ചയച്ചു കൊണ്ടു പറഞ്ഞു: നിങ്ങൾ രണ്ടു പേരും കായികബലവും ഊർജ്ജസ്വലതയുമുള്ളവരാണ്. ആയതിനാൽ നിങ്ങൾ രണ്ടുപേരും നിങ്ങളുടെ മതത്തിനു (ഇസ്ലാമിനു) വേണ്ടി ഈ കരുത്ത് ഉപയോഗപ്പെടുത്തുക''. അനന്തരം അദ്ദേഹം എഴുന്നേറ്റ് വിസർജ്ജന സ്ഥലത്തേക്ക് പ്രവേശിച്ചു. ശേഷം അവിടെ നിന്നും പുറത്തു വന്ന് വെള്ളം ആവശ്യപ്പെടുകയും കൈക്കുമ്പിൾ നിറയെ വെള്ളമെടുക്കുകയും ചെയ്തു. തുടന്ന് (ഇരു കൈകളും) അതുകൊണ്ട് ഉരച്ചു കഴുകി. എന്നിട്ടദ്ദേഹം ഖുർആൻ പാരായണം ചെയ്യാൻ തുടങ്ങി. ഇതു കണ്ടപ്പോൾ അവർ ആശ്ചര്യഭരിതരായി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) വിസർജ്ജനസ്ഥലത്തുനിന്ന് പുറത്തു വരികയും അനന്തരം ഞങ്ങളോടൊപ്പം മാസം കഴിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. വലിയ അശുദ്ധിയുണ്ടാവുക എന്നതൊഴികെ മറ്റൊന്നും ഖുർആൻ പാരായണത്തിൽ നിന്നും തിരുമേനിയെ തടഞ്ഞിട്ടില്ല. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ سَلَمَةَ قَالَ', 'അബ്ദുള്ളാഹിബ്നു സലമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 218, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اعْتَكَفَ مَعَهُ بَعْضُ نِسَائِهِ، وَهِيَ مُسْتَحَاضَةٌ، تَرَى الدَّمَ. وَرُبَّمَا وَضَعَتِ الطَّسْتَ تَحْتَهَا مِنَ الدَّمِ. (خ)', 'ആഇശ(റ): നബി(സ)യോടൊപ്പം അവിടുത്തെ പത്നിമാരിൽ ചിലർ അവർക്ക് അമിതമായി രക്തം പോകുന്നത് കണ്ടിരിക്കെ തന്നെ ഇഅ്തികാഫ് ഇരിക്കാറുണ്ടായിരുന്നു. അങ്ങനെ രക്തത്തിന്റെ ആധിക്യം കാരണത്താൽ അവർ ചുവട്ടിൽ താലം വെക്കുമായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 219, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كُنَّا نُنْهَى أَنْ نُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلاَثٍ إِلَّا عَلَى زَوْجٍ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا وَلَا نَكْتَحِلَ، وَلَا نَتَطَيَّبَ، وَلَا نَلْبَسَ ثَوْبًا مَصْبُوغًا، إِلَّا ثَوْبَ عَصْبٍ. وَقَدْ رُخِّصَ لَنَا عِنْدَ الطُّهْرِ، إِذَا اغْتَسَلَتْ إِحْدَانَا مِنْ مَحِيضِهَا فِي نُبْذَةٍ مِنْ كُسْتِ أَظْفَارٍ، وَكُنَّا نُنْهَى عَنِ اتِّبَاعِ الْجَنَائِزِ. (خ)', 'ഉമ്മുഅത്വിയ്യ(റ): ഭർത്താവ് മരിച്ചാൽ നാല് മാസവും പത്ത് ദിവസവും ദുഃഖമാചരിക്കുക എന്നതൊഴികെ ഒരാൾ മരിച്ചാൽ മൂന്നു ദിവസത്തിലധികം ദുഖമാചരിക്കുന്നതിൽ നിന്ന് ഞങ്ങൾ വിലക്കപ്പെട്ടിരുന്നു. ഇക്കാലയളവിൽ സുഗന്ധം പൂശുകയോ, സുറുമയിടുകയോ, ചായം പിടിപ്പിച്ച താഴ്ന്ന നൂലുകൊണ്ടുള്ള വസ്ത്രങ്ങൾ അല്ലാതെ ചായം പിടിപ്പിച്ച വസ്ത്രം അണിയുന്നതും ഞങ്ങൾക്ക് വിലക്കി. എന്നാൽ ശുദ്ധിയാവുമ്പോൾ ആർത്തവത്തിൽ നിന്ന് കുളിക്കുമ്പോൾ ''കുസ്ത് അള്ഫാർ'' (ഒരു സുഗന്ധ ദ്രവ്യം) ഉയോഗിക്കാൻ ഞങ്ങളെ അനുവദിച്ചിരുന്നു. എന്നാൽ മയ്യിത്തിനെ അനുഗമിക്കുന്നതിൽ നിന്ന് ഞങ്ങൾ വിലക്കപ്പെട്ടു. (ബു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 219, 219, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَهْلَلْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَجَّةِ الْوَدَاعِ، فَكُنْتُ مِمَّنْ تَمَتَّعَ، وَلَمْ يَسُقِ الْهَدْيَ، فَزَعَمَتْ أَنَّهَا حَاضَتْ، وَلَمْ تَطْهُرْ حَتَّى دَخَلَتْ لَيْلَةُ عَرَفَةَ، فَقَالَتْ: يَا رَسُولَ اللهِ هَذِهِ لَيْلَةُ عَرَفَةَ، وَإِنَّمَا كُنْتُ تَمَتَّعْتُ بِعُمْرَةٍ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْقُضِي رَأْسَكِ، وَامْتَشِطِي، وَأَمْسِكِي عَنْ عُمْرَتِكِ". فَفَعَلْتُ، فَلَمَّا قَضَيْتُ الْحَجَّ، أَمَرَ عَبْدَالرَّحْمَنِ لَيْلَةَ الْحَصْبَةِ، فَأَعْمَرَنِي مِنَ التَّنْعِيمِ مَكَانَ عُمْرَتِي الَّتِي نَسَكْتُ. (خ)', 'ആഇശ(റ): ഹജ്ജത്തുൽ വദാഇൽ നബി(സ)യോടൊപ്പം ഞാൻ ഇഹ്റാം ചെയ്തു. ബലിമൃഗങ്ങളെ കൊണ്ടു പോവാതിരിക്കുകയും, ഹജ്ജിനു മുമ്പ് ഉംറക്കു വേണ്ടി മാത്രം ഇഹ്റാം കെട്ടുകയും ചെയ്തവരുടെ വിഭാഗത്തലാണ് ഞാൻ പെട്ടിരുന്നത്. മഹതി പറയുന്നു: എനിക്ക് ആർത്തവമാരംഭിച്ചു. അറഫാദിന രാവിലാണ് ഞാൻ ശുദ്ധിയായത്. മഹതി പറഞ്ഞു: നബിയേ, ഇത് അറഫായുടെ നാളിന്റെ രാവാണ്, ഞാൻ ഹജ്ജിനുമുമ്പ് ഉംറക്കു മാത്രം ഇഹ്റാം കെട്ടിയതുമാണ്. നബി(സ) പറഞ്ഞു: "നീ നിന്റെ മുടിയുടെ കെട്ടഴിക്കുക, മുടി ചീകിക്കൊള്ളുക, ഉംറയുടെ നടപടികൾ നിർത്തിവെക്കുക." ഞാൻ അപ്രകാരം ചെയ്തു. ഹജ്ജിൽ പ്രവേശിച്ചു കഴിഞ്ഞപ്പോൾ അബ്ദുർറഹ്മാൻ(റ) (എന്റെ സഹോദരൻ) ഹസ്ബായുടെ (ചരൽകല്ല്) രാത്രി നബി(സ) കൽപിച്ച പ്രകാരം തൻഈമിൽ നിന്ന് എന്റെ നേരത്തെയുള്ള ഉംറക്കു പകരമായി എന്നെ ഉംറ ചെയ്യിച്ചു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 219, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مُوَافِينَ لِهِلاَلِ ذِي الْحِجَّةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ أَنْ يُهِلَّ بِعُمْرَةٍ فَلْيُهْلِلْ، فَإِنِّي لَوْلاَ أَنِّي أَهْدَيْتُ لَأَهْلَلْتُ بِعُمْرَةٍ". فَأَهَلَّ بَعْضُهُمْ بِعُمْرَةٍ، وَأَهَلَّ بَعْضُهُمْ بِحَجٍّ، وَكُنْتُ أَنَا مِمَّنْ أَهَلَّ بِعُمْرَةٍ، فَأَدْرَكَنِي يَوْمُ عَرَفَةَ وَأَنَا حَائِضٌ، فَشَكَوْتُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "دَعِي عُمْرَتَكِ، وَانْقُضِي رَأْسَكِ، وَامْتَشِطِي، وَأَهِلِّي بِحَجٍّ". فَفَعَلْتُ، حَتَّى إِذَا كَانَ لَيْلَةُ الْحَصْبَةِ أَرْسَلَ مَعِي أَخِي عَبْدَالرَّحْمَنِ بْنِ أَبِي بَكْرٍ، فَخَرَجْتُ إِلَى التَّنْعِيمِ، فَأَهْلَلْتُ بِعُمْرَةٍ مَكَانَ عُمْرَتِي، وَلَمْ يَكُنْ فِي شَيْءٍ مِنْ ذَلِكَ هَدْيٌ، وَلاَ صَوْمٌ، وَلاَ صَدَقَةٌ. (خ)', 'ആഇശ(റ): ദുൽഹിജജ മാസപ്പിറവി കണ്ടയുടനെ ഞങ്ങൾ (ഹജ്ജിന്) പുറപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "വല്ലവനും ഉംറക്കുമാത്രം ഇഹ്റാം കെട്ടാനുദ്ദേശിക്കുന്നുവെങ്കിൽ അവൻ അങ്ങനെ ചെയ്തു കൊള്ളട്ടെ. ബലിമൃഗങ്ങളെ കൂടെ കൊണ്ടുവന്നിരുന്നില്ലെങ്കിൽ ഞാനും ഉംറക്കുമാത്രം ഇഹ്റാം കെട്ടുമായിരുന്നു. ഞങ്ങളിൽ ചിലർ ഉംറക്കും, ചിലർ ഹജ്ജിനും ഇഹ്റാം കെട്ടി. ഉംറക്കു വേണ്ടി മാത്രം ഇഹ്റാം കെട്ടിയവരിലായിരുന്നു ഞാൻ. അറഫാ ദിന രാവിൽ എനിക്ക് ആർത്തവമുണ്ടായി. നബി (സ)യോട് ഞാൻ പരാതിപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "നീ നിന്റെ ഉംറ ഒഴിവാക്കുക, മുടി കെട്ടഴിക്കുകയും, ചീകുകയും ചെയ്യുക പിന്നെ ഹജ്ജിന് ഇഹ്റാം കെട്ടുക. ഞാൻ അപ്രകാരം ചെയ്തു. ചരൽകല്ല് രാത്രി (മുസ്ദലിഫയിൽ രാപാർക്കുന്ന രാത്രി) എന്റെ സഹോദരൻ അബ്ദുർറഹ്മാനെ(റ)യും എന്റെ കൂടെ അയച്ചു. ഞാൻ തൻഈമിലേക്കു പോയി. എന്റെ ആദ്യ ഉംറയുടെ സ്ഥാനത്ത് ഞാൻ ഉംറക്ക് ഇഹ്റാം ചെയ്തു. എനിക്ക് ഒന്നിലും ബലി കഴിക്കേണ്ടതായോ നോമ്പ് നോൽക്കേണ്ടതായോ, ദാനം ചെയ്യേണ്ടതയോ വന്നില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً قَالَتْ لَهَا: أَتُجْزِي إِحْدَانَا صَلاَتَهَا إِذَا طَهُرَتْ؟ فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ كُنَّا نَحِيضُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلاَ يَأْمُرُنَا بِهِ، أَوْ قَالَتْ: فَلاَ نَفْعَلُهُ. (خ,ن)', 'ആഇശ(റ): ഒരു സ്ത്രീ മഹതിയോട് ചോദിച്ചു: സ്ത്രീ ആർത്തവമില്ലാതെ ശുദ്ധിയായിരിക്കുമ്പോൾ മാത്രം നിസ്കരിച്ചാൽ മതിയാവുമോ? മഹതി ചോദിച്ചു: നീ ''ഹറൂരിയ്യ''¹ സംഘത്തിൽ പെട്ടയാളാണോ? ആർത്തവ ദിവസങ്ങളിൽ ഞങ്ങൾ നബി(സ) യോട് കൂടെയാരിക്കെ ഞങ്ങളോട് നിസ്കരിക്കാൻ കൽപിച്ചിരുന്നില്ല. അല്ലെങ്കിൽ അവർ പറഞ്ഞു: ഞങ്ങൾ അങ്ങനെ ചെയ്തിരുന്നില്ല. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', '¹. അലി(റ)ക്കെതിരിൽ ''ഹറൂറ'' എന്ന സ്ഥലത്തുനിന്നും സംഘടിച്ച ''ഖവാരിജി'' കക്ഷിയാണ് ഹറൂരിയ്യ. ആർത്തവഘട്ടത്തിൽ വിട്ടുപോയ നിസ്കാരങ്ങളെല്ലാം ശുദ്ധികാലയളവൽ വീട്ടണമെന്ന് അവർ വാദിച്ചിരുന്നതായി കാണാം.', null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 220, 220, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ مُعَاذَةَ الْعَدَوِيَّةِ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلْتُ عَائِشَةَ: فَقُلْتُ: مَا بَالُ الْحَائِضِ تَقْضِي الصَّوْمَ وَلاَ تَقْضِي الصَّلاَةَ؟ فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ قُلْتُ: لَسْتُ بِحَرُورِيَّةٍ، وَلَكِنِّي أَسْأَلُ. قَالَتْ: كَانَ يُصِيبُنَا ذَلِكَ، فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ، وَلاَ نُؤْمَرُ بِقَضَاءِ الصَّلاَةِ. (ق,ت,ن,جه)', 'മുആദതുൽ അദവിയ്യ(റ): ഒരു സ്ത്രീ ആഇശ(റ)യോട് ചോദിച്ചു: ആർത്തവകാരി നിസ്കാരം വീട്ടേണ്ടതുണ്ടോ? ആഇശ(റ) ചോദിച്ചു: നീ ''ഹറൂരിയത്ത്'' ആണോ? അവൾ പറഞ്ഞു: ''അല്ല, എങ്കിലും ഞാൻ ചോദിക്കുകയാണ്.'' മഹതി പറഞ്ഞു: നബി(സ)യുടെ അടുത്തുനിന്ന് ഞങ്ങൾക്ക് ആർത്തവമുണ്ടാവാറുണ്ടായിരുന്നു. നോമ്പു വീട്ടാൻ ഞങ്ങൾ കൽപിക്കപ്പെട്ടിരുന്നു. പക്ഷെ നിസ്കാരം വീട്ടാൻ കൽപിക്കപ്പെട്ടിരുന്നില്ല. (ബു,മു,തു,ന,ജ)', 'مُعَاذَةَ الْعَدَوِيَّةِ', 'മുആദതുൽ അദവിയ്യ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: بَيْنَمَا أَنَا مُضْطَجِعَةٌ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمِيلَةِ إِذْ حِضْتُ، فَانْسَلَلْتُ فَأَخَذْتُ ثِيَابَ حَيْضَتِي، فَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنُفِسْتِ؟" قُلْتُ: نَعَمْ، فَدَعَانِي فَاضْطَجَعْتُ مَعَهُ فِي الْخَمِيلَةِ، قَالَتْ: وَكَانَتْ هِيَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلاَنِ فِي الْإِنَاءِ الْوَاحِدِ مِنَ الْجَنَابَةِ. (ق,ن,جه)', 'ഉമ്മുസലമ(റ): ഒരിക്കൽ ഞാൻ നബി(സ)യോടൊപ്പം ഒരു പുതപ്പിൽ കിടന്നുറങ്ങുന്നതിനിടയിൽ എനിക്ക് ആർത്തവമുണ്ടായി. ഞാൻ മെല്ലെ അവിടെ നിന്നെഴുന്നേറ്റുപോയി ആർത്തവ ഘട്ടത്തിൽ ധരിക്കാറുള്ള വസ്ത്രം മാറ്റി ധരിച്ചു. നബി(സ) ചോദിച്ചു: "നിനക്കാർത്തവമുണ്ടായോ?" ഞാൻ പറഞ്ഞു: അതെ, അപ്പോൾ നബി(സ) എന്നെ വിളിച്ചു. എന്നിട്ട് നബി(സ)യോടൊപ്പം ഒരേ പുതപ്പിൽ ഞാൻ കിടന്നു. മഹതി പറഞ്ഞു: ഞാനും നബി(സ)യും ഒരേ പാത്രത്തിൽ നിന്ന് ജനാബത്തു കുളി നിർവ്വഹിച്ചിരുന്നു. (ബു,മു,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ حَدِيثُ حَيْضَتِهَا وَهِيَ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْخَمِيلَةِ. ثُمَّ قَالَتْ فِي هَذِهِ الرِّوَايَةِ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ. (خ)', 'ഉമ്മുസലമ(റ): അവർ നബി(സ)യോടൊന്നിച്ച് ഒറ്റ പുതപ്പിൽ കിടന്നുറങ്ങുമ്പോൾ ആർത്തവമുണ്ടായ സംഭവം വിവരിക്കുന്നു. ഈ റിപ്പോർട്ടിൽ ഉമ്മുസലമ പറയുന്നു: നബി(സ) നോമ്പുകാരനായിരിക്കെ മഹതിയെ ചുംബിച്ചിരുന്നു. (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيتُ فِي الشِّعَارِ الْوَاحِدِ وَأَنَا طَامِثٌ حَائِضٌ، فَإِنْ أَصَابَهُ مِنِّي شَيْءٌ غَسَلَ مَكَانَهُ لَمْ يَعْدُهُ، ثُمَّ صَلَّى فِيهِ، ثُمَّ يَعُودُ فَإِنْ أَصَابَهُ مِنِّي شَيْءٌ فَعَلَ مِثْلَ ذَلِكَ: غَسَلَ مَكَانَهُ لَمْ يَعْدُهُ وَصَلَّى فِيهِ. (د,ن)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കെ ഞാനും നബി(സ)യും ഒരേ വിരിപ്പിൽ കിടക്കാറുണ്ടായിരുന്നു. എന്നിൽ നിന്ന് വല്ലതും നബി(സ)യുടെ ദേഹത്തു പുരണ്ടാൽ ആ ഭാഗം മാത്രം കഴുകുകയും, ആ വസ്ത്രത്തിൽ തന്നെ നിസ്കരിക്കുകയും ചെയ്യും. പിന്നെ മടങ്ങി വന്ന് എന്നിൽ നിന്ന് വല്ലതും ദേഹത്തു പുരണ്ടാൽ ആ ഭാഗം മാത്രം കഴുകി നിസ്കരിക്കും. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 221, 221, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ حَفْصَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتْ أُمُّ عَطِيَّةَ لاَ تَذْكُرُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا قَالَتْ: بِأَبَا، فَقُلْتُ: أَسَمِعْتِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ كَذَا وَكَذَا، قَالَتْ: نَعَمْ بِأَبَا, قَالَ: "لِتَخْرُجِ الْعَوَاتِقُ وَذَوَاتُ الْخُدُورِ، وَالْحُيَّضُ فَيَشْهَدْنَ الْخَيْرَ، وَدَعْوَةَ الْمُسْلِمِينَ، وَتَعْتَزِلِ الْحُيَّضُ الْمُصَلَّى". (ن)', 'ഹഫ്സ്വ(റ): ഉമ്മുഅത്വിയ്യ(റ) നബി(സ)യുടെ നിസ്കാരത്തെപ്പറ്റി പറയുമ്പോഴെല്ലാം എന്റെ പിതാവിനെ സത്യം. എന്നു പറയാറുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: നബി(സ) അപ്രകാരം പറയുന്നതായി നീ കേട്ടിട്ടുണ്ടാ? അപ്പോൾ ഉമ്മുഅതിയ്യ(റ) പറഞ്ഞു: അതെ, എന്റെ പിതാവിനെ സത്യം. നബി(സ) പറഞ്ഞു: "മോചനം ലഭിച്ച അടിമ സ്ത്രീകളും മൂടുപടം ധരിച്ചവരും ആർത്തവകാരികളും (മുസല്ലായിലേക്ക്) പുറപ്പെടണം. നല്ല കാര്യങ്ങളിൽ അവർ പങ്കാളികളാവുകയും മുസ്ലിംകളുടെ പ്രാർത്ഥനയിൽ പങ്കെടുക്കുകയും ചെയ്യട്ടെ. ആർത്തവകാരികൾ നിസ്കാരത്തിൽ നിന്ന് ഒഴിഞ്ഞു നിൽക്കട്ടെ." (ന)', 'حَفْصَةَ', 'ഹഫ്സ്വ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 221, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَضِيَ عَنْهَا – أَنَّهَا قَالَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ إِنَّ صَفِيَّةَ قَدْ حَاضَتْ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَعَلَّهَا تَحْبِسُنَا، أَلَمْ تَكُنْ طَافَتْ مَعَكُنَّ؟" فَقَالُوا: بَلَى، قَالَ: "فَاخْرُجِي". (خ,ن)', 'ആഇശ(റ): അവർ നബി(സ)യോട് ചോദിച്ചു: സ്വഫിയ്യക്ക് ആർത്തവമുണ്ടായി. നബി(സ) പറഞ്ഞു: "അവൾ നമ്മുടെ തിരിച്ചുപോക്ക് പിന്തിപ്പിച്ചേക്കാം. അവൾ നിങ്ങൾക്കൊപ്പം ത്വവാഫ് ചെയ്തിരുന്നില്ലയോ?" അവർ പറഞ്ഞു: അതെ, നബി(സ) പറഞ്ഞു: "എങ്കിൽ നീ പുറപ്പെടുക." (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَضِيَ عَنْهَا – أَنَّهَا كَانَتْ تَكُونُ حَائِضًا لاَ تُصَلِّي وَهِيَ مُفْتَرِشَةٌ بِحَذَاءِ مَسْجِدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ يُصَلِّي عَلَى خُمْرَتِهِ، إِذَا سَجَدَ أَصَابَنِي بَعْضُ ثَوْبِهِ. (خ)', 'മൈമൂന(നബി(സ)യുടെ ഭാര്യ)(റ): അവർക്ക് ആർത്തവമുണ്ടാവുമ്പോൾ അവർ നിസ്കരിക്കാറില്ല. എന്നാൽ നബി(സ) പായയിൽ നിസ്കരിക്കുമ്പോൾ അവർ നബിയുടെ പള്ളിയുടെ ചുമരിനോട് തിരിഞ്ഞു കിടക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അവർ പറയുന്നു: നബി(സ) സുജൂദ് ചെയ്യുമ്പോൾ വസ്ത്രം എന്റെ ശരീരത്തിൽ തട്ടാറുണ്ടായിരുന്നു. (ബു)', 'مَيْمُونَةَ', 'മൈമൂന(നബി(സ)യുടെ ഭാര്യ)(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 222, 222, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَسْمَاءَ رَضِيَ اللهُ عَنْهَا سَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ غُسْلِ الْمَحِيضِ؟ فَقَالَ: "تَأْخُذُ إِحْدَاكُنَّ مَاءَهَا وَسِدْرَتَهَا فَتَطَهَّرُ فَتُحْسِنُ الطُّهُورَ، ثُمَّ تَصُبُّ عَلَى رَأْسِهَا فَتَدْلُكُهُ دَلْكًا شَدِيدًا، حَتَّى تَبْلُغَ شُؤُونَ رَأْسِهَا، ثُمَّ تَصُبُّ عَلَيْهَا الْمَاءَ، ثُمَّ تَأْخُذُ فِرْصَةً مُمَسَّكَةً فَتَطَهَّرُ بِهَا". فَقَالَتْ أَسْمَاءُ: وَكَيْفَ تَطَهَّرُ بِهَا؟ فَقَالَ: "سُبْحَانَ اللهِ، تَطَهَّرِينَ بِهَا". فَقَالَتْ عَائِشَةُ:–كَأَنَّهَا تُخْفِي ذَلِكَ– تَتَبَّعِينَ أَثَرَ الدَّمِ. وَسَأَلْتُهُ عَنْ غُسْلِ الْجَنَابَةِ؟ فَقَالَ: "تَأْخُذُ مَاءً فَتَطَهَّرُ فَتُحْسِنُ الطُّهُورَ– أَوْ تُبْلِغُ الطُّهُورَ– ثُمَّ تَصُبُّ عَلَى رَأْسِهَا، فَتَدْلُكُهُ حَتَّى تَبْلُغَ شُؤُونَ رَأْسِهَا، ثُمَّ تُفِيضُ عَلَيْهَا الْمَاءَ". فَقَالَتْ عَائِشَةُ: نِعْمَ النِّسَاءُ نِسَاءُ الْأَنْصَارِ، لَمْ يَكُنْ يَمْنَعُهُنَّ الْحَيَاءُ أَنْ يَتَفَقَّهْنَ فِي الدِّينِ. (م)', 'ആഇശ(റ): ആർത്തവശുദ്ധിക്കുള്ള കുളിയെപ്പറ്റി അസ്മാഅ്(റ) നബി(സ)യോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വെള്ളവും താളിയുമപയോഗിച്ച് നന്നായി വൃത്തിയാക്കുക. പിന്നെ തലയിൽ വെള്ളമൊഴിച്ച് തലയുടെ മുഴുവൻ ഭാഗത്തും എത്തുന്ന നിലക്ക് നന്നായി തേച്ചുകഴുകുക. പിന്നെയും വെള്ളമൊഴിക്കുക. ശേഷം ഒരുപിടി പരുത്തിയുപയോഗിച്ച് വൃത്തിയാക്കുക." അപ്പോൾ അസ്മാഅ്(റ) ചോദിച്ചു: അതുകൊണ്ട് എങ്ങനെയാണ് ശുദ്ധിയാവുക? നബി(സ) പറഞ്ഞു: "അല്ലാഹു എത്ര പരിശുദ്ധൻ!, നീ അതുകൊണ്ട് വൃത്തിയാക്കുക." ആഇശ(റ) പതുക്കെ പറഞ്ഞു: നീ രക്തപ്പാടുകൾ അതുകൊണ്ട് തുടക്കണം. ജനാബത്ത് കുളിയെക്കുറിച്ച് അസ്മാഅ് നബി(സ)യോട് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ വെള്ളമെടുത്ത് നന്നായി ശുദ്ധിയാക്കുക, പിന്നെ വെള്ളം തലയിലൊഴിക്കുക." ആഇശ(റ) പറഞ്ഞു: അൻസ്വാരിസ്ത്രീകൾ എത്ര നല്ലവർ! മതകാര്യങ്ങൾ പഠിക്കുന്നതിൽ നിന്ന് ലജ്ജ അവർക്ക് തടസ്സമായിട്ടില്ല. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 222, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَبْدِ اللهِ بْنِ يَزِيدَ الْخَطْمِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ فِي الْمُسْتَحَاضَةِ: "تَدَعُ الصَّلاَةَ أَيَّامَ أَقْرَائِهَا، الَّتِي كَانَتْ تَحِيضُ فِيهَا، ثُمَّ تَغْتَسِلُ وَتَتَوَضَّأُ عِنْدَ كُلِّ صَلاَةٍ، وَتَصُومُ، وَتُصَلِّي". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു യസീദുൽ ഖുത്വമി(റ): രക്തസ്രാവമുള്ള സ്ത്രീയെപ്പറ്റി നബി(സ) പറഞ്ഞു: "അവൾ സാധാരണ ആർത്തവമുണ്ടാവാറുള്ള ദിവസങ്ങളിലെ നിസ്കാരം ഒഴിവാക്കണം. പിന്നെ ഓരോ നിസ്കാരത്തിനും കുളിക്കുകയും വുദൂ ചെയ്യുകയും വേണം. അവർ നോമ്പനുഷ്ഠിക്കുകയും, നിസ്കരിക്കുകയും വേണം." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ يَزِيدَ الْخَطْمِيِّ', 'അബ്ദുല്ലാഹിബ്നു യസീദുൽ ഖുത്വമി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 223, 223, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ حَمْنَةَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أُسْتَحَاضُ حَيْضَةً كَثِيرَةً شَدِيدَةً، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَسْتَفْتِيهِ، وَأُخْبِرُهُ فَوَجَدْتُهُ فِي بَيْتِ أُخْتِي زَيْنَبَ بِنْتِ جَحْشٍ، فَقُلْتُ: يَا رَسُولَ اللهِ، إِنِّي أُسْتَحَاضُ حَيْضَةً كَثِيرَةً شَدِيدَةً، فَمَا تَأْمُرُنِي فِيهَا، قَدْ مَنَعَتْنِي الصِّيَامَ وَالصَّلاَةَ؟ قَالَ: "أَنْعَتُ لَكِ الْكُرْسُفَ، فَإِنَّهُ يُذْهِبُ الدَّمَ". قَالَتْ: هُوَ أَكْثَرُ مِنْ ذَلِكَ، قَالَ: "فَتَلَجَّمِي". قَالَتْ: هُوَ أَكْثَرُ مِنْ ذَلِكَ؟ قَالَ: "فَاتَّخِذِي ثَوْبًا". قَالَتْ: هُوَ أَكْثَرُ مِنْ ذَلِكَ؟ إِنَّمَا أَثُجُّ ثَجًّا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَآمُرُكِ بِأَمْرَيْنِ، أَيَّهُمَا صَنَعْتِ أَجْزَأَ عَنْكِ، فَإِنْ قَوِيتِ عَلَيْهِمَا فَأَنْتِ أَعْلَمُ". فَقَالَ: "إِنَّمَا هِيَ رَكْضَةٌ مِنَ الشَّيْطَانِ، فَتَحَيَّضِي سِتَّةَ أَيَّامٍ أَوْ سَبْعَةَ أَيَّامٍ فِي عِلْمِ اللهِ، ثُمَّ اغْتَسِلِي، فَإِذَا رَأَيْتِ أَنَّكِ قَدْ طَهُرْتِ وَاسْتَنْقَأْتِ، فَصَلِّي أَرْبَعًا وَعِشْرِينَ لَيْلَةً، أَوْ ثَلاَثًا وَعِشْرِينَ لَيْلَةً وَأَيَّامَهَا، وَصُومِي وَصَلِّي، فَإِنَّ ذَلِكِ يُجْزِئُكِ. وَكَذَلِكِ فَافْعَلِي كَمَا تَحِيضُ النِّسَاءُ وَكَمَا يَطْهُرْنَ لِمِيقَاتِ حَيْضِهِنَّ وَطُهْرِهِنَّ. فَإِنْ قَوِيتِ عَلَى أَنْ تُؤَخِّرِي الظُّهْرَ وَتُعَجِّلِي الْعَصْرَ، ثُمَّ تَغْتَسِلِينَ حِينَ تَطْهُرِينَ، وَتُصَلِّينَ الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ تُؤَخِّرِينَ الْمَغْرِبَ، وَتُعَجِّلِينَ الْعِشَاءَ، ثُمَّ تَغْتَسِلِينَ وَتَجْمَعِينَ بَيْنَ الصَّلاَتَيْنِ، فَافْعَلِي وَتَغْتَسِلِينَ مَعَ الصُّبْحِ، وَتُصَلِّينَ. وَكَذَلِكِ فَافْعَلِي، وَصُومِي إِنْ قَوِيتِ عَلَى ذَلِكِ". فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَهُوَ أَعْجَبُ الْأَمْرَيْنِ إِلَيَّ". (د,ت,ن,جه)', 'ഹംന(റ): എനിക്ക് ശക്തമായ ആർത്തവമുണ്ടാവാറുണ്ടായിരുന്നു. അതിനെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കുവാനും കാര്യങ്ങൾ പറയുവാനുമായി ഞാൻ ചെന്നു. അപ്പോൾ നബി(സ) എന്റെ സഹോദരി സൈനബിന്റെ (പ്രവാചക പത്നി) വീട്ടിലായിരുന്നു. ഞാൻ ചോദിച്ചു: നബിയേ, എനിക്ക് ശക്തമായ ആർത്തവമുണ്ടാവാറുണ്ട്. അങ്ങെന്താണെനിക്കു നിർദ്ദേശിക്കുന്നത്? ആർത്തവം എന്റെ നോമ്പും നിസ്കാരവും മുടക്കിയിട്ടുണ്ട്. നബി(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് പരുത്തി വെക്കാൻ നിർദ്ദേശിക്കുന്നു. അത് രക്തം പോക്കിക്കളയും (ഒലിക്കുന്നത് തടയും)." അവർ പറഞ്ഞു: രക്തം അതിലും കൂടുതലാണ്. നബി(സ) പറഞ്ഞു: "നീ വെച്ചുകെട്ടുക." അവർ പറഞ്ഞു: രക്തം അതിലും കൂടുതലാണ്. നബി(സ) പറഞ്ഞു: "കെട്ടിനു താഴെ ഒരു തുണിക്കഷ്ണവും വെക്കുക." അവർ പറഞ്ഞു: രക്തം അതിലും കൂടുതലാണ്. അതി ശക്തമായ രക്തസ്രാവ മുള്ളതായി അനുഭവപ്പെടുന്നു. നബി (സ) പറഞ്ഞു: "നിനക്ക് (ചെയ്യാൻ വേണ്ടി) ഞാൻ രണ്ട് കാര്യങ്ങൾ കൽപിക്കുന്നു, ഏതു ചെയ്താലും മതി. രണ്ടും ചെയ്യാനറിയുമോയെന്ന് നിനക്കാണ് കൂടുതലറിയുക. ഇപ്രകാരം ഒഴുകുന്നത് പൈശാചികമായ ഒന്നാണ്, നീ അല്ലാഹു കണക്കാക്കിയ പ്രകാരം ആറോ ഏഴോ ദിവസങ്ങൾ ആർത്തവമായി കണക്കാക്കുക. പിന്നെ കുളിക്കുക. ശുദ്ധിയായെന്നറിഞ്ഞാൽ ഇരുപത്തിനാലോ ഇരുപത്തിമൂന്നോ ദിവസം നിസ്കരിക്കുക. നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുക. നിനക്കതുമതി. ഇപ്രകാരം സ്ത്രീകൾക്ക് ആർത്തവവും ശുദ്ധിയുമുണ്ടാവുന്ന കണക്കനുസരിച്ച് നീ പ്രവർത്തിക്കുക; ളുഹ്ർ പിന്തിച്ച് അസ്വ്ർ നേരത്തെയാക്കു കയും പിന്നെ ശുദ്ധിയാകുമ്പോൾ കുളിച്ച് ളുഹ്റും അസ്വ്റും ഒന്നിച്ച് നിസ്കരിക്കുകയും മഗ്രിബ് പിന്തിച്ച് ഇശാഅ് നേരത്തെ നിസ്കരിക്കുകയും പിന്നെ കുളിച്ച് രണ്ടു നിസ്കാരവും ഒന്നിച്ച് നിസ്കരിക്കുകയും ചെയ്യാൻ സാധിച്ചാൽ അപ്രകാരം ചെയ്യുക. സുബ്ഹി നിസ്കാരത്തിന് കുളിക്കുകയും നിസ്കരിക്കുകയും ചെയ്യുക. നീ ഇപ്രകാരം ചെയ്യുക. സാധിക്കുമെങ്കിൽ നോമ്പനുഷ്ഠിക്കുക." നബി (സ) പറഞ്ഞു: "ഇപ്പറഞ്ഞ രീതിയിൽ ചെയ്യലാണ് ഈ രണ്ടെണ്ണത്തിൽ വെച്ച് എനിക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത്." (ദ,തു,ന,ജ)', 'حَمْنَةَ بِنْتِ جَحْشٍ', 'ഹംന(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 223, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ حَمْنَةَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا اسْتُحِيضَتْ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي اسْتُحِضْتُ حَيْضَةً مُنْكَرَةً شَدِيدَةً، قَالَ لَهَا: "احْتَشِي كُرْسُفًا". قَالَتْ لَهُ: إِنَّهُ أَشَدُّ مِنْ ذَلِكَ، إِنِّي أَثُجُّ ثَجًّا. قَالَ: "تَلَجَّمِي وَتَحَيَّضِي فِي كُلِّ شَهْرٍ – فِي عِلْمِ اللهِ – سِتَّةَ أَيَّامٍ أَوْ سَبْعَةَ أَيَّامٍ، ثُمَّ اغْتَسِلِي غُسْلًا، فَصَلِّي وَصُومِي ثَلاَثَةً وَعِشْرِينَ، أَوْ أَرْبَعَةً وَعِشْرِينَ، وَأَخِّرِي الظُّهْرَ، وَقَدِّمِي الْعَصْرَ، وَاغْتَسِلِي لَهُمَا غُسْلًا، وَأَخِّرِي الْمَغْرِبَ، وَعَجِّلِي الْعِشَاءَ، وَاغْتَسِلِي لَهُمَا غُسْلًا، وَهَذَا أَحَبُّ الْأَمْرَيْنِ إِلَيَّ". (د,ت,جه)', 'ഹംന(റ): അവർക്ക് നബി(സ)യുടെ കാലത്ത് ആർത്തവമുണ്ടാവാറുണ്ടായിരുന്നു. അവർ നബി(സ)യുടെ അടുത്തുവന്നു പറഞ്ഞു: എനിക്ക് ശക്തമായ ആർത്തവമുണ്ടാവുന്നു. നബി(സ) പറഞ്ഞു: "നീ പരുത്തി നിറക്കുക." അവർ പറഞ്ഞു: രക്തം അതിലും കൂടുതലാണ്. എനിക്ക് അതി ശക്തമായ രക്തസ്രാവമുള്ളതായി അനുഭവപ്പെടുന്നു. നബി(സ) പറഞ്ഞു: "നീ തുണിക്കഷ്ണം വെച്ച് കെട്ടുകയും മാസത്തിൽ അല്ലാഹു കണക്കാക്കിയ പ്രകാരം ആറോ ഏഴോ ദിവസങ്ങൾ ആർത്തവമായി കണക്കാക്കുകകയും ചെയ്യുക. പിന്നെ കുളിക്കുക. ഇരുപത്തിനാലോ ഇരുപത്തിമൂന്നോ ദിവസം നിസ്കരിക്കുകയും നോമ്പനുഷ്ഠിക്കുകയും ചെയ്യുക. ളുഹ്ർ പിന്തിച്ച് അസ്ർ നേരത്തെയാക്കുകയും രണ്ടിനുമായി ഒരു കുളി കുളിക്കുകയും ചെയ്യുക." ഇതാണ് രണ്ടിൽവെച്ച് എനിക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടത്." (ദ,തു,ജ)', 'حَمْنَةَ بِنْتِ جَحْشٍ', 'ഹംന(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لاَ تَقْرَأِ الْحَائِضُ وَلاَ الْجُنُبُ شَيْئًا مِنَ الْقُرْآنِ". (ت,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ജനാബത്തുകാരനും ആർത്തവകാരിയും ഖുർആനിൽ നിന്ന് ഒന്നും പാരായണം ചെയ്യരുത്." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 224, 224, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَتَى حَائِضًا أَوِ امْرَأَةً فِي دُبُرِهَا، أَوْ كَاهِنًا، فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആർത്തവകാരിയുമായോ സ്ത്രീയുടെ പിൻദ്വാരത്തിലൂടെയോ ആരെങ്കിലും ബന്ധപ്പെട്ടാൽ, അല്ലെങ്കിൽ ഒരു പ്രശ്നം നോക്കുന്നവനെ സമീപിച്ചാൽ, അവൻ മുഹമ്മദ് നബി(സ)യുടെ മേൽ ഇറക്കപ്പെട്ടതിനോട് (ഖുർആൻ) നിഷേധം കാണിച്ചിരിക്കുന്നു." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 224, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتِ النُّفَسَاءُ تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ يَوْمًا، فَكُنَّا نَطْلِي وُجُوهَنَا بِالْوَرْسِ مِنَ الْكَلَفِ. (د,ت,جه)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ കാലത്ത് പ്രസവ രക്തകാരികൾക്ക് നാൽപത് ദിവസം കണക്കാക്കിയിരുന്നു. മുഖത്തെ പാടു കാരണം ഞങ്ങൾ(പ്രസവ രക്തമുള്ളപ്പോൾ) കുങ്കുമം പുരട്ടാറുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَّتَ لِلنُّفَسَاءِ أَرْبَعِينَ يَوْمًا، إِلَّا أَنْ تَرَى الطُّهْرَ قَبْلَ ذَلِكَ. (جه)', 'അനസ്(റ): നബി(സ) പ്രസവ രക്തകാരികൾക്ക് നാൽപതു ദിവസം കണക്കാക്കിയിരുന്നു. അതിന്റെ മുമ്പ് ശുദ്ധി കണ്ടാലൊഴികെ. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ مُسَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: حَجَجْتُ، فَدَخَلْتُ عَلَى أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا، فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، إِنَّ سَمُرَةَ بْنَ جُنْدُبٍ يَأْمُرُ النِّسَاءَ يَقْضِينَ صَلاَةَ الْمَحِيضِ؟ فَقَالَتْ: لاَ يَقْضِينَ، كَانَتِ الْمَرْأَةُ مِنْ نِسَاءِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَقْعُدُ فِي النِّفَاسِ أَرْبَعِينَ لَيْلَةً، لاَ يَأْمُرُهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقَضَاءِ صَلاَةِ النِّفَاسِ. (د)', 'മുസ്സത്ത്(റ): ഞാൻ ഹജ്ജ് ചെയ്ത് ഉമ്മുസലമ(റ)യുടെയടുത്തു ചെന്ന് ചോദിച്ചു: ഉമ്മുൽ മുഅ്മിനീൻ, ജുൻദുബിന്റെ മകൻ സമുറ ആർത്തവകാരികളോട് നഷ്ടപ്പെട്ട നിസ്കാരം വീട്ടാനാവശ്യപ്പെടുന്നുണ്ടല്ലോ. അവർ പറഞ്ഞു: വീട്ടേണ്ടതില്ല, നബി(സ)യുടെ ഭാര്യമാർ പ്രസവ രക്തമുണ്ടായാൽ നാൽപത് ദിവസം ഇരിക്കും. എന്നാൽ നബി(സ) അവരോട് നിസ്കാരം വീട്ടാനാവശ്യപ്പെട്ടിരുന്നില്ല. (ദ)', 'مُسَّةَ', 'മുസ്സത്ത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لاَ نُرَى إِلَّا الْحَجَّ، فَلَمَّا كُنَّا بِسَرِفَ حِضْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، فَقَالَ: "مَا لَكِ أَنُفِسْتِ؟" قُلْتُ: نَعَمْ، قَالَ: "هَذَا أَمْرٌ كَتَبَهُ اللهُ عَزَّ وَجَلَّ عَلَى بَنَاتِ آدَمَ، فَاقْضِي مَا يَقْضِي الْحَاجُّ، غَيْرَ أَنْ لاَ تَطُوفِي بِالْبَيْتِ". قَالَتْ: وَضَحَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ نِسَائِهِ بِالْبَقَرِ. (خ,ن)', 'ആഇശ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം പുറപ്പെട്ടു. ഹജ്ജ് അല്ലാതെ മറ്റൊരു ഉദ്ദേശ്യവും അതിന് ഇല്ലായിരുന്നു. സ്വറഫിൽ എത്തിയപ്പോഴേക്കും എനിക്ക് ആർത്തവം തുടങ്ങി. ഞാൻ കരയാൻ തുടങ്ങി. നബി(സ) ചോദിച്ചു: "നിനക്കെന്തു പറ്റി? ആർത്തവം തുടങ്ങിയോ?" (നിഫാസ് എന്ന പദമാണ് ആർത്തവത്തിനുപയോഗിച്ചത്.) ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അത് ആദം സന്തതികളിലെ സ്ത്രീകൾക്ക് അല്ലാഹു നിശ്ചയിച്ചതാണ്. അതുകൊണ്ട് ത്വവാഫല്ലാത്ത ഹജ്ജിന്റെ മറ്റു കർമ്മങ്ങളെല്ലാം നീ ചെയ്തു കൊള്ളുക." ആഇശ(റ) പറഞ്ഞു: നബി(സ) തന്റെ പത്നിമാർക്ക് വേണ്ടി അന്ന് പശുവിനെയാണ് ബലിഅറുത്തത്. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 225, 225, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا مِنْ بَنِي أَسَدِ قُرَيْشٍ: أَنَّهَا أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَتْ أَنَّهَا تُسْتَحَاضُ، فَزَعَمَتْ أَنَّهُ قَالَ لَهَا: "إِنَّمَا ذَلِكَ عِرْقٌ، فَإِذَا أَقْبَلَتِ الْحَيْضَةُ فَدَعِي الصَّلاَةَ، وَإِذَا أَدْبَرَتْ فَاغْتَسِلِي وَاغْسِلِي عَنْكِ الدَّمَ، ثُمَّ صَلِّي". (ن)', 'ബനൂഅസദിലെ ഫാത്വിമ ബിൻതുഖൈസ്(റ): അവർ നബി(സ)യുടെ അടുത്തുചെന്ന് രക്തസ്രാവത്തെ കുറിച്ച് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അതൊരു ദ്രാവകം മാത്രമാണ്, ആർത്തവം തുടങ്ങിയാൽ നിസ്കാരം ഒഴിവാക്കുക. ആർത്തവം അവസാനിച്ചാൽ കുളിച്ച് വൃത്തിയാവുക. രക്തസ്രാവമുണ്ടങ്കിൽ അത് കഴുകിയശേഷം നിസ്കരിക്കുക." (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ബനൂഅസദിലെ ഫാത്വിമ ബിൻതുഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَقْبَلَتِ الْحَيْضَةُ فَدَعِي الصَّلاَةَ، وَإِذَا أَدْبَرَتْ فَاغْتَسِلِي". (ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ആർത്തവം തുടങ്ങിയാൽ നിസ്കാരം ഒഴിവാക്കുക. അവസാനിച്ചാൽ കുളിച്ച് വൃത്തിയാവുക." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اسْتَفْتَتْ أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنِّي أُسْتَحَاضُ؟ فَقَالَ: "إِنَّ ذَلِكَ عِرْقٌ، فَاغْتَسِلِي ثُمَّ صَلِّي". فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلاَةٍ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ)യോട് ജഹ്ശിന്റെ മകൾ ഉമ്മുഹബീബ ചോദിച്ചു: എനിക്ക് രക്തസ്രാവമുണ്ട്, നിസ്കരിക്കാമോ? നബി(സ) പറഞ്ഞു: "അതൊരു ദ്രാവകം മാത്രമാണ്, നീ അതു കഴുകിക്കളഞ്ഞതിനു ശേഷം നിസ്കരിക്കുക." അവർ ഓരോ നിസ്കാര സമയത്തും അത് കഴുകിക്കളയാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ أُمَّ حَبِيبَةَ سَأَلَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّمِ فَقَالَتْ عَائِشَةُ: رَأَيْتُ مِرْكَنَهَا مَلْآنَ دَمًا، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اغْتَسِلِي". (م,د,ن)', 'ആഇശ(റ): നബി(സ)യോട് ഉമ്മുഹബീബ(റ) രക്തസ്രാവത്തെക്കുറിച്ച് ചോദിച്ചു. ആഇശ(റ) പറയുന്നു: അവരുടെ ''മിർകുൻ''² രക്തം കൊണ്ട് നിറഞ്ഞതായി ഞാൻ കണ്ടു. നബി(സ) അവരോട് പറഞ്ഞു: "നിന്റെ ആർത്തവ നാളുകളിൽ മാത്രം നീ നിസ്കാരം വെടിയുക, അതിനുശേഷം കഴുകി വൃത്തിയാക്കി നിസ്കരിക്കുക." (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', '². കുളിക്കാൻ വെള്ളമെടുക്കുന്ന ഒരുതരം വലിയ പാത്രം', null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَأَلَتِ امْرَأَةٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: إِنِّي أُسْتَحَاضُ فَلاَ أَطْهُرُ، أَفَأَدَعُ الصَّلاَةَ؟ قَالَ: "لاَ، وَلَكِنْ دَعِي قَدْرَ تِلْكَ الْأَيَّامِ وَاللَّيَالِي الَّتِي كُنْتِ تَحِيضِينَ فِيهَا، ثُمَّ اغْتَسِلِي وَاسْتَثْفِرِي وَصَلِّي". (ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ)യോട് ഒരു സ്ത്രീ പറഞ്ഞു: എനിക്ക് രക്തസ്രാവമുണ്ട്, ശുദ്ധിയാവാൻ കഴിയുന്നില്ല. ഞാൻ നിസ്കാരം ഒഴിവാക്കട്ടെയോ? നബി(സ) പറഞ്ഞു: "അരുത്, നിന്റെ ആർത്തവ നാളുകൾ കണക്കാക്കി ആ ദിവസങ്ങളിലെ നിസ്കാരം മാത്രം ഒഴിവാക്കുക. പിന്നെ നീ കഴുകി ഒരു ശീല കൊണ്ട് കെട്ടിവെച്ചതിനു ശേഷം നിസ്കരിക്കുക." (ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 226, 226, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً كَانَتْ تُهَرَاقُ الدَّمَ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، اسْتَفْتَتْ لَهَا أُمُّ سَلَمَةَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لِتَنْظُرْ عَدَدَ اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُ مِنَ الشَّهْرِ قَبْلَ أَنْ يُصِيبَهَا الَّذِي أَصَابَهَا، فَلْتَتْرُكِ الصَّلَاةَ قَدْرَ ذَلِكَ مِنَ الشَّهْرِ، فَإِذَا خَلَّفَتْ ذَلِكَ فَلْتَغْتَسِلْ، ثُمَّ لِتَسْتَثْفِرْ بِالثَّوْبِ، ثُمَّ لِتُصَلِّ". (ن)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ കാലത്ത് ഒരു സ്ത്രീക്ക് അതിയായ രക്തസ്രാവമുണ്ടായി. ഉമ്മുസലമ(റ) അവൾക്കു വേണ്ടി നബി(സ)യോട് സംശയം ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "അവൾക്ക് രക്തസ്രാവമുണ്ടാവുന്നതിനു മുമ്പ് സാധാരണ ഗതിയിൽ ഒരു മാസത്തിൽ എത്ര ദിവസങ്ങളിൽ ആർത്തവമുണ്ടാവാറുണ്ടായിരുന്നുവെന്ന് കണക്കാക്കുക. ഓരോ മാസവും അത്രയും ദിവസങ്ങളിൽ മാത്രം നിസ്കാരം ഒഴിവാക്കട്ടെ. അതു കഴിഞ്ഞാൽ കഴുകി വൃത്തിയാക്കിയതിനു ശേഷം ഒരു തുണിക്കഷ്ണമുപയോഗിച്ച് കെട്ടിവെച്ച് നിസ്കരിക്കട്ടെ." (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 227, 227, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ أُمَّ حبيبة بنت جحش الَّتِي كَانَتْ تحت عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، وَأَنَّهَا اسْتُحِيضَتْ لَا تَطْهُرُ، فَذُكِرَ شَأْنُهَا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَتْ بِالْحَيْضَةِ، وَلَكِنَّهَا رَكْضَةٌ مِنَ الرَّحِمِ، لِتَنْظُرْ قَدْرَ قُرْئِهَا الَّتِي كَانَتْ تَحِيضُ لَهَا فَلْتَتْرُكِ الصَّلَاةَ، ثُمَّ تَنْظُرُ مَا بَعْدَ ذَلِكَ فَلْتَغْتَسِلْ عِنْدَ كُلِّ صَلَاةٍ". (ن)', 'ആഇശ(റ): ജഹ്ശിന്റെ മകൾ ഉമ്മുഹബീബ അബ്ദുർറഹ്മാനുബ്നു ഔഫിനോടൊപ്പമായിരുന്നു. അവർക്ക് രക്തസ്രാവമുണ്ടായി. അത് നിലക്കാതിരുന്നപ്പോൾ വിവരം നബി(സ)യെ ധരിപ്പിച്ചു. നബി(സ) പറഞ്ഞു: "അത് ആർത്തവമല്ല, മറിച്ച് ഗർഭപാത്രത്തിൽ നിന്നുള്ള തള്ള് ആണ്. അവൾ അവളുടെ ആർത്തവ നാളുകൾ എണ്ണിത്തിട്ടപ്പെടുത്തട്ടെ. അതിനു ശേഷം ഓരോ നിസ്കാരത്തിനുമായി കഴുകി വൃത്തിയാക്കി നിസ്കാരത്തിൽ പ്രവേശിക്കട്ടെ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 227, 227, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ ابْنَةَ جَحْشٍ كَانَتْ تُسْتَحَاضُ سَبْعَ سِنِينَ، فَسَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَيْسَتْ بِالْحَيْضَةِ، إِنَّمَا هُوَ عِرْقٌ". فَأَمَرَهَا أَنْ تَتْرُكَ الصَّلَاةَ قَدْرَ أَقْرَائِهَا وَحَيْضَتِهَا، وَتَغْتَسِلَ وَتُصَلِّيَ، فَكَانَتْ تَغْتَسِلُ عِنْدَ كُلِّ صَلَاةٍ. (ن)', 'ആഇശ(റ): ജഹ്ശിന്റെ മകൾക്ക് ഏഴു വർഷം രക്തസ്രാവമുണ്ടായി. നബി(സ)യോട് അതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ആർത്തവമല്ല, ഒരു ദ്രാവകം മാത്രമാണ്." പിന്നീട് അവളോട് ആർത്തവ നാളുകളിൽ മാത്രം നിസ്കാരം ഒഴിവാക്കാൻ കൽപിക്കുകയും മറ്റു ദിവസങ്ങളിൽ കഴുകി വൃത്തിയാക്കി നിസ്കരിക്കാൻ പറയുകയും ചെയ്തു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 227, 227, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ أُمِّ سَلَمَةَ- زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهَا -: أَنَّ امْرَأَةً كَانَتْ تُهَرَاقُ الدِّمَاءَ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَتْ لَهَا أُمُّ سَلَمَةَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لِتَنْظُرْ عِدَّةَ اللَّيَالِي وَالْأَيَّامِ الَّتِي كَانَتْ تَحِيضُهُنَّ مِنَ الشَّهْرِ قَبْلَ أَنْ يُصِيبَهَا الَّذِي أَصَابَهَا، فَلْتَتْرُكِ الصَّلَاةَ قَدْرَ ذَلِكَ مِنَ الشَّهْرِ، فَإِذَا خَلَّفَتْ ذَلِكَ فَلْتَغْتَسِلْ، ثُمَّ لِتَسْتَثْفِرْ بِثَوْبٍ، ثُمَّ لِتُصَلِّ فِيهِ". (د,ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ)യുടെ കാലത്ത് ഒരു സ്ത്രീക്ക് വല്ലാതെ രക്തം ഒലിച്ചിരുന്നു. ഉമ്മുസലമ അവർക്കുവേണ്ടി നബി(സ)യോട് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഈ രോഗമാവുന്നതിനു മുമ്പ് അവർക്ക് ആർത്തവമുണ്ടായിരുന്ന രാപ്പകലുകളുടെ കണക്കെടുക്കുക. ഒരു മാസത്തിൽ അത്രയും ദിവസത്തെ നിസ്കാരങ്ങൾ ഒഴിവാക്കുക. രക്തം ഇല്ലാതായാൽ കുളിക്കണം, പിന്നെ ഒരു തുണി വെച്ചുകെട്ടി നിസ്കരിക്കുകയും ചെയ്യുക." (ദ,ന,ജ)', 'أُمِّ سَلَمَةَ- زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 227, 227, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: إِنَّ أُمَّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا سَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الدَّمِ، فَقَالَتْ عَائِشَةُ: فَرَأَيْتُ مِرْكَنَهَا مَلْآنَ دَمًا، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اغْتَسِلِي". (م,د,ن)', 'ആഇശ(റ): ഉമ്മുഹബീബ(റ) നബി(സ)യോട് രക്ത(സ്രാവ)ത്തെപ്പറ്റി ചോദിച്ചു. ആഇശ(റ) പറയുന്നു: അപ്പോഴവരുടെ ''മിർകൻ'' രക്തം നിറഞ്ഞതായി ഞാൻ കണ്ടു. നബി(സ) പറഞ്ഞു: "ആർത്തവമുണ്ടായിരുന്ന ദിവസങ്ങൾ കണക്കാക്കി പിന്നെ കുളിക്കുക." (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: حَدَّثَتْنِي فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ أَنَّهَا أَمَرَتْ أَسْمَاءَ- أَوْ أَسْمَاءُ رَضِيَ اللهُ عَنْهَا حَدَّثَتْنِي: أَنَّهَا أَمَرَتْهَا فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ - أَنْ تَسْأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَهَا: أَنْ تَقْعُدَ الْأَيَّامَ الَّتِي كَانَتْ تَقْعُدُ، ثُمَّ تَغْتَسِلُ. (د)', 'ഉർവ്വതുബ്നു സുബൈർ(റ): അബൂഹുബൈശിന്റെ മകൾ ഫാത്വിമ എന്നോട് പറഞ്ഞു: അസ്മ(റ) അവരോട് കൽപിച്ചു - അല്ലെങ്കിൽ അസ്മ എന്നോടു പറഞ്ഞു: അവരോട് അബൂഹുബൈശിന്റെ മകൾ ഫാത്വിമ നബി(സ)യോട് ചോദിക്കാൻ കൽപിച്ചു. നബി(സ) പറഞ്ഞു: "ആർത്തവമുണ്ടായിരുന്ന ദിവസം ഇരിക്കുക. പിന്നെ കുളിക്കുക." (ദ)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവ്വതുബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَشَكَتْ إِلَيْهِ الدَّمَ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا ذَلِكَ عِرْقٌ، فَانْظُرِي إِذَا أَتَاكِ قَرْؤُكِ فَلَا تُصَلِّي، وَإِذَا مَرَّ قَرْؤُكِ فَلْتَطَهَّرِي، ثُمَّ صَلِّي مَا بَيْنَ الْقَرْءِ إِلَى الْقَرْءِ". (د,ن,جه)', 'ഫാത്വിമാ ബിൻതുഹുബൈശ്(റ): അവർ നബി(സ)യുടെ അടുത്തു ചെന്ന് രക്തസ്രാവത്തെക്കുറിച്ച് വേവലാതി പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അതൊരു ദ്രാവകം മാത്രമാണ്. നിന്റെ ആർത്തവ ദിവസം വന്നാൽ മാത്രം നീ നിസ്കാരം ഉപേക്ഷിക്കുക. ആർത്തവം കഴിഞ്ഞാൽ അടുത്ത ആർത്തവം വരെ നിസ്കരിക്കുക." (ദ,ന,ജ)', 'فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ', 'ഫാത്വിമാ ബിൻതുഹുബൈശ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: وَقَدْ سَأَلَ امْرَأَةً عَنِ امْرَأَةٍ فَسَدَ حَيْضُهَا وَأُهْرِيقَتْ دَمًا؟ قَالَتْ: فَأَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنْ آمُرَهَا فَلْتَنْظُرْ قَدْرَ مَا كَانَتْ تَحِيضُ فِي كُلِّ شَهْرٍ، وَحَيْضُهَا مُسْتَقِيمٌ، فَلْتَعْتَدَّ بِقَدْرِ ذَلِكَ مِنَ الْأَيَّامِ، ثُمَّ لِتَدَعِ الصَّلَاةَ فِيهِنَّ، أَوْ بِقَدْرِهِنَّ، ثُمَّ لِتَغْتَسِلْ، ثُمَّ لِتَسْتَثْفِرْ بِثَوْبٍ، ثُمَّ لِتُصَلِّ. (د)', 'ആഇശ(റ): ഒരു സ്ത്രീ, സാധാരണ ആർത്തവത്തേക്കാൾ രക്തമൊലിക്കുന്ന ഒരു സ്ത്രീയെപ്പറ്റി ചോദിച്ചു. അവർ പറഞ്ഞു: നബി(സ) അവളേട് ഇപ്രകാരം കൽപിക്കാൻ എന്നോട് പറഞ്ഞു: "ആർത്തവം ശരിയാവുമ്പോൾ എല്ലാ മാസവും ആർത്തവമുണ്ടാവാറുള്ളതിന്റെ (സാധാരണ ഗതിയിൽ ഒരു മാസത്തിൽ എത്ര ദിവസമാണ് ആർത്തവമുണ്ടാവാറുള്ളത് എന്നതിന്റെ) കണക്കെടുക്കുക. പിന്നെ അത്രയും ദിവസം എണ്ണിക്കണക്കാക്കി നിസ്കാരങ്ങൾ ഒഴിവാക്കുക. പിന്നെ കുളിക്കുകയും (രക്തം ഒലിക്കുന്നിടത്ത്) ഒരു തുണിക്കഷ്ണം വെച്ചുകെട്ടി നിസ്കരിക്കുകയും വേണം." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 228, 228, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تُسْتَحَاضُ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كَانَ دَمُ الْحَيْضِ فَإِنَّهُ دَمٌ أَسْوَدُ يُعْرَفُ، فَأَمْسِكِي عَنِ الصَّلَاةِ، وَإِذَا كَانَ الْآخَرُ فَتَوَضَّئِي، فَإِنَّمَا هُوَ عِرْقٌ". (د,ن)', 'ഫാത്വിമ ബിൻതുഹുബൈശ്(റ): രക്തസ്രാവമുള്ള ഒരു സ്ത്രീയായിരുന്നു അവർ. നബി(സ) അവരോട് പറഞ്ഞു. "ആർത്തവ രക്തം അറിയപ്പെടുന്ന രീതിയിലുള്ള കറുപ്പ് കലർന്ന വിധത്തിലായിരിക്കും. അതുവന്നാൽ നിസ്കാരം ഉപേക്ഷിക്കുക. മറ്റേ രക്തം (ഇസ്തിഹാളത്ത്) വന്നാൽ വുദൂ ചെയ്ത് നിസ്കരിക്കുക. കാരണം അതൊരു ദ്രാവകം മാത്രമാണ്." (ദ,ന)', 'فَاطِمَةَ بِنْتِ أَبِي حُبَيْشٍ', 'ഫാത്വിമ ബിൻതുഹുബൈശ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 228, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ كَانَتْ تُسْتَحَاضُ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ دَمَ الْحَيْضِ دَمٌ أَسْوَدُ يُعْرَفُ، فَإِذَا كَانَ ذَلِكَ فَأَمْسِكِي عَنِ الصَّلَاةِ. فَإِذَا كَانَ الْآخَرُ فَتَوَضَّئِي وَصَلِّي". (د,ن)', 'ആഇശ(റ): ഫാത്വിമ ബിൻതു ഹുബൈശിന് രക്തസ്രാവമുണ്ടായിരുന്നു. നബി(സ) അവരോട് പറഞ്ഞു: "ആർത്തവരക്തം കറുപ്പ് കലർന്ന അറിയപ്പെടുന്ന ഒരു രക്തമാണ്, അത് ആരംഭിച്ചാൽ നിസ്കാരം ഉപേക്ഷിക്കുക. മറ്റേ രക്തം (ഇസ്തിഹാളത്ത്) വന്നാൽ വുദൂ ചെയ്ത് നിസ്കരിക്കുക." (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: اسْتُحِيضَتْ فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ, فَسَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنِّي أُسْتَحَاضُ فَلَا أَطْهُرُ، أَفَأَدَعُ الصَّلَاةَ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا ذَلِكَ عِرْقٌ وَلَيْسَتْ بِالْحَيْضَةِ، فَإِذَا أَقْبَلَتِ الْحَيْضَةُ فَدَعِي الصَّلَاةَ، وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ وَتَوَضَّئِي وَصَلِّي، فَإِنَّمَا ذَلِكَ عِرْقٌ وَلَيْسَتْ بِالْحَيْضَةِ". (ن)', 'ആഇശ(റ): ഹുബൈശിന്റെ മകൾ ഫാത്വിമക്ക് രക്തസ്രാവമുണ്ടായി. നബി(സ)യോട് അതിനെക്കുറിച്ച് ചോദിച്ചു: നബിയെ, ഞാൻ രക്തസ്രാവമുള്ള ഒരു സ്ത്രീയാണ്, എനിക്ക് നിസ്കാരം ഒഴിവാക്കാമോ? നബി(സ) പറഞ്ഞു: "അരുത്, അത് ആർത്തവമല്ല. ഒരു സ്രവം മാത്രമാണ്. ആർത്തവം ആരംഭിച്ചാൽ നിസ്കാരം ഉപേക്ഷിക്കുക. ആർത്തവം കഴിഞ്ഞാൽ രക്തം കഴുകി വുദൂ ചെയ്ത് നിസ്കാരം നിർവ്വഹിക്കുക. അത് സ്രവമാണ്, ഹൈള് അല്ല." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ بنت أَبِي حُبَيْشٍ قَالَتْ: يَا رَسُولَ اللهِ, إِنِّي لَا أَطْهُرُ، أَفَأَتْرُكُ الصَّلَاةَ؟ قَالَ: "لَا، إِنَّمَا هُوَ عِرْقٌ وَلَيْسَتْ بِالْحَيْضَةِ، فَإِذَا أَقْبَلَتِ الْحَيْضَةُ فَدَعِي الصَّلَاةَ، وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ ثُمَّ صَلِّي. (ق,د,ت,ن,جه)', 'ആഇശ(റ): ഫാത്വിമ ബിൻതു ഹുബൈശ്(റ) നബി(സ)യോട് ചോദിച്ചു: എനിക്ക് ശുദ്ധിയുണ്ടാവാറില്ല. എനിക്ക് നിസ്കാരം ഒഴിവാക്കിക്കൂടെ? നബി(സ) പറഞ്ഞു: "അതൊരു സ്രവമാണ്. ആർത്തവമല്ല. ആർത്തവ സമയമായാൽ നിസ്കാരം ഉപേക്ഷിക്കുക, അതിന്റെ കണക്ക് (സാധാരണ ആർത്തവം ഉണ്ടാകാറുള്ള നിശ്ചിത ദിവസങ്ങൾ) കഴിഞ്ഞാൽ രക്തം കഴുകി നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً كَانَتْ تُهَرَاقُ الدَّمَ، وَكَانَتْ تَحْتَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ تَغْتَسِلَ عِنْدَ كُلِّ صَلَاةٍ وَتُصَلِّيَ. (د)', 'അബൂസലമയുടെ മകൾ സൈനബ(റ): അബ്ദുർറഹ്മാനുബ്നു ഔഫിനു കീഴിലായിരുന്ന രക്തസ്രാവമുള്ള ഒരു സ്ത്രീയോട് നബി(സ) ഓരോ നിസ്കാര സമയത്തും കുളിക്കാനും പിന്നെ നിസ്കരിക്കാനും കൽപിച്ചു. (ദ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ', 'അബൂസലമയുടെ മകൾ സൈനബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 229, 229, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي الْمَرْأَةِ تَرَى مَا يُرِيبُهَا بَعْدَ الطُّهْرِ: "إِنَّمَا هِيَ- أَوْ قَالَ: إِنَّمَا هُوَ – عِرْقٌ. أَوْ قَالَ: عُرُوقٌ. وَفِي رِوَايَةٍ: "إِنْ قَوِيتِ فَاغْتَسِلِي لِكُلِّ صَلَاةٍ، وَإِلَّا فَاجْمَعِي". (د,جه)', 'ആഇശ(റ): ശുദ്ധിക്കുശേഷം സംശയകരമായി രക്തം കാണുന്ന ഒരു സ്ത്രീയെപ്പറ്റി നബി(സ) പറഞ്ഞു: "അതൊരു സ്രവമാണ്." ഒരു റിപ്പോർട്ടിൽ: "അത് ശക്തമായാൽ ഓരോ നിസ്കാരത്തിനും കുളിക്കുക. അല്ലെങ്കിൽ ജംഅ് ആക്കുക." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 229, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=129), 1, 'وَفِي رِوَايَةٍ: "إِنْ قَوِيتِ فَاغْتَسِلِي لِكُلِّ صَلَاةٍ، وَإِلَّا فَاجْمَعِي". (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّ فَاطِمَةَ بِنْتَ أَبِي حُبَيْشٍ اسْتُحِيضَتْ مُنْذُ كَذَا وَكَذَا، فَلَمْ تُصَلِّ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سُبْحَانَ اللهِ، إِنَّ هَذَا مِنَ الشَّيْطَانِ، لِتَجْلِسْ فِي مِرْكَنٍ، فَإِذَا رَأَتْ صُفْرَةً فَوْقَ الْمَاءِ فَلْتَغْتَسِلْ لِلظُّهْرِ وَالْعَصْرِ غُسْلًا وَاحِدًا، وَتَغْتَسِلْ لِلْمَغْرِبِ وَالْعِشَاءِ غُسْلًا وَاحِدًا، وَتَغْتَسِلْ لِلْفَجْرِ غُسْلًا وَاحِدًا، وَتَتَوَضَّأْ فِيمَا بَيْنَ ذَلِكَ". (د)', 'ഉമൈസിന്റെ മകൾ അസ്മ(റ): ഞാൻ പറഞ്ഞു: അബൂഹുബൈശിന്റെ മകൾ ഫാത്വിമക്ക് ഇന്നദിവസം മുതൽ രക്തം സ്രവിക്കുകയാണ്, അവൾ നിസ്കരിക്കണോ? നബി(സ) പറഞ്ഞു: "അല്ലാഹു എത്ര പരിശുദ്ധൻ! അത് പിശാചിൽ നിന്നുള്ളതാണ്. നിങ്ങൾ മിർകനിൽ ഇരിക്കുക. വെള്ളത്തിന്റെ മുകളിൽ മഞ്ഞ കണ്ടാൽ ളുഹ്റിനും അസ്വറിനും ഒരു കുളിയും, മഗ്രിബിനും ഇശാഇനും ഒരു കുളിയും, സുബ്ഹിക്ക് ഒരു പ്രാവശ്യം കുളിക്കണം. ഇടക്ക് വുദൂ ചെയ്യണം." (ദ)', 'أَسْمَاءَ بِنْتِ عُمَيْسٍ', 'ഉമൈസിന്റെ മകൾ അസ്മ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا فِي الْمُسْتَحَاضَةِ: تَغْتَسِلُ- تَعْنِي مَرَّةً وَاحِدَةً- ثُمَّ تَوَضَّأُ إِلَى أَيَّامِ أَقْرَائِهَا. (د)', 'ആഇശ(റ): രക്തസ്രാവത്തെക്കുറിച്ച് പറഞ്ഞു: ഒരു പ്രാവശ്യം കുളിക്കണം, പിന്നെ ശുദ്ധിയുടെ ദിവസം തീരുന്നതുവരെ വുദൂ ചെയ്യണം. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ وَقَدْ سُئِلَ: كَيْفَ تَغْتَسِلُ الْمُسْتَحَاضَةُ؟ فَقَالَ: تَغْتَسِلُ مِنْ ظُهْرٍ إِلَى ظُهْرٍ، وَتَتَوَضَّأُ لِكُلِّ صَلَاةٍ، فَإِنْ غَلَبَهَا الدَّمُ اسْتَثْفَرَتْ بِثَوْبٍ. (د)', 'സഈദുബ്നുൽ മുസ്വയ്യബ്(റ): രക്തസ്രാവമുള്ളവർ കുളിക്കേണ്ടതെങ്ങനെയാണെന്ന് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഒരു ളുഹ്ർ മുതൽ മറ്റേ ളുഹ്ർ വരേയുള്ളതിന് ഒരു കുളി കുളിക്കണം. എല്ലാ നിസ്കാരത്തിനും വുദൂ ചെയ്യണം. രക്തം കൂടുതൽ ഒലിക്കുകയാണെങ്കിൽ തുണി വെച്ചുകെട്ടണം. (ദ)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസ്വയ്യബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْه قَالَ: الْمُسْتَحَاضَةُ إِذَا انْقَضَى حَيْضُهَا اغْتَسَلَتْ كُلَّ يَوْمٍ، وَاتَّخَذَتْ صُوفَةً فِيهَا سَمْنٌ أَوْ زَيْتٌ. (د)', 'അലി(റ): രക്തസ്രാവമുള്ളവർ ആർത്തവം കഴിഞ്ഞാൽ എല്ലാ ദിവസവും കുളിക്കണം. എണ്ണയോ നെയ്യോ പുരട്ടിയ രോമവസ്ത്രമെടുത്ത് ഗുഹ്യസ്ഥാനത്ത് വെക്കണം. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ رَضِيَ اللهُ عَنْه، وَقَدْ سُئِلَ: عَنِ الْمُسْتَحَاضَةِ، فَقَالَ: تَدَعُ الصَّلَاةَ أَيَّامَ أَقْرَائِهَا، ثُمَّ تَغْتَسِلُ فَتُصَلِّي، ثُمَّ تَغْتَسِلُ فِي الْأَيَّامِ. (د)', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ): ആർത്തവകാരിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അശുദ്ധി കാലയളവിൽ അവൾ നിസ്കാരമൊഴിവാക്കട്ടെ. പിന്നെ കുളിച്ച് നിസ്കരിക്കണം. പിന്നെ എല്ലാ ദിവസവും (രക്തം സ്രവിക്കുമ്പോൾ) കുളിക്കണം. (ദ)', 'الْقَاسِمِ بْنِ مُحَمَّدٍ', 'ഖാസിമുബ്നു മുഹമ്മദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ رَبِيعَةَ رَضِيَ اللهُ عَنْه: أَنَّهُ كَانَ لَا يَرَى عَلَى الْمُسْتَحَاضَةِ وُضُوءًا عِنْدَ كُلِّ صَلَاةٍ، إِلَّا أَنْ يُصِيبَهَا حَدَثٌ غَيْرُ الدَّمِ فَتَوَضَّأُ. (د)', 'റബീഅ(റ): രക്തസ്രാവമുള്ളവർ എല്ലാ നിസ്കാരത്തിനും വുദൂ ചെയ്യണമെന്ന അഭിപ്രായം അദ്ദേഹത്തിനില്ലായിരുന്നു. രക്തമൊലിക്കലല്ലാത്ത വല്ല അശുദ്ധിയും ഉണ്ടായാലൊഴികെ. ഉണ്ടായാൽ വുദൂ ചെയ്യണം. (ദ)', 'رَبِيعَةَ', 'റബീഅ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 230, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أُمَيَّةَ بِنْتِ أَبِي الصَّلْتِ رَضِيَ اللهُ عَنْهَا، عَنِ امْرَأَةٍ مِنْ بَنِي غِفَارٍ قَالَتْ: أَرْدَفَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى حَقِيبَةِ رَحْلِهِ, قَالَتْ: فَوَاللهِ لَمْ يَزَلْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الصُّبْحِ، فَأَنَاخَ، وَنَزَلْتُ عَنْ حَقِيبَةِ رَحْلِهِ، فَإِذَا بِهَا دَمٌ مِنِّي، فَكَانَتْ أَوَّلَ حَيْضَةٍ حِضْتُهَا، قَالَتْ: فَتَقَبَّضْتُ إِلَى النَّاقَةِ وَاسْتَحْيَيْتُ، فَلَمَّا رَأَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَا بِي وَرَأَى الدَّمَ قَالَ: "مَا لَكِ لَعَلَّكِ نَفِسْتِ". قُلْتُ: نَعَمْ، قَالَ: "فَأَصْلِحِي مِنْ نفسك، ثُمَّ خُذِي إِنَاءً مِنْ مَاءٍ فَاطْرَحِي فِيهِ مِلْحًا، ثُمَّ اغْسِلِي مَا أَصَابَ الْحَقِيبَةَ مِنَ الدَّمِ، ثُمَّ عُودِي لِمَرْكَبِك". قَالَتْ: فَلَمَّا فَتَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ رَضَخَ لَنَا مِنَ الْفَيْءِ. قَالَتْ: وَكَانَتْ لَا تَطْهُرُ مِنْ حَيْضَةٍ إِلَّا جَعَلَتْ فِي طُهُورِهَا مِلْحًا، وَأَوْصَتْ بِهِ أَنْ يُجْعَلَ فِي غُسْلِهَا حِينَ مَاتَتْ. (د)', 'ഉമയ്യതു ബിൻത് അബിസ്സ്വൽത്(റ): ബനൂഗിഫ്ഫാറിൽപ്പെട്ട ഒരു സ്ത്രീ പറഞ്ഞു: നബി(സ)യുടെ പിന്നിൽ ഒട്ടകത്തിന്റെ പിൻഭാഗത്ത് ഞാൻ സഞ്ചരിച്ചു. പ്രഭാതം വരെ നബി(സ) അതിന്റെ മുകളിലായിരുന്നു. പിന്നെ അത് മുട്ടുകുത്തി. ഞാൻ പിൻഭാഗത്തു നിന്നിറങ്ങുകയും ചെയ്തു. അപ്പോൾ അതിലെന്റെ രക്തമുണ്ടായിരുന്നു. എന്റെ ആദ്യ ആർത്തവമായിരുന്നു അത്. ഞാൻ ലജ്ജിച്ച് ഒട്ടകത്തിന്റടുത്തേക്കു ചാടി. എന്റെ ലജ്ജയും രക്തവും കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്തേ നിനക്കാർത്തവമുണ്ടായോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "നീ നിന്റെ ശരീരത്തിലുള്ളത് വൃത്തിയാക്കുക, പിന്നെ ഒരു പാത്രം വെള്ളമെടുത്ത് അതിൽ ഉപ്പിട്ട് ഒട്ടകപ്പുറത്തായ രക്തം കഴുകുക. പിന്നെ വാഹനത്തിലേക്കു മടങ്ങുക." അവർ പറയുന്നു: നബി(സ) ഖൈബർ യുദ്ധത്തിൽ ജയിച്ചപ്പോൾ ഞങ്ങൾക്ക് ഗനീമത്ത് സ്വത്ത് കിട്ടി. പിന്നെ അവർ ആർത്തവം വൃത്തിയാക്കുകയാണെങ്കിൽ വെള്ളത്തിൽ ഉപ്പ് കലർത്താറുണ്ടായിരുന്നു. മരിക്കുമ്പോൾ കുളിക്കാനുള്ള വെള്ളത്തിൽ ഉപ്പ് കലർത്താൻ അവർ കൽപിക്കുകയും ചെയ്തു. (ദ)', 'أُمَيَّةَ بِنْتِ أَبِي الصَّلْتِ', 'ഉമയ്യതു ബിൻത് അബിസ്സ്വൽത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 230, 231, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا، وَكَانَتْ بَايَعَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: كُنَّا لَا نَعُدُّ الصُّفْرَةَ وَالْكُدْرَةَ بَعْدَ الطُّهْرِ شَيْئًا. (خ,د,ن,جه)', 'ഉമ്മുഅത്വിയ്യ(റ): -അവർ റസുലിനോട് ബൈഅത്ത് (അനുരഞ്ജന പ്രതിജ്ഞ) ചെയ്തയാളായിരുന്നു- അവർ പറഞ്ഞു: (സ്ത്രീകളിൽ നിന്ന് സ്രവിക്കുന്ന) മഞ്ഞയും കലർപ്പുമൊന്നും ഞങ്ങൾ വിഷയമാക്കാറില്ലായിരുന്നു. (ബു,ദ,ന,ജ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 231, 231, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْه قَالَ: كَانَتِ الْيَهُودُ إِذَا حَاضَتِ الْمَرْأَةُ مِنْهُمْ لَمْ يُؤَاكِلُوهُنَّ وَلَا يُشَارِبُوهُنَّ وَلَا يُجَامِعُوهُنَّ فِي الْبُيُوتِ، فَسَأَلُوا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى} الْآيَةَ، فَأَمَرَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُؤَاكِلُوهُنَّ وَيُشَارِبُوهُنَّ وَيُجَامِعُوهُنَّ فِي الْبُيُوتِ، وَأَنْ يَصْنَعُوا بِهِنَّ كُلَّ شَيْءٍ مَا خَلَا الْجِمَاعَ، فَقَالَتِ الْيَهُودُ: مَا يَدَعُ رَسُولُ اللهِ شَيْئًا مِنْ أَمْرِنَا إِلَّا خَالَفَنَا. فَقَامَ أُسَيْدُ بْنُ حُضَيْرٍ، وَعَبَّادُ بْنُ بشر فَأَخْبَرَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَا: أَنُجَامِعُهُنَّ فِي الْمَحِيضِ؟ فَتَمَعَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَمَعُّرًا شَدِيدًا، حَتَّى ظَنَنَّا أَنَّهُ قَدْ غَضِبَ، فَقَامَا، فَاسْتَقْبَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَدِيَّةً لَبَنٍ، فَبَعَثَ فِي آثَارِهِمَا فَرَدَّهُمَا، فَسَقَاهُمَا، فَعُرِفَ أَنَّهُ لَمْ يَغْضَبْ عَلَيْهِمَا. (م,د,ن,جه)', 'അനസ്(റ): ജൂതന്മാർ അവരുടെ സ്ത്രീകൾക്ക് ആർത്തവമുണ്ടായാൽ അവരോടൊപ്പം തിന്നുകയോ കുടിക്കുകയോ വീട്ടിൽ ഒന്നിച്ച് നിൽക്കുകയോ ചെയ്യാറില്ലായിരുന്നു. ഈ വിഷയം നബി(സ)യോട് അനുയായികൾ ചോദിച്ചു. അപ്പോൾ ഈ സൂക്തം അവതരിച്ചു: "ആർത്തവത്തെക്കുറിച്ച് അവർ താങ്കളോട് ചോദിക്കുന്നു, താങ്കൾ പറയുക; അത് (ആർത്തവം) മ്ലേച്ചമാണ്...." അങ്ങനെ നബി(സ) അവരോടൊപ്പം (ആർത്തവകാരികളോടൊപ്പം) തിന്നാനും കുടിക്കാനും വീട്ടിൽ ഒന്നിച്ച് കഴിയാനും സംഭോഗമല്ലാത്ത മറ്റെല്ലാം ആവാമെന്നും കൽപിച്ചു. അപ്പോൾ ജൂതന്മാർ പറഞ്ഞു: നമ്മുടെ ഒരൊറ്റ കാര്യവും പ്രവാചകൻ നമുക്കെതിരായിട്ടല്ലാതെയില്ല. ഉബൈദുബ്നുഹുളൈറും അബ്ബാദുബ്നു ബിശ്റും എഴുന്നേറ്റുനിന്നു പറഞ്ഞു: ഞങ്ങൾ ആർത്തവ വേളയിൽ സംഭോഗം ചെയ്യട്ടെയോ? അപ്പോൾ നബി(സ)യുടെ മുഖം കഠിനമായി ചുവന്നു. നബി(സ)ക്ക് ദേഷ്യം വന്നുവെന്നു ഞങ്ങൾ കരുതി. അവരിരുവരും എഴുന്നേറ്റു നിന്നു. നബി(സ) പാലുമായി വന്ന് അവരുടെ പിന്നിൽ ആളെയയച്ചു വരുത്തി അവരെ പാൽ കുടിപ്പിച്ചു. ഈ സമയം നബി(സ) അവരോട് ദേഷ്യപ്പെട്ടിട്ടില്ല എന്നവർക്ക് മനസ്സിലായി. (മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 231, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الرَّجُلِ يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ: "يَتَصَدَّقُ بِدِينَارٍ، أَوْ بِنِصْفِ دِينَارٍ". (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ആർത്തവ വേളയിൽ ഭാര്യയുമായി ബന്ധപ്പെടുന്നവനെപ്പറ്റി നബി(സ) പറഞ്ഞു: "ഒരു സ്വർണ്ണ നാണയം (അല്ലെങ്കിൽ അര സ്വർണ്ണ നാണയം) ധർമ്മം ചെയ്തുകൊള്ളട്ടെ." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُ إِحْدَانَا إِذَا كَانَتْ حَائِضًا أَنْ تَشُدَّ إِزَارَهَا، ثُمَّ يُبَاشِرُهَا. (ق,ت,ن)', 'ആഇശ(റ): ഞങ്ങളിലാരെങ്കിലും ആർത്തവമുണ്ടായാൽ നബി(സ) ഞങ്ങളോട് അരയുടുപ്പണിയാൻ കൽപിക്കാറുണ്ടായിരുന്നു. പിന്നെ അവരോടൊത്ത് സഹവസിക്കുകയും ചെയ്യും. (ബു,മു,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ كِلَانَا جُنُبٌ، وَكَانَ يَأْمُرُنِي فَأَتَّزِرُ فَيُبَاشِرُنِي وَأَنَا حَائِضٌ، وَكَانَ يُخْرِجُ رَأْسَهُ إِلَيَّ وَهُوَ مُعْتَكِفٌ، فَأَغْسِلُهُ وَأَنَا حَائِضٌ. (خ)', 'ആഇശ(റ): ഞാനും നബി(സ)യും ജനാബത്തുകാരായിരിക്കെ ഒരേ പാത്രത്തിൽ നിന്ന് കുളിക്കാറുണ്ടായിരുന്നു. ഞാൻ ആർത്തവകാരിയായിരിക്കെ എന്നോട് അരയുടുപ്പണിയാൻ കൽപിക്കുകയും പിന്നെ എന്നോടൊപ്പം സഹവസിക്കുകയും ചെയ്യമായിരുന്നു. ഞാൻ ആർത്തവകാരിയായിരിക്കെ നബി(സ) ഇഅ്തികാഫിരിക്കുമ്പോൾ തല എന്നിലേക്ക് വെച്ചുതരികയും ഞാൻ കഴുകിക്കൊടുക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتْ إِحْدَانَا إِذَا كَانَتْ حَائِضًا فَأَرَادَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُبَاشِرَهَا أَمَرَهَا أَنْ تَتَّزِرَ فِي فَوْرِ حَيْضَتِهَا، ثُمَّ يُبَاشِرُهَا. قَالَتْ: وَأَيُّكُمْ يَمْلِكُ إِرْبَهُ كَمَا كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْلِكُ إِرْبَهُ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): ഞങ്ങളിലാർക്കെങ്കിലും ആർത്തവമുണ്ടാവുകയും നബി(സ) അവളോട് സഹവസിക്കാൻ ആഗ്രഹിക്കുകയും ചെയ്താൽ അവളുടെ ശക്തിയായ ആർത്തവത്തിന്റെ ഘട്ടത്തിൽ തന്നെ അവളോട് ഹൈളിന്റെ വസ്ത്രമണിയാൻ കൽപിക്കുകയും പിന്നെ അവളോടൊപ്പം സഹവസിക്കുകുയം ചെയ്യാറുണ്ടായിരുന്നു. ആഇശ(റ) പറഞ്ഞു: നബി(സ)ക്ക് കഴിഞ്ഞിരുന്നതുപോലെ കാമവികാരങ്ങൾ നിയന്ത്രിച്ച് നിർത്താൻ നിങ്ങളിലാർക്കാണ് കഴിയുക? (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 232, 232, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أَضْحَى أَوْ فِطْرٍ إِلَى الْمُصَلَّى، فَمَرَّ عَلَى النِّسَاءِ فَقَالَ: "يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي أُرِيتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ". فَقُلْنَ: وَبِمَ يَا رَسُولَ اللهِ؟ قَالَ: "تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ، مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ الْحَازِمِ مِنْ إِحْدَاكُنَّ". قُلْنَ: وَمَا نُقْصَانُ دِينِنَا وَعَقْلِنَا يَا رَسُولَ اللهِ؟ قَالَ: "أَلَيْسَ شَهَادَةُ الْمَرْأَةِ مِثْلَ نِصْفِ شَهَادَةِ الرَّجُلِ؟" قُلْنَ: بَلَى، قَالَ: "فَذَلِكِ مِنْ نُقْصَانِ عَقْلِهَا، أَلَيْسَ إِذَا حَاضَتْ لَمْ تُصَلِّ، وَلَمْ تَصُمْ؟" قُلْنَ: بَلَى، قَالَ: "فَذَلِكِ مِنْ نُقْصَانِ دِينِهَا". (خ)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒരു ചെറിയ പെരുന്നാളിനോ ബലിപെരുന്നാളിനോ നബി(സ) നിസ്കരിക്കാൻ പുറപ്പെട്ടു. അപ്പോൾ ഒരുകൂട്ടം സ്ത്രീകളുടെയരികിലൂടെ നടന്നുപോയി. നബി(സ) പറഞ്ഞു: "സ്ത്രീകളെ, നിങ്ങൾ ദാനം ചെയ്യുക. കാരണം, നരകാവകാശികളിൽ ഏറ്റവും കൂടുതൽ എനിക്ക് കാണിക്കപ്പെട്ടത് നിങ്ങളെയാണ്." അവർ പറഞ്ഞു: നബിയേ അതെന്തു കൊണ്ടാണ്? നബി (സ) പറഞ്ഞു: നിങ്ങൾ വല്ലാതെ ശപിക്കുന്നു, ഭർത്താക്കന്മാരോട് നന്ദികേട് കാണിക്കുന്നു. ബുദ്ധിയുള്ള മനുഷ്യന്റെ ബുദ്ധിയെ പോക്കിക്കളയുവാന്മാത്രം ദീനും ബുദ്ധിയും ഇത്ര കുറഞ്ഞവരായി നിങ്ങളേക്കാൾ ആരെയും ഞാൻ കണ്ടിട്ടില്ല." അവർ പറഞ്ഞു: നബിയേ, എന്താണ് ഞങ്ങളുടെ ബുദ്ധിയുടെയും മതത്തിന്റെയും ന്യൂനത? നബി(സ) പറഞ്ഞു: "സ്ത്രീയുടെ സാക്ഷ്യം പുരുഷന്റെ സാക്ഷ്യത്തിന്റെ പകുതിയല്ലെയോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അത് അവരുടെ ബുദ്ധിയുടെ ന്യൂനതയിൽപെട്ടതാണ്. ആർത്തവമുണ്ടാവുമ്പോൾ അവർ നിസ്കരിക്കും, നോമ്പെടുക്കാറുമില്ലല്ലോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അത് അവരുടെ മതത്തിന്റെ ന്യൂനതയിൽപെട്ടതാണ്." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 233, 233, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ جُمَيْعِ بْنِ عُمَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا مَعَ أُمِّي وَخَالَتِي، فَسَأَلَتَاهَا: كَيْفَ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ إِذَا حَاضَتْ إِحْدَاكُنَّ؟ قَالَتْ: كَانَ يَأْمُرُنَا إِذَا حَاضَتْ إِحْدَانَا أَنْ تَتَّزِرَ بِإِزَارٍ وَاسِعٍ، ثُمَّ يَلْتَزِمُ صَدْرَهَا وَثَدْيَيْهَا. (ن)', 'ജുമൈഉബ്നു ഉമൈർ(റ): ഞാൻ എന്റെ ഉമ്മയോടും മാതൃസഹോദരിയോടുമൊപ്പം ആഇശ(റ)യുടെ അടുത്തു ചെന്നു. അവർ രണ്ടു പേരും ആഇശ(റ)യോട് ചോദിച്ചു: നിങ്ങളിലാർക്കെങ്കിലും ആർത്തവമുണ്ടായാൽ നബി(സ) എന്താണ് ചെയ്തിരുന്നത്? അവർ പറഞ്ഞു: ഞങ്ങളിലാർക്കെങ്കിലും ആർത്തവമുണ്ടായാൽ ഞങ്ങളോട് വലിയ അരയുടുപ്പണിയാൻ കൽപിച്ചിരുന്നു. പിന്നെ സ്തനങ്ങളിലും നെഞ്ചിലും നബി(സ) സ്പർശിക്കാറുണ്ടായിരുന്നു. (ന)', 'جُمَيْعِ بْنِ عُمَيْرٍ', 'ജുമൈഉബ്നു ഉമൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 233, 233, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُبَاشِرُ الْمَرْأَةَ مِنْ نسائه وَهِيَ حَائِضٌ، إِذَا كَانَ عَلَيْهَا إِزَارٌ يَبْلُغُ أَنْصَافَ الْفَخِذَيْنِ وَالرُّكْبَتَيْنِ، وَفِي رِوَايَةٍ: تَحْتَجِزُ بِهِ. (ق,د,ن)', 'മൈമൂന(റ): നബി(സ)യുടെ ഭാര്യമാരിലാർക്കെങ്കിലും ആർത്തവമുണ്ടായാൽ അവരിൽ മുട്ടിന്റെയും തുടകളുടെയും പകുതി വരെ എത്തുന്ന ഉടുപ്പണിഞ്ഞവരോട് നബി(സ) സഹവസിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 233, 233, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=145), 1, 'وَفِي رِوَايَةٍ: تَحْتَجِزُ بِهِ. (ق,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، رَضِيَ اللهُ عَنْهَا عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا - زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - قَالَ: سَأَلْتُهَا: كَيْفَ كُنْتِ تَصْنَعِينَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَيْضَةِ؟ قَالَتْ: كَانَتْ إِحْدَانَا، فِي فَوْرِهَا أَوَّلَ مَا تَحِيضُ، تَشُدُّ عَلَيْهَا إِزَارًا إِلَى أَنْصَافِ فَخِذَيْهَا، ثُمَّ تَضْطَجِعُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ): നബി(സ)യുടെ ഭാര്യ ഉമ്മുഹബീബ(റ)യോട് ഞാൻ ചോദിച്ചു: നിങ്ങളിലാർക്കെങ്കിലും ആർത്തവമുണ്ടായാൽ നബി(സ)യോടൊപ്പം എങ്ങിനെയാണ് ചെയ്തിരുന്നത്? അവർ പറഞ്ഞു: ആർത്തവമുണ്ടായാൽ ഞങ്ങൾ തുടകളുടെ പകുതിവരെ എത്തുന്ന ഉടുപ്പണിഞ്ഞിരുന്നു. നബി(സ)യോടെപ്പം കിടക്കാറുമുണ്ടായിരുന്നു. (ജ)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ،', 'മുആവിയതുബ്നു അബീസുഫ്യാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 233, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَأَلَتْهَا امْرَأَةٌ، قَالَتْ: إِحْدَانَا تَحِيضُ، وَلَيْسَ لَهَا وَلِزَوْجِهَا إِلَّا فِرَاشٌ وَاحِدٌ؟ قَالَتْ: أُخْبِرُكِ بِمَا صَنَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: دَخَلَ فَمَضَى إِلَى مَسْجِدِهِ- تَعْنِي مَسْجِدَ بَيْتِهِ- فَلَمْ يَنْصَرِفْ حَتَّى غَلَبَتْنِي عَيْنِي وَأَوْجَعَهُ الْبَرْدُ، فَقَالَ: "ادْنِي مِنِّي". فَقُلْتُ: إِنِّي حَائِضٌ، فَقَالَ: "وَإِنْ، اكْشِفِي عَنْ فَخِذَيْكِ". فَكَشَفْتُ فَخِذَيَّ، فَوَضَعَ خَدَّهُ وَصَدْرَهُ عَلَى فَخِذَيَّ، وَحَنَيْتُ عَلَيْهِ حَتَّى دَفِئَ وَنَامَ. (د)', 'ആഇശ(റ): ഒരു സ്ത്രീ ചോദിച്ചു: ആർത്തവമുണ്ടാവുമ്പോൾ ഭാര്യക്കും ഭർത്താവിനും ആകെ ഒരു വിരിപ്പ് മാത്രമുണ്ടായാൽ എന്താണ് ചെയ്യേണ്ടത്? അവർ പറഞ്ഞു: നബി(സ) ചെയ്തത് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞുതരാം. നബി(സ) വന്ന് പള്ളിയിൽ (നബി(സ)യുടെ വീട്ടിലെ പള്ളിയിൽ) പോയി. എനിക്ക് ഉറക്കം വരുന്നതുവരെ നബി പോയില്ല. തണുപ്പ് നബിയെ വേദനിപ്പിച്ചു. നബി(സ) പറഞ്ഞു: എന്നോടടുക്കുക. ഞാൻ പറഞ്ഞു: എനിക്കാർത്തവമുണ്ട്. നബി(സ) പറഞ്ഞു: "നിന്റെ തുടയിൽ നിന്നു വസ്ത്രം മാറ്റുക." ഞാനപ്രകാരം ചെയ്തു. നബി(സ)യുടെ നെഞ്ചും കവിളും എന്റെ തുടയുടെമേൽ വെച്ചു. ഞാൻ നബി(സ)യോട് അനുകമ്പ കാണിച്ചു. നബി(സ)ക്ക് ചൂട് അനുഭവപ്പെടുകയും ഉറങ്ങുകയും ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: كُنْتُ إِذَا حِضْتُ نَزَلْتُ عَنِ الْمِثَالِ عَلَى الْحَصِيرِ، فَلَمْ نَقْرَبْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ نَدْنُ مِنْهُ حَتَّى نَطْهُرَ. (د)', 'ആഇശ(റ): എനിക്കാർത്തവമുണ്ടായാൽ ഞാൻ വിരിപ്പിൽ നിന്നിറങ്ങി പായയിൽ ഉറങ്ങും. ശുദ്ധമാവുന്നതുവരെ ഞങ്ങൾ നബി(സ)യിലേക്ക് അടുക്കാറില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عِكْرِمَةَ رَضِيَ اللهُ عَنْه: عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ مِنَ الْحَائِضِ شَيْئًا أَلْقَى عَلَى فَرْجِهَا ثَوْبًا. (د)', 'ഇക്രിമ(റ): നബി(സ)യുടെ ഭാര്യമാരിൽ ചിലർ പറഞ്ഞു: നബി(സ) ആർത്തവകാരികളിൽ നിന്നെന്തെങ്കിലും ഉദ്ദേശിച്ചാൽ അവരുടെ ഗുഹ്യസ്ഥാനത്ത് വസ്ത്രം ഇടാറുണ്ടായിരുന്നു. (ദ)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 234, 234, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ شُرَيْحٍ رَضِيَ اللهُ عَنْه: أَنَّهُ سَأَلَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: هَلْ تَأْكُلُ الْمَرْأَةُ مَعَ زَوْجِهَا وَهِيَ طَامِثٌ؟ قَالَتْ: نَعَمْ، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُونِي، فَآكُلُ مَعَهُ، وَأَنَا عَارِكٌ، كَانَ يَأْخُذُ الْعَرْقَ، فَيُقْسِمُ عَلَيَّ فِيهِ، فَأَعْتَرِقُ مِنْهُ، ثُمَّ أَضَعُهُ فَيَأْخُذُهُ، فَيَعْتَرِقُ مِنْهُ وَيَضَعُ فَمَهُ حَيْثُ وَضَعْتُ فَمِي مِنَ الْعَرْقِ، وَيَدْعُو بِالشَّرَابِ فَيُقْسِمُ عَلَيَّ فِيهِ مِنْ قَبْلِ أَنْ يَشْرَبَ مِنْهُ، فَآخُذُهُ فَأَشْرَبُ مِنْهُ، ثُمَّ أَضَعُهُ، فَيَأْخُذُهُ فَيَشْرَبُ مِنْهُ، وَيَضَعُ فَمَهُ حَيْثُ وَضَعْتُ فَمِي مِنَ الْقَدَحِ. (م,د,ن,جه)', 'ശുറൈഹ്(റ): സ്ത്രീക്ക് അശുദ്ധിയുണ്ടായിരിക്കെ അവളോടൊത്ത് ഭക്ഷിക്കാമോ എന്ന് അദ്ദേഹം ആഇശ(റ)യോട് ചോദിച്ചു. ആഇശ(റ) പറഞ്ഞു: അതെ, നബി(സ) എന്നെ വിളിക്കുകയും ആർത്തവകാരിയായിരിക്കെ ഞാൻ അവിടത്തോടൊപ്പം ഭക്ഷിക്കുകയും ചെയ്തിരുന്നു. നബി(സ) ഇറച്ചിയിലെ എല്ലെടുത്ത് എനിക്ക് വിഹിതംവെച്ചുതരും. ഞാൻ അതിലെ മാംസം കഴിക്കുകയും അവിടെ വെക്കുകയും ചെയ്യും. അപ്പോൾ നബി(സ) അതെടുത്ത് അതിലെ മാംസം ഭക്ഷിക്കും. ഈ സമയം അവിടുത്തെ വായ ഞാൻ വായ വെച്ചേടത്തുതന്നെ വെക്കും. പിന്നെ വെള്ളം കൊണ്ടുവരാൻ പറയും. നബി(സ) കുടിക്കുന്നതിനു മുമ്പ് എനിക്ക് വിഹിതംവെച്ചുതരും. ഞാനെടുത്ത് കുടിച്ചു വെക്കും. അപ്പോൾ നബി(സ) കപ്പിൽ എന്റെ വായ വെച്ചേടത്തുതന്നെ വായ വെച്ച് വെള്ളം കുടിക്കുകയും ചെയ്യും. (മു,ദ,ന,ജ)', 'شُرَيْحٍ', 'ശുറൈഹ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 234, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضَعُ فَاهُ عَلَى الْمَوْضِعِ الَّذِي أَشْرَبُ مِنْهُ، وَيَشْرَبُ مِنْ فَضْلِ شَرَابِي وَأَنَا حَائِضٌ. (ن)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കെ നബി(സ) അവിടത്തെ വായ, ഞാൻ കുടിക്കുമ്പോൾ വായ വെക്കുന്നേടത്ത് വെക്കുകയും എന്റെ ബാക്കി കുടിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'عَائِشَةَ قَالَتْ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عَبْدِ اللهِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْه قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ مُوَاكَلَةِ الْحَائِضِ، فَقَالَ: "وَاكِلْهَا". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു സഅ്ദ്(റ): ആർത്തവകാരിയോടൊപ്പം തിന്നുന്നതിനെപ്പറ്റി ഞാൻ നബി(സ)യോട് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവളുടെ കൂടെ തിന്നോളൂ." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ سَعْدٍ', 'അബ്ദുല്ലാഹിബ്നു സഅ്ദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَشْرَبُ مِنَ الْقَدَحِ وَأَنَا حَائِضٌ، فَأُنَاوِلُهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ، فَيَشْرَبُ مِنْهُ وَأَتَعَرَّقُ مِنَ الْعَرْقِ وَأَنَا حَائِضٌ، فَأُنَاوِلُهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَضَعُ فَاهُ عَلَى مَوْضِعِ فِيَّ. (م,ن)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കുമ്പോൾ ഞാൻ കപ്പിൽ നിന്ന് വെള്ളം കുടിച്ച് നബി(സ)ക്ക് നൽകുകയും, എന്റെ വായ വെച്ചിടത്ത് നബി(സ) വായ വെക്കുകയും കുടിക്കുകയും ചെയ്യും. ആർത്തവ സമയത്ത് ഞാൻ എല്ലിൽ നിന്ന് മാംസം തിന്നുകയും നബി(സ)ക്ക് കൊടുക്കുകയും ചെയ്യും. ഞാൻ വായ വെച്ചിടത്ത് തന്നെ നബി(സ) വായ വെച്ച് അത് തിന്നുകയും ചെയ്യാറുണ്ടായിരുന്നു. (മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَأْسُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حِجْرِ إِحْدَانَا وَهِيَ حَائِضٌ، وَهُوَ يَقْرَأُ الْقُرْآنَ. (خ,ن)', 'ആഇശ(റ): ഞങ്ങളിലൊരാൾ ആർത്തവകാരിയായിരിക്കെ നബി(സ) അവളുടെ മടിയിൽ തല വെച്ച് ഖുർആൻ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضَعُ رَأْسَهُ فِي حِجْرِ إِحْدَانَا، فَيَتْلُو الْقُرْآنَ وَهِيَ حَائِضٌ، وَتَقُومُ إِحْدَانَا بِخُمْرَتِهِ إِلَى الْمَسْجِدِ، فَتَبْسُطُهَا وَهِيَ حَائِضٌ. (ن)', 'മൈമൂന(റ): ഞങ്ങളിൽ ഒരാൾ ആർത്തവകാരിയായിരിക്കെ അവളുടെ മടിയിൽ നബി(സ) തല വെക്കുകയും ഖുർആൻ പാരായണം ചെയ്യുകയും ചെയ്തിരുന്നു. ഞങ്ങലിലൊരാൾ ആർത്തവകാരിയായിരിക്കെ അവൾ റസൂലി(സ)ന്റെ പായയുമായി പള്ളിയിലേക്കു പോവുകയും അത് തിരുമേനിക്ക് വിരിച്ചു കൊടുക്കുകയും ചെയ്യും. (ന)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 235, 235, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَّكِئُ فِي حَجْرِي وَأَنَا حَائِضٌ، ثُمَّ يَقْرَأُ الْقُرْآنَ. (خ)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കെ നബി(സ) എന്റെ മടിയിൽ തല വെച്ച് ഖുർആൻ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 235, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ إِذْ قَالَ: "يَا عَائِشَةُ، نَاوِلِينِي الثَّوْبَ". فَقَالَتْ: إِنِّي لَا أُصَلِّي، فَقَالَ: "إِنَّهُ لَيْسَ فِي يَدِكِ". فَنَاوَلَتْهُ. (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പള്ളിയിലായിരിക്കെ "ആഇശാ, എന്റെ വസ്ത്രമെടുക്കൂ!." എന്ന് പറഞ്ഞപ്പോൾ ആഇശ(റ) പറഞ്ഞു: ഞാൻ നിസ്കരിക്കുന്നില്ല (എനിക്ക് ആർത്തവമാണ്). നബി(സ) പറഞ്ഞു: "അത് (ആർത്തവം) നിന്റെ കയ്യിലല്ലല്ലോ?" അപ്പോൾ ആഇശ(റ) നബി(സ)ക്ക് വസ്ത്രം എടുത്തുകൊടുത്തു.(മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَاوِلِينِي الْخُمْرَةَ مِنَ الْمَسْجِدِ". فَقُلْتُ: إِنِّي حَائِضٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيْسَتْ حَيْضَتُكِ فِي يَدِكِ". (م,د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "പള്ളിയിൽ നിന്ന് നിസ്കാരപ്പായ എടുത്തുതരിക." ഞാൻ പറഞ്ഞു: ഞാൻ ആർത്തവകാരിയാണ്. നബി(സ) പറഞ്ഞു: നിന്റെ ആർത്തവം നിന്റെ കയ്യിലല്ലല്ലോ!." (മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُدْنِي إِلَيَّ رَأْسَهُ وَهُوَ مُعْتَكِفٌ، فَأَغْسِلُهُ وَأَنَا حَائِضٌ. (ن)', 'ആഇശ(റ): നബി(സ) പള്ളിയിൽ ഇഅ്തികാഫിലായിരിക്കെ അവിടുത്തെ തല എന്നിലേക്ക് അടുപ്പിച്ചു തരികയും ഞാൻ കഴുകുകയും ചെയ്യാറുണ്ടായിരുന്നു. ആ സമയം ഞാൻ ആർത്തവകാരിയായിരിക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَنَّهَا كَانَتْ تُرَجِّلُ رَأْسَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ حَائِضٌ، وَهُوَ مُعْتَكِفٌ، فَيُنَاوِلُهَا رَأْسَهُ وَهِيَ فِي حُجْرَتِهَا. (ن)', 'ആഇശ(റ): അവർ ആർത്തവകാരിയായിരിക്കെ നബി(സ)യുടെ മുടി ചീകിക്കൊടുക്കാറുണ്ടായിരുന്നു. നബി(സ) അപ്പോൾ പള്ളിയിൽ ഇഅ്തികാഫിലും. അവർ അവരുടെ റൂമിലുമായിരിക്കും. നബി(സ) തന്റെ തല അവരിലേക്ക് നീട്ടിക്കൊടുക്കും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُخْرِجُ رَأْسَهُ مِنَ الْمَسْجِدِ وَهُوَ مُعْتَكِفٌ، فَأَغْسِلُهُ وَأَنَا حَائِضٌ. (ن,جه)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കെ നബി(സ) ഇഅ്തികാഫിലായിരിക്കുമ്പോൾ പള്ളിയിൽ നിന്ന് തല പുറത്തേക്കിടുകയും ഞാനത് കഴുകുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَائِشَةَ قَالَتْ: كُنْتُ أُرَجِّلُ رَأْسَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا حَائِضٌ. (خ,ن)', 'ആഇശ(റ): ഞാൻ ആർത്തവകാരിയായിരിക്കെ നബി(സ)യുടെ മുടി ചീകിക്കൊടുക്കാറുണ്ടായിരുന്നു. (ബു,ന)', 'عَائِشَةَ قَالَتْ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 236, 236, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كُنْتُ لَأَدْخُلُ الْبَيْتَ لِلْحَاجَةِ، وَالْمَرِيضُ فِيهِ، فَمَا أَسْأَلُ عَنْهُ إِلَّا وَأَنَا مَارَّةٌ. وَإِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيُدْخِلُ عَلَيَّ رَأْسَهُ وَهُوَ فِي الْمَسْجِدِ، فَأُرَجِّلُهُ. وَكَانَ لَا يَدْخُلُ الْبَيْتَ إِلَّا لِحَاجَةٍ، إِذَا كَانَ مُعْتَكِفًا. (م)', 'ആഇശ(റ): ഞാൻ (ഇഅ്തികാഫിലായിരിക്കെ) വല്ല ആവശ്യത്തിനും വീട്ടിൽ പ്രവേശിക്കുമ്പോൾ അവിടെ രോഗിയുണ്ടായിരിക്കും. ഞാൻ നടന്നു കൊണ്ടിരിക്കെ യല്ലാതെ (രോഗിയോട്) അയാളുടെ ക്ഷേമത്തെക്കുറിച്ച് ചോദിക്കാറില്ല. നബി(സ) പള്ളിയിലായിരിക്കെ തല നീട്ടിത്തരുകയും ഞാൻ ചീകിക്കൊടുക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. തിരുമേനി(സ) ഇഅ്തികാഫിലായിരിക്കുമ്പോൾ ആവശ്യത്തിനല്ലാതെ വീട്ടിൽ പ്രവേശിക്കാറുണ്ടായിരുന്നില്ല. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ فِي حَدِيثِ أَسْمَاءَ بِنْتِ عُمَيْسٍ حِينَ نُفِسَتْ بِذِي الْحُلَيْفَةِ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَبِي بَكْرٍ: "مُرْهَا أَنْ تَغْتَسِلَ وَتُهِلَّ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ):അസ്മാഅ് ബിൻത് ഉമൈസിന് ദുൽഹുലൈഫയിൽ വെച്ച് പ്രസവ രക്തമുണ്ടായപ്പോൾ നബി(സ) അബൂബക്കറി(റ)നോട് പറഞ്ഞു: "അവരോട് കുളിച്ച് തഹ്ലീൽ ചൊല്ലാൻ പറയുക." (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أُمِّ كَعْبٍ، مَاتَتْ فِي نِفَاسِهَا، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الصَّلَاةِ فِي وَسْطِهَا. (خ,ن)', 'സമുറ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഉമ്മുകഅ്ബിന്റെ മേൽ മയ്യിത്ത് നിസ്കരിച്ചു. പ്രസവരക്തമുള്ള സമയത്താണ് അവൾ മരിച്ചത്. നബി(സ) നിസ്കരിച്ചപ്പോൾ അവരുടെ മദ്ധ്യഭാഗത്തു നിന്നു. (ബു,ന)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَرْحَةَ هَذَا الْمَسْجِدِ، فَنَادَى بِأَعْلَى صَوْتِهِ: "إِنَّ الْمَسْجِدَ لَا يَحِلُّ لِجُنُبٍ وَلَا لِحَائِضٍ". [ز: في إسناده ضعيف] (جه)', 'ഉമ്മുസലമ(റ): നബി(സ) പള്ളിയുടെ മുറ്റത്തുവെച്ച് ഉച്ചത്തിൽ വിളിച്ചു പറഞ്ഞു: "പള്ളി ജനാബത്തുകാരനും ആർത്തവകാരിക്കും അനുവദനീയമല്ല." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 237, 237, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَوُجُوهُ بُيُوتِ أَصْحَابِهِ شَارِعَةٌ فِي الْمَسْجِدِ، فَقَالَ: "وَجِّهُوا هَذِهِ الْبُيُوتَ عَنِ الْمَسْجِدِ". ثُمَّ دَخَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَصْنَعِ الْقَوْمُ شَيْئًا، رَجَاءَ أَنْ تَنْزِلَ فِيهِمْ رُخْصَةٌ، فَخَرَجَ إِلَيْهِمْ بَعْدُ فَقَالَ: "وَجِّهُوا هَذِهِ الْبُيُوتَ عَنِ الْمَسْجِدِ، فَإِنِّي لَا أُحِلُّ الْمَسْجِدَ لِحَائِضٍ وَلَا جُنُبٍ". (د)', 'ആഇശ(റ) പറഞ്ഞു: ഒരിക്കൽ റസൂൽ(സ) കടന്നുവന്നപ്പോൾ തന്റെ അനുചരന്മാരുടെ വീടുകളുടെ വാതിലുകൾ പള്ളികൾക്കഭിമുഖമായി തുറന്നു കിടക്കുന്നതു കണ്ടു. അന്നേരം തിരുമേനി(സ) പറഞ്ഞു: ''നിങ്ങളുടെ വീടുകളുടെ മുഖങ്ങളെ പള്ളിയുടെ ഭാഗത്തു നിന്നും തിരുക്കുക''. തിരുമേനി(സ) അകത്തേക്കു പോയി. എന്നാൽ ആളുകൾ ഒന്നും തന്നെ ചെയ്തില്ല. ഇക്കാര്യത്തിൽ തങ്ങൾക്ക് ഇളവ് ലഭിച്ചേക്കാം എന്നു പ്രതീക്ഷിച്ചു കൊണ്ടാണ് (അവർ പ്രവാചകന്റെ നിർദ്ദേശം പാലിക്കാതിരുന്നത്). പന്നീട് പ്രവാചകൻ(സ) പുറത്തിറങ്ങി അവരിലേക്കു വന്നു. ശേഷം പറഞ്ഞു: നിങ്ങൾ നിങ്ങളുടെ വീടുകളുടെ മുഖങ്ങളെ പള്ളിയിൽ നിന്നും തിരിച്ചുകളയുക. നിശ്ചയം, ഞാൻ ആർത്തവകാരികൾക്കും, വലിയ അശുദ്ധിയുള്ളവർക്കും പള്ളി അനുവദനിയമാക്കിയിട്ടില്ല. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 237, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى، وَعَلَيْهِ مِرْطٌ بَعْضُهُ عَلَيْهِ، وَعَلَيْهَا بَعْضُهُ وَهِيَ حَائِضٌ. (د,جه)', 'മൈമൂന(റ): നബി(സ) താൻ ധരിച്ച വസ്ത്രത്തിന്റെ ഒരു ഭാഗം തന്റെ മേലും ഒരുഭാഗം ആർത്തവകാരിയായ തന്റെ ഭാര്യയായ മൈമൂന(റ)യുടെ മേലുമായിരിക്കെ നമസ്കരിച്ചു. (ദ,ജ)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَاخْتَبَأَتْ مَوْلَاةٌ لَهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَاضَتْ؟". فَقَالَتْ: نَعَمْ، فَشَقَّ لَهَا مِنْ عِمَامَتِهِ، فَقَالَ: "اخْتَمِرِي بِهَذَا". (جه)', 'ആഇശ(റ): നബി(സ) ആഇശ(റ)യുടെ അടുത്ത് വന്നു. അപ്പോൾ അവരുടെ ഒരു അടിമസ്ത്രീ മറഞ്ഞുനിന്നു. നബി(സ) ചോദിച്ചു: "അവൾക്ക് ആർത്തവമുണ്ടായോ?" അവർ പറഞ്ഞു: അതെ. അപ്പോൾ നബിയുടെ തലപ്പാവിൽ നിന്നും (ഒരു ഭാഗം) അവൾക്ക് കീറിക്കൊടുത്തുകൊണ്ട് പറഞ്ഞു: "ഇതുകൊണ്ട് നീ മുഖമക്കന ധരിക്കുക. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَقْبَلُ اللهُ صَلَاةَ حَائِضٍ إِلَّا بِخِمَارٍ". (د,ت,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "പ്രായപൂർത്തിയായവളുടെ നിസ്കാരം മുഖമക്കനയില്ലാതെ അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ مُعَاذَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً سَأَلَتْ عَائِشَةَ قَالَتْ: تَخْتَضِبُ الْحَائِضُ؟ فَقَالَتْ: قَدْ كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَخْتَضِبُ، فَلَمْ يَكُنْ يَنْهَانَا عَنْهُ. (جه)', 'മുആദ(റ): ഒരു സ്ത്രീ ആഇശ(റ)യോട് ചോദിച്ചു: ആർത്തവകാരിക്ക് മൈലാഞ്ചിയിടാമോ? അവർ പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യോടൊപ്പമായിരിക്കുമ്പോൾ മൈലാഞ്ചിയിടാറുണ്ടായിരുന്നു. അതിൽനിന്ന് നബി(സ) ഞങ്ങളെ വിലക്കിയിരുന്നില്ല. (ജ)', 'مُعَاذَةَ', 'മുആദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 238, 238, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اغْتَسَلَ مِنْ جَنَابَةٍ، فَرَأَى لُمْعَةً لَمْ يُصِبْهَا الْمَاءُ، فَقَالَ بِجُمَّتِهِ فَبَلَّهَا عَلَيْهَا. وَفِي رِوَايَةٍ: فَعَصَرَ شَعْرَهُ عَلَيْهَا. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ജനാബത്തു കുളിക്കുകയും പിന്നെ വെള്ളമെത്താത്ത ഒരു സ്ഥലം കാണുകയും ചെയ്തപ്പോൾ ആ ഭാഗം തന്റെ മുടി കൊണ്ട് നനച്ചു. ഒരു റിപ്പോർട്ടിൽ: നബി അതിന്റെമേൽ മുടി പിടിച്ച് പിഴിഞ്ഞു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=13 and h.hadith_no=172), 1, 'وَفِي رِوَايَةٍ: فَعَصَرَ شَعْرَهُ عَلَيْهَا. [ز: في إسناده ضعيف] (جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي اغْتَسَلْتُ مِنَ الْجَنَابَةِ، وَصَلَّيْتُ الْفَجْرَ، ثُمَّ أَصْبَحْتُ، فَرَأَيْتُ قَدْرَ مَوْضِعِ الظُّفْرِ لَمْ يُصِبْهُ الْمَاءُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ كُنْتَ مَسَحْتَ عَلَيْهِ بِيَدِكَ أَجْزَأَكَ". [ز: في إسناده ضعيف] (جه)', 'അലി(റ): ഒരാൾ നബി(സ)യുടെയടുത്തുവന്ന് പറഞ്ഞു: ഞാൻ ജനാബത്തു കുളി കുളിക്കുകയും സുബ്ഹി നിസ്കരിക്കുകയും ചെയ്തു. നേരംപുലർന്നപ്പോൾ ഒരു നഖത്തിന്റത്ര വലുപ്പത്തിൽ ഒരുഭാഗം നനയാത്തതായി കണ്ടു. നബി(സ) പറഞ്ഞു: "നീ ആ ഭാഗത്ത് കൈകൊണ്ട് തടവിയിരുന്നെങ്കിൽ അതു മതിയാവുമായിരുന്നു." [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عِكْرِمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ أُمُّ حَبِيبَةَ تُسْتَحَاضُ، فَكَانَ زَوْجُهَا يَغْشَاهَا. (د)', 'ഇക്രിമ(റ): ഉമ്മുഹബീബ(റ)ക്ക് രക്തസ്രാവമുണ്ടാവുമ്പോൾ അവരുടെ ഭർത്താവ് അവരെ ആലിംഗനം ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'عِكْرِمَةَ', 'ഇക്രിമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ حَمْنَةَ بِنْتِ جَحْشٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ مُسْتَحَاضَةً، وَكَانَ زَوْجُهَا يُجَامِعُهَا. (د)', 'ഹംന ബിൻത് ജഹ്ശ്(റ): അവർക്ക് രക്തസ്രാവമുണ്ടായിരിക്കെ അവരുടെ ഭർത്താവ് അവരുമായി സംഭോഗം ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'حَمْنَةَ بِنْتِ جَحْشٍ', 'ഹംന ബിൻത് ജഹ്ശ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: اسْتَفْتَتْ أُمُّ حَبِيبَةَ ابْنَةُ جَحْشٍ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي أُسْتَحَاضُ فَلَا أَطْهُرُ، أَفَأَدَعُ الصَّلَاةَ؟ فَقَالَ: "لَا، إِنَّمَا ذَلِكَ عِرْقٌ، فَاغْتَسِلِي ثُمَّ صَلِّي". فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): ജഹ്ശിന്റെ പുത്രി ഉമ്മുഹബീബ പ്രവാചകനോട് ചോദിച്ചു: എനിക്ക് രക്ത സ്രാവമുണ്ടാവാറുണ്ട്. പക്ഷെ ശുദ്ധി ഉണ്ടാവാറില്ല. ഞാൻ നിസ്കാരം ഒഴിവാക്കട്ടെ?. പ്രവാചകൻ പറഞ്ഞു: "പറ്റില്ല, അത് ഒരു സ്രവം മാത്രമാണ്. നീ കുളിക്കുക. എന്നിട്ട് നിസ്കരിക്കുകയും ചെയ്യുക." അവർ എല്ലാ നിസ്കാരത്തിനും കുളിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 239, 239, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ مُعَاذَةَ: أَنَّ امْرَأَةً سَأَلَتْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَتَقْضِي إِحْدَانَا صَلَاتَهَا أَيَّامَ مَحِيضِهَا؟ فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ قَدْ كَانَتْ إِحْدَانَا تَحِيضُ فَلَا تُؤْمَرُ بِقَضَاءٍ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'മുആദ(റ): ഒരു സ്ത്രീ ആഇശ(റ)യോട് ചോദിച്ചു: ആർത്തവകാലത്തുള്ള നിസ്കാരം സ്ത്രീ വീണ്ടെടുക്കേണ്ടതുണ്ടോ?. ആഇശ(റ) ചോദിച്ചു: നീ ഖവാരിജുകളിൽ പെട്ടവളാണോ?. ഞങ്ങളൊക്കെ ആർത്തവകാരികളാകാറുണ്ടായിരുന്നു. പക്ഷെ വീണ്ടെടുക്കാൻ കൽപിക്കപ്പെട്ടിരുന്നില്ല. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'مُعَاذَةَ', 'മുആദ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 239, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ فَاطِمَةَ بِنْتِ الْمُنْذِرِ، عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، رَضِيَ اللهُ عَنْهُمْ: أَنَّ امْرَأَةً سَأَلَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الثَّوْبِ يُصِيبُهُ الدَّمُ مِنَ الْحَيْضَةِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حُتِّيهِ، ثُمَّ اقْرُصِيهِ بِالْمَاءِ، ثُمَّ رُشِّيهِ وَصَلِّي فِيهِ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂബക്കറിന്റെ പുത്രി അസ്മ(റ)യിൽ നിന്ന് മുൻദിറിന്റെ പുത്രി ഫാത്വിമ(റ): ആർത്തവ രക്തം പുരണ്ട വസ്ത്രത്തെപ്പറ്റി പ്രവാചകനോട് ഒരു സ്ത്രീ ചോദിച്ചു. പ്രവാചകൻ പറഞ്ഞു: അത് ചുരണ്ടിക്കളയുക. പിന്നെ വെള്ളമുപയോഗിച്ച് തേച്ചുരക്കുക. പിന്നീട് വെള്ളം കുടയുകയും അതുപയോഗിച്ച് നിസ്കരിക്കുകയും ചെയ്യുക. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,തു)', 'فَاطِمَةَ بِنْتِ الْمُنْذِرِ، عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ،', 'അബൂബക്കറിന്റെ പുത്രി അസ്മ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 240, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَاوِلِينِي الْخُمْرَةَ مِنَ الْمَسْجِدِ". قَالَتْ: قُلْتُ: إِنِّي حَائِضٌ. قَالَ: "إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ആഇശ(റ): പ്രവാചകൻ(സ) എന്നോട് പറഞ്ഞു: പള്ളിയിൽ നിന്ന് ആ മുസ്വല്ല എടുക്കുക." ഞാൻ പറഞ്ഞു: ''ഞാനാർത്തവകാരിയാണ്''. പ്രവാചകൻ പറഞ്ഞു: "നിന്റെ ആർത്തവം നിന്റെ കയ്യിലല്ല." ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു.(ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 240, 240, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
